const LanguageContext = createContext({ language: 'en', setLanguage: () => {}, t: (key) => key });
const useLanguage = () => useContext(LanguageContext);

function _t(dict, path) {
  return path.split('.').reduce((acc, k) => (acc && acc[k] !== undefined ? acc[k] : undefined), dict);
}

const LanguageProvider = ({ children }) => {
  const [language, setLanguageState] = useState(() => {
    try { return localStorage.getItem('snapsa_language') || 'en'; } catch { return 'en'; }
  });
  const setLanguage = (lang) => {
    setLanguageState(lang);
    try { localStorage.setItem('snapsa_language', lang); } catch {}
  };
  const t = useCallback((key) => {
    const v = _t(TRANSLATIONS[language], key);
    if (v !== undefined) return v;
    const fallback = _t(TRANSLATIONS.en, key);
    return fallback !== undefined ? fallback : key;
  }, [language]);
  return <LanguageContext.Provider value={{ language, setLanguage, t }}>{children}</LanguageContext.Provider>;
};


class ScreenErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { hasError: false, msg: '' }; }
  static getDerivedStateFromError(error) { return { hasError: true, msg: String(error?.message || error).slice(0, 200) }; }

  componentDidCatch(error, info) {
    console.error('[Snapsa] screen crashed:', error, info?.componentStack);
  }
  handleRetry = () => this.setState({ hasError: false });
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:14, padding:32, background:'#0B0B14' }}>
          <AlertCircle size={40} style={{ color:'#6B7280' }}/>
          <p style={{ color:'white', fontWeight:700, fontSize:15, textAlign:'center' }}>Something went wrong loading this screen</p>
          {this.state.msg ? <p style={{ color:'#9CA3AF', fontSize:11, textAlign:'center', wordBreak:'break-word' }}>{this.state.msg}</p> : null}

          <button onClick={this.handleRetry}
            style={{ padding:'10px 24px', borderRadius:999, background:'#FF2055', border:'none', color:'white', fontWeight:700, fontSize:13, cursor:'pointer' }}>
            Try again
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

