// The Snapsa coin artwork (public/SnapsaCoin.png), used everywhere the coin shows.
const SnapCoin = ({ size = 16, style }) => <img src="/SnapsaCoin.png" alt="" aria-hidden="true" style={{ width:size, height:size, objectFit:'contain', display:'inline-block', verticalAlign:'-0.15em', ...style }}/>;

// Shown while the feed loads, so there is always something to watch: the SNAPSA ad.
// The SNAPSA ad with sound, like any other video. Phones only allow sound after a
// tap, so if the browser refuses sound at the start, the ad plays muted and the
// first tap turns the sound on. The feed still waits until the ad has finished.
const SnapsaAdVideo = ({ onEnded, style, loop = false }) => {
  const ref = useRef(null);
  const [fail, setFail] = useState('');      // why the ad could not play (shown small, so we can see the cause)
  const [buffering, setBuffering] = useState(true);
  useEffect(() => {
    const v = ref.current;
    if (!v) return;
    let unmute = null;
    v.muted = false;
    v.play().catch((err) => {
      // Sound not allowed before a tap -> play muted; a tap turns the sound on.
      if (err && err.name === 'NotSupportedError') { setFail('NotSupported (file missing or codec)'); onEnded?.(); return; }
      v.muted = true;
      v.play().catch((e2) => { setFail(e2?.name || 'play failed'); onEnded?.(); });
      unmute = () => { v.muted = false; v.play().catch(() => {}); };
      window.addEventListener('pointerdown', unmute, { once: true });
    });
    return () => { if (unmute) window.removeEventListener('pointerdown', unmute); };
  }, []);
  const code = (e) => {
    const er = e?.target?.error;
    setFail(er ? `media error ${er.code}${er.code === 4 ? ' (file missing or format not supported)' : ''}` : 'video error');
    onEnded?.();
  };
  return (
    <>
      <video ref={ref} src="/SnapsaAd.mp4" playsInline preload="auto" loop={loop}
        onLoadStart={() => setBuffering(true)} onWaiting={() => setBuffering(true)}
        onCanPlay={() => setBuffering(false)} onPlaying={() => { setBuffering(false); setFail(''); }}
        onEnded={() => onEnded?.()} onError={code} style={style}/>
      {(fail || buffering) && (
        <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:10, pointerEvents:'none', background: fail ? '#000' : 'transparent' }}>
          {fail && <img src="/SnapsaHub.png" alt="Snapsa" style={{ height:48, width:'auto', opacity:.9 }} onError={e => { e.target.style.display = 'none'; }}/>}
          <span style={{ color:'rgba(255,255,255,.55)', fontSize:11, fontWeight:600 }}>
            {fail ? `Ad unavailable — ${fail}` : 'Loading ad…'}
          </span>
        </div>
      )}
    </>
  );
};


// Snapsa neon loading ring — shown over a video's thumbnail while its data is still arriving
const NeonLoader = ({ size = 54, label }) => (
  <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:10 }}>
    <div style={{ width:size, height:size, borderRadius:'50%', border:'3px solid rgba(180,76,255,.18)', borderTopColor:'#ff2d95', borderRightColor:'#b44cff', boxShadow:'0 0 18px rgba(180,76,255,.55), 0 0 36px rgba(255,45,149,.3)', animation:'snapsaNeonSpin .9s linear infinite' }}/>
    {label && <span style={{ color:'rgba(255,255,255,.7)', fontSize:12, fontWeight:700, letterSpacing:.4 }}>{label}</span>}
    <style>{'@keyframes snapsaNeonSpin{to{transform:rotate(360deg)}}'}</style>
  </div>
);

// Plays once per session, as a normal slide between videos (never as a gate before the feed)
const HouseAdSlide = ({ active }) => {
  return (
    <div style={{ width:'100%', height:'100%', background:'#000', position:'relative', overflow:'hidden' }}>
      {active ? <SnapsaAdVideo loop={false} onEnded={() => {}} style={{ position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover' }}/> : <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center' }}><NeonLoader/></div>}
      <div style={{ position:'absolute', left:16, bottom:118, display:'flex', alignItems:'center', gap:6, pointerEvents:'none' }}>
        <span style={{ color:SNAPSA_VERIFIED_PINK, fontWeight:800, fontSize:15, letterSpacing:.6 }}>SNAPSA</span>
        <SnapsaVerifiedBadge size={15}/>
        <span style={{ color:'rgba(255,255,255,.7)', fontSize:11, fontWeight:700 }}>(Ad)</span>
      </div>
    </div>
  );
};

let _snapsaAdWatched = false;
let _snapsaHouseAdShown = false;

// The ad is optional. It plays while the feed loads; a small arrow at the bottom shows
// "Loading feed…" and, once the feed is ready, turns into "Swipe up for next video".
const SnapsaAdLoader = ({ ready, onDone }) => {
  const [ended, setEnded] = useState(false);
  const [likes, setLikes] = useState(0);
  const [liked, setLiked] = useState(false);
  const touchY = useRef(null);
  const doneRef = useRef(false);
  const finish = () => { if (!doneRef.current) { doneRef.current = true; onDone?.(); } };

  useEffect(() => {
    snapFetch('/snapsa/ads/snapsa').then(r => r.ok ? r.json() : null)
      .then(d => { if (d) { setLikes(d.likes || 0); setLiked(!!d.liked); } }).catch(() => {});
  }, []);

  // Feed ready and the ad has played through: move on by itself after a moment.
  useEffect(() => {
    if (!(ready && ended)) return;
    const t = setTimeout(finish, 4000);
    return () => clearTimeout(t);
  }, [ready, ended]);

  const toggleLike = async (e) => {
    e?.stopPropagation();
    const next = !liked;
    setLiked(next); setLikes(n => Math.max(0, n + (next ? 1 : -1)));
    try {
      const res = await snapFetch('/snapsa/ads/snapsa/like', { method: 'POST' });
      if (!res.ok) throw new Error('like failed');
      const d = await res.json();
      setLiked(!!d.liked); setLikes(d.likes || 0);
    } catch { setLiked(!next); setLikes(n => Math.max(0, n + (next ? -1 : 1))); }
  };

  const onTouchStart = (e) => { touchY.current = e.touches[0].clientY; };
  const onTouchEnd = (e) => {
    if (touchY.current == null) return;
    const dy = touchY.current - e.changedTouches[0].clientY;
    touchY.current = null;
    if (dy > 60 && ready) finish();
  };
  const onWheel = (e) => { if (e.deltaY > 40 && ready) finish(); };

  return (
    <div onTouchStart={onTouchStart} onTouchEnd={onTouchEnd} onWheel={onWheel}
      style={{ width:'100%', height:'100svh', background:'#000', position:'relative', overflow:'hidden' }}>
      <SnapsaAdVideo loop={!ready} onEnded={() => setEnded(true)} style={{ position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover' }}/>
      <div style={{ position:'absolute', inset:0, background:'linear-gradient(180deg, rgba(0,0,0,0) 50%, rgba(0,0,0,0.8) 100%)', pointerEvents:'none' }}/>

      <div style={{ position:'absolute', left:16, right:86, bottom:118, display:'flex', flexDirection:'column', gap:3, pointerEvents:'none' }}>
        <div style={{ display:'flex', alignItems:'center', gap:6 }}>
          <span style={{ color:SNAPSA_VERIFIED_PINK, fontWeight:800, fontSize:15, letterSpacing:0.6 }}>SNAPSA</span>
          <SnapsaVerifiedBadge size={15}/>
        </div>
        <span style={{ color:'rgba(255,255,255,0.7)', fontSize:11, fontWeight:700, letterSpacing:0.4 }}>(Ad)</span>
      </div>

      {/* Like the ad */}
      <div style={{ position:'absolute', right:12, bottom:130, display:'flex', flexDirection:'column', alignItems:'center', gap:4 }}>
        <button onClick={toggleLike} aria-label="Like this ad"
          style={{ width:46, height:46, borderRadius:'50%', border:'none', cursor:'pointer', background:'rgba(255,255,255,0.12)', display:'flex', alignItems:'center', justifyContent:'center' }}>
          <svg width="26" height="26" viewBox="0 0 24 24" fill={liked ? '#ff2a5f' : 'none'} stroke={liked ? '#ff2a5f' : 'white'} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8l1 1.1L12 21l7.8-7.5 1-1.1a5.5 5.5 0 0 0 0-7.8z"/>
          </svg>
        </button>
        <span style={{ color:'white', fontSize:12, fontWeight:700 }}>{likes}</span>
      </div>

      {/* Skip, only once the feed is ready */}
      {ready && (
        <button onClick={finish}
          style={{ position:'absolute', top:'max(16px, var(--sat, env(safe-area-inset-top, 0px)))', right:14, padding:'7px 14px', borderRadius:16, border:'none', background:'rgba(0,0,0,0.5)', color:'white', fontSize:12, fontWeight:700, cursor:'pointer' }}>
          Skip
        </button>
      )}

      {/* Bottom-centre: loading feed (arrow down + wave)  ->  swipe up (arrow up) */}
      <div style={{ position:'absolute', left:0, right:0, bottom:78, display:'flex', flexDirection:'column', alignItems:'center', gap:5, pointerEvents:'none' }}>
        <div style={{ animation: ready ? 'adArrowUp 1.3s ease-in-out infinite' : 'adArrowDown 1.3s ease-in-out infinite' }}>
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
            style={{ display:'block', transition:'transform .45s ease', transform: ready ? 'rotate(180deg)' : 'rotate(0deg)' }}>
            <polyline points="6 9 12 15 18 9"/>
          </svg>
        </div>
        {!ready && (
          <div style={{ display:'flex', gap:3, alignItems:'center', height:12 }}>
            {[0,1,2,3,4].map(i => (
              <span key={i} style={{ width:3, height:12, borderRadius:2, background:'rgba(255,255,255,0.85)', transformOrigin:'center', animation:`adWave 1s ease-in-out ${i*0.12}s infinite` }}/>
            ))}
          </div>
        )}
        <span style={{ color:'rgba(255,255,255,0.85)', fontSize:12, fontWeight:700, letterSpacing:0.3, textShadow:'0 1px 3px rgba(0,0,0,0.6)' }}>
          {ready ? 'Swipe up for next video' : 'Loading feed…'}
        </span>
      </div>

      <style>{`
        @keyframes adArrowDown { 0%,100%{transform:translateY(0)} 50%{transform:translateY(6px)} }
        @keyframes adArrowUp   { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-6px)} }
        @keyframes adWave      { 0%,100%{transform:scaleY(.35)} 50%{transform:scaleY(1)} }
      `}</style>
    </div>
  );
};

const makeWatermarkOverlay = async (username, opts = {}) => {
  try {
    const name = String(username || '').replace(/^@/, '').trim().slice(0, 40);
    if (!name || typeof document === 'undefined') return '';
    const loadImg = (src, cors) => new Promise((res, rej) => { const i = new Image(); if (cors) i.crossOrigin = 'anonymous'; i.onload = () => res(i); i.onerror = rej; i.src = src; });
    // Who is posting: avatar + verified badge (own profile, fetched once)
    let avatarUrl = opts.avatarUrl || null, verified = opts.verified;
    let crew = opts.crew, official = opts.official;
    if (avatarUrl == null || verified == null || crew == null || official == null) {
      try {
        const r = await snapFetchNetwork('/snapsa/me'); const d = r.ok ? await r.json() : null; const p = d?.profile || {};
        if (avatarUrl == null) avatarUrl = p.avatarUrl || null;
        if (verified == null) verified = !!(p.tier === 'snapsa' || p.snapsaVerified || p.verified || p.wernTier || p.officialLabel || p.crewPosition);
        if (crew == null) crew = p.crewPosition ? 'CREW' : '';
        if (official == null) official = p.officialLabel || '';
      } catch {}
    }
    let logoImg = null, avatarImg = null;
    try { logoImg = await loadImg('/SnapsaWatermark.png'); } catch {}
    if (avatarUrl) { try { avatarImg = await loadImg(mediaHref(avatarUrl), true); } catch {} }

    // Picture is 728px wide: the server uses that width to know this is the new layout
    // (top 83% = corner watermark, whole picture = the end screen with "DISCOVER ON SNAPSA").
    const W = 728;
    const lh = logoImg ? Math.round(W * logoImg.naturalHeight / logoImg.naturalWidth) : 90;
    const rowH = 118, gap = 14;
    crew = crew || ''; official = official || '';
    const offH = official ? 58 : 0;
    const mainH = lh + gap + rowH + offH + 12;
    const H = Math.ceil(mainH / 0.83);
    const canvas = document.createElement('canvas');
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext('2d');
    ctx.shadowColor = 'rgba(0,0,0,0.65)'; ctx.shadowBlur = 8; ctx.shadowOffsetX = 1; ctx.shadowOffsetY = 1;
    if (logoImg) ctx.drawImage(logoImg, 0, 0, W, lh);
    else { ctx.fillStyle = '#fff'; ctx.font = '900 84px system-ui, sans-serif'; ctx.textAlign = 'left'; ctx.textBaseline = 'top'; ctx.fillText('SNAPSA', 0, 0); }

    // Row: [avatar] name [badge], centred
    ctx.font = '700 58px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
    const nameW = Math.min(ctx.measureText(name).width, W - 230);
    const av = 98, badge = verified ? 50 : 0, g1 = 22, g2 = verified ? 14 : 0;
    const crewH = Math.round(badge * 0.8), crewW = crew ? Math.round(crewH * 2.6) : 0, g3 = crew ? 12 : 0;
    const rowW = av + g1 + nameW + g3 + crewW + g2 + badge;
    let x = Math.max(10, (W - rowW) / 2);
    const cy = lh + gap + rowH / 2;
    // avatar with white ring
    ctx.save();
    ctx.beginPath(); ctx.arc(x + av / 2, cy, av / 2, 0, Math.PI * 2); ctx.closePath();
    ctx.fillStyle = '#ffffff'; ctx.fill();
    ctx.beginPath(); ctx.arc(x + av / 2, cy, av / 2 - 5, 0, Math.PI * 2); ctx.closePath(); ctx.clip();
    if (avatarImg) ctx.drawImage(avatarImg, x + 5, cy - av / 2 + 5, av - 10, av - 10);
    else { ctx.fillStyle = '#7C3AED'; ctx.fillRect(x, cy - av / 2, av, av); ctx.fillStyle = '#fff'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.shadowColor = 'transparent'; ctx.fillText((name[0] || 'S').toUpperCase(), x + av / 2, cy + 3); }
    ctx.restore();
    x += av + g1;
    // name
    ctx.fillStyle = '#ffffff'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.font = '700 58px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
    ctx.fillText(name, x, cy + 2, nameW);
    x += nameW + g3;
    if (crew) {
      ctx.save(); ctx.shadowColor = 'rgba(255,90,0,0.9)'; ctx.shadowBlur = 10;
      const pg = ctx.createLinearGradient(x, 0, x + crewW, 0); pg.addColorStop(0, '#ff9a1f'); pg.addColorStop(0.55, '#ff4d00'); pg.addColorStop(1, '#d61a00');
      ctx.fillStyle = pg; ctx.beginPath(); ctx.roundRect ? ctx.roundRect(x, cy - crewH / 2, crewW, crewH, crewH / 2) : ctx.rect(x, cy - crewH / 2, crewW, crewH); ctx.fill();
      ctx.shadowColor = 'transparent'; ctx.fillStyle = '#fff'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.font = `900 ${Math.round(crewH * 0.58)}px system-ui, sans-serif`;
      try { ctx.letterSpacing = '2px'; } catch {}
      ctx.fillText('CREW', x + crewW / 2 + 1, cy + 1); try { ctx.letterSpacing = '0px'; } catch {}
      ctx.restore(); ctx.textAlign = 'left';
    }
    x += crewW + g2;
    // verified badge (pink scalloped seal with a white tick)
    if (verified) {
      ctx.save(); ctx.translate(x, cy - badge / 2); ctx.scale(badge / 24, badge / 24);
      ctx.fillStyle = '#D81B60'; ctx.fill(new Path2D('M12 2l2.4 1.4 2.7-.4 1.3 2.4 2.4 1.4-.4 2.7L22 12l-1.6 2.5.4 2.7-2.4 1.4-1.3 2.4-2.7-.4L12 22l-2.4-1.4-2.7.4-1.3-2.4-2.4-1.4.4-2.7L2 12l1.6-2.5-.4-2.7 2.4-1.4 1.3-2.4 2.7.4L12 2z'));
      ctx.shadowColor = 'transparent'; ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      ctx.stroke(new Path2D('M8.4 12.4l2.4 2.4 4.8-5'));
      ctx.restore();
    }
    if (official) {
      ctx.save(); ctx.shadowColor = 'transparent';
      const ph = 36; ctx.font = '900 21px system-ui, sans-serif'; try { ctx.letterSpacing = '3px'; } catch {}
      const pw = Math.ceil(ctx.measureText(String(official).toUpperCase()).width) + 36, px = (W - pw) / 2, py = lh + gap + rowH + 4;
      const og = ctx.createLinearGradient(px, 0, px + pw, 0); og.addColorStop(0, '#39ff14'); og.addColorStop(1, '#00e5ff');
      ctx.fillStyle = og; ctx.beginPath(); ctx.roundRect ? ctx.roundRect(px, py, pw, ph, ph / 2) : ctx.rect(px, py, pw, ph); ctx.fill();
      ctx.fillStyle = '#0a0014'; official = String(official).toUpperCase(); ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(official, W / 2 + 1, py + ph / 2 + 1);
      ctx.restore();
    }
    // "DISCOVER ON SNAPSA" (only visible on the end screen — the server crops it off the corner mark)
    ctx.save();
    ctx.shadowColor = 'transparent';
    const bandMid = mainH + (H - mainH) / 2;
    const grad = ctx.createLinearGradient(0, 0, W, 0); grad.addColorStop(0, '#ff4fd8'); grad.addColorStop(1, '#a855f7');
    ctx.fillStyle = grad; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.font = '600 50px "Courier New", ui-monospace, Menlo, monospace';
    try { ctx.letterSpacing = '5px'; } catch {}
    ctx.fillText('DISCOVER ON SNAPSA', W / 2, bandMid, W - 20);
    ctx.restore();
    return canvas.toDataURL('image/png').split(',')[1] || '';
  } catch { return ''; }
};
 
const snapFetchNetwork = (path, opts = {}) => {
  
  opts = { cache: 'no-store', ...opts };

  const token = getSnapToken();
  return fetch(`${SNAP_URL}${path}`, {
    ...opts,
    headers: {
      ...(token ? { 'Authorization': `Bearer ${token}` } : {}),
      ...(opts.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }),
      ...(opts.headers || {}),
    },
  }).then(res => {
    // A suspended/barred account gets a 403 with a code on every request —
    // surface it once so the whole app can show the restriction screen.
    if (res.status === 423) { try { window.dispatchEvent(new CustomEvent('snapsa:lockdown')); } catch {} }
    if (res.status === 403) {
      res.clone().json().then(b => {
        if (b?.code === 'ACCOUNT_SUSPENDED' || b?.code === 'ACCOUNT_BARRED') {
          window.dispatchEvent(new CustomEvent('snapsa:accountRestricted', { detail: b }));
        }
      }).catch(() => {});
    }
    return res;
  });
};
// ─── Transfer indicators: upload = blue ↑ bar, download = green ↓ bar ───────────────
// Uploads and downloads run in the background; their progress shows in these small
// bars at the top of the app instead of a screen or popup that blocks everything.
const _transfer = { up: { active: false, pct: 0, phase: '', label: '' }, down: { active: false, pct: 0, phase: '', label: '' } };
const _transferTimers = {};
const _emitTransfer = () => { try { window.dispatchEvent(new CustomEvent('snapsa:transfer')); } catch {} };
const transferSet = (kind, patch) => { _transfer[kind] = { ..._transfer[kind], ...patch }; _emitTransfer(); };
const transferBusy = (kind) => _transfer[kind].active && _transfer[kind].phase !== 'done' && _transfer[kind].phase !== 'error';
const transferFinish = (kind, ok, label) => {
  clearTimeout(_transferTimers[kind]);
  transferSet(kind, { active: true, pct: ok ? 100 : _transfer[kind].pct, phase: ok ? 'done' : 'error', label: label || '' });
  _transferTimers[kind] = setTimeout(() => transferSet(kind, { active: false, pct: 0, phase: '', label: '' }), ok ? 2500 : 5000);
};
const useTransfers = () => {
  const [, force] = useState(0);
  useEffect(() => {
    const h = () => force(n => n + 1);
    window.addEventListener('snapsa:transfer', h);
    return () => window.removeEventListener('snapsa:transfer', h);
  }, []);
  return _transfer;
};

// Real upload progress (fetch can't report it, XMLHttpRequest can).
const snapXhrUploadWithPhase = (path, formData, onProgress) => new Promise((resolve, reject) => {
  const xhr = new XMLHttpRequest();
  xhr.open('POST', `${SNAP_URL}${path}`);
  const token = getSnapToken();
  if (token) xhr.setRequestHeader('Authorization', `Bearer ${token}`);
  xhr.upload.onprogress = (e) => { if (e.lengthComputable) onProgress?.(Math.min(99, Math.round((e.loaded / e.total) * 100)), 'sending'); };
  xhr.upload.onload = () => onProgress?.(100, 'processing'); // all bytes sent — the server is now preparing the video
  xhr.onerror = () => reject(new Error('Network error while uploading'));
  xhr.onload = () => {
    let data = null; try { data = JSON.parse(xhr.responseText); } catch {}
    resolve({ ok: xhr.status >= 200 && xhr.status < 300, status: xhr.status, data });
  };
  xhr.send(formData);
});

// Runs after the screen has closed, so it must not depend on any screen state.
const startBackgroundUpload = async (formData, { name = 'Video', showToast, afterOk } = {}) => {
  clearTimeout(_transferTimers.up);
  transferSet('up', { active: true, pct: 0, phase: 'sending', label: name });
  try {
    const r = await snapXhrUploadWithPhase('/snapsa/videos/upload', formData, (pct, phase) => transferSet('up', { pct, phase }));
    if (!r.ok) throw new Error(r.data?.error || `Upload failed (${r.status})`);
    transferFinish('up', true, 'Posted');
    showToast?.(`📹 "${name}" posted!`, 'success');
    try { await afterOk?.(r.data); } catch {}
    return true;
  } catch (e) {
    transferFinish('up', false, 'Failed');
    showToast?.(e?.message || 'Upload failed', 'error');
    return false;
  }
};

const startBackgroundSave = async (video, showToast) => {
  clearTimeout(_transferTimers.down);
  transferSet('down', { active: true, pct: 1, phase: 'sending', label: video?.authorName || 'Video' });
  try {
    const { saveVideoToDevice } = await import('./videoSave.js');
    await saveVideoToDevice({
      videoId: video.id, authorName: video.authorName, snapUrl: SNAP_URL, authToken: getSnapToken(),
      onProgress: (pct) => transferSet('down', { pct: Math.max(1, Math.min(99, Math.round(pct))), phase: pct >= 80 ? 'processing' : 'sending' }),
    });
    transferFinish('down', true, 'Saved');
    showToast?.('✅ Video saved!', 'success');
  } catch (err) {
    console.error('[Save]', err);
    transferFinish('down', false, 'Failed');
    showToast?.(`❌ Could not save video${err?.message ? ': ' + err.message : ''}`, 'error');
  }
};

const TransferBars = ({ floating = false }) => {
  const tr = useTransfers();
  const items = [
    { key: 'up',   color: '#3B82F6', t: tr.up },
    { key: 'down', color: '#22C55E', t: tr.down },
  ].filter(i => i.t.active);
  if (!items.length) return null;
  const box = floating
    ? { position: 'fixed', top: 'calc(var(--sat, env(safe-area-inset-top, 0px)) + 8px)', right: 10, zIndex: 400 }
    : { position: 'absolute', right: 12, bottom: 8, zIndex: 25 };
  return (
    <div style={{ ...box, display: 'flex', gap: 14, background: 'rgba(0,0,0,.55)', padding: '4px 10px', borderRadius: 12, pointerEvents: 'none' }}>
      {items.map(({ key, color, t }) => {
        const err = t.phase === 'error';
        const text = err ? 'Failed' : t.phase === 'done' ? '✓ Done' : (key === 'up' && t.phase === 'processing') ? 'Processing…' : `${t.pct}%`;
        return (
          <div key={key} style={{ width: 92 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 4, color: err ? '#ef4444' : color, fontWeight: 800, fontSize: 13, lineHeight: 1.1 }}>
              <span style={{ fontSize: 16 }}>{key === 'up' ? '↑' : '↓'}</span>
              <span>{text}</span>
            </div>
            <div style={{ height: 4, borderRadius: 99, background: 'rgba(255,255,255,.18)', marginTop: 3, overflow: 'hidden' }}>
              <div style={{ height: '100%', width: `${err ? 100 : t.pct}%`, background: err ? '#ef4444' : color, transition: 'width .25s', animation: t.phase === 'processing' ? 'trPulse 1.1s ease-in-out infinite' : 'none' }} />
            </div>
          </div>
        );
      })}
      <style>{`@keyframes trPulse{0%,100%{opacity:1}50%{opacity:.45}}`}</style>
    </div>
  );
};

// Offline-first: saved copy offline / when the server is slow or down; refetch when online.
const SNAP_SLOW_MS = 6000;
const snapFetch = (path, opts = {}) => {
  const method = String(opts.method || 'GET').toUpperCase();
  if (method !== 'GET' || !apiCache.isCacheable(path)) return snapFetchNetwork(path, opts);

  const key = apiCache.keyFor(getSnapToken(), path);
  const fromCache = async () => {
    const rec = await apiCache.get(key);
    if (!rec) return null;
    apiCache.markStale(key, path);
    return apiCache.toResponse(rec);
  };
  const fromNetwork = () => snapFetchNetwork(path, opts).then((res) => {
    if (res.ok && (res.headers.get('content-type') || '').includes('json')) {
      res.clone().text().then((t) => apiCache.put(key, t, path)).catch(() => {});
    }
    return res;
  });

  // Offline: show what was fetched while online, without waiting on the network.
  if (typeof navigator !== 'undefined' && navigator.onLine === false) {
    return fromCache().then((hit) => hit || fromNetwork());
  }
  // Online: network first. If it fails, errors (5xx) or is very slow, show the saved copy.
  return new Promise((resolve, reject) => {
    let settled = false;
    const done = (fn, v) => { if (!settled) { settled = true; clearTimeout(timer); fn(v); } };
    const timer = setTimeout(() => { fromCache().then((hit) => { if (hit) done(resolve, hit); }); }, SNAP_SLOW_MS);
    fromNetwork().then(async (res) => {
      if (res.status >= 500) { const hit = await fromCache(); if (hit) return done(resolve, hit); }
      done(resolve, res);
    }).catch(async (err) => {
      if (err && err.name === 'AbortError') return done(reject, err);
      const hit = await fromCache();
      if (hit) done(resolve, hit); else done(reject, err);
    });
  });
};
apiCache.setRefetcher((p) => snapFetch(p));

// ─── Feed pre-warm cache ────────────────────────────────────────────────

const FEED_PREWARM_MS = 20000;
let _feedPrewarm = null; // { promise, token, ts, seed }

export function warmFeedCache(token) {
  if (!token) return;
  if (_feedPrewarm && _feedPrewarm.token === token && (Date.now() - _feedPrewarm.ts) < FEED_PREWARM_MS) {
    return; // already warm/warming for this token
  }
  const seed = Math.random();
  const promise = fetch(`${SNAP_URL}/snapsa/videos/feed?limit=3&skip=0&seed=${seed}`, {
    headers: { 'Authorization': `Bearer ${token}` },
  }).then(r => r.ok ? r.json() : null).catch(() => null);
  _feedPrewarm = { promise, token, ts: Date.now(), seed };
}

const consumeFeedPrewarm = (token) => {
  if (!_feedPrewarm || !token || _feedPrewarm.token !== token || (Date.now() - _feedPrewarm.ts) >= FEED_PREWARM_MS) {
    return null;
  }
  const entry = _feedPrewarm;
  _feedPrewarm = null; // one-shot — never reused on a later remount
  return entry;
};

const snapUploadWithProgress = (path, formData, { onProgress, timeoutMs = 3 * 60 * 1000 } = {}) => {
  const token = getSnapToken();
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('POST', `${SNAP_URL}${path}`);
    if (token) xhr.setRequestHeader('Authorization', `Bearer ${token}`);
    xhr.timeout = timeoutMs;

    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable && onProgress) onProgress(Math.round((e.loaded / e.total) * 100));
    };
    xhr.onload = () => {
      let json = {};
      try { json = xhr.responseText ? JSON.parse(xhr.responseText) : {}; } catch {}
      resolve({ ok: xhr.status >= 200 && xhr.status < 300, status: xhr.status, json });
    };
    xhr.onerror = () => reject(new Error('Network error — check your connection and try again'));
    xhr.ontimeout = () => reject(new Error('Upload timed out — check your connection and try again'));
    xhr.send(formData);
  });
};

 // ─── Rich text v2 + the DCE-07 code word ─────────────────────────────────────────
// "DCE-07" is shown as the founder's full name wherever text is displayed.
// WhatsApp-style: *bold*  _italic_  ~strike~  `code`  ```fenced code with js/jsx/css/html/json/py```
// + tappable links and @mentions
// + colour tags: *blue*any words you like*/*  (the word blue disappears; everything up to */* turns blue)
// + a heart emoji tints the whole message (❤️ red, 💗 pink, 💙 blue …)
// + tone words colour themselves (good → green, fault → red, warning → amber …)
// Built from plain React elements (no HTML injection), so user text can never run as code.
const DCE_CODE_RE = /\bDCE-07\b/gi;
const DCE_FULL_NAME = 'Frans Dominique Van Der Werndtz';
const expandAlias = (s) => (typeof s === 'string' ? s.replace(DCE_CODE_RE, DCE_FULL_NAME) : s);

// ── Heart tint: the FIRST heart in the message decides the colour of its text ──
const HEART_COLORS = {
  '❤': '#ff5a5f', '🧡': '#fb923c', '💛': '#facc15', '💚': '#4ade80', '💙': '#5aa9ff', '💜': '#c084fc',
  '🩷': '#ff8ad8', '💗': '#ff8ad8', '💖': '#ff8ad8', '💕': '#ff8ad8', '💓': '#ff8ad8', '💞': '#ff8ad8', '💘': '#ff8ad8',
  '🖤': '#9ca3af', '🤍': '#f3f4f6',
};
const HEART_RE = /❤️?|🧡|💛|💚|💙|💜|🩷|💗|💖|💕|💓|💞|💘|🖤|🤍/u;
const heartTint = (text) => {
  const m = HEART_RE.exec(text);
  return m ? HEART_COLORS[m[0].replace('️', '')] || null : null;
};

// ── Tone words (edit freely — lowercase, whole words only) ──
const TONE_GROUPS = [
  { color: '#4ade80', words: ['good', 'great', 'nice', 'awesome', 'excellent', 'perfect', 'success', 'passed', 'correct', 'goed', 'lekker', 'mooi', 'reg', 'sukses'] },
  { color: '#ff5a5f', words: ['fault', 'bad', 'error', 'fail', 'failed', 'wrong', 'broken', 'bug', 'crash', 'fout', 'sleg', 'gebreek', 'fout'] },
  { color: '#facc15', words: ['warning', 'careful', 'caution', 'wait', 'oppas', 'wag'] },
];
const TONE_MAP = {};
TONE_GROUPS.forEach(g => g.words.forEach(w => { TONE_MAP[w] = g.color; }));
const TONE_RE = new RegExp('(?<![A-Za-z0-9_])(' + Object.keys(TONE_MAP).sort((a, b) => b.length - a.length).join('|') + ')(?![A-Za-z0-9_])', 'gi');

// ── Tiny syntax highlighter for fenced code ──
const CODE_COLORS = { comment: '#7f8c9b', string: '#a5e075', number: '#f0a35e', keyword: '#d68cff', tag: '#ff7a85', attr: '#61afef', fn: '#e8c46a', plain: '#e6e9ef' };
const CODE_LANG_ALIAS = { javascript: 'js', jsx: 'js', ts: 'js', tsx: 'js', typescript: 'js', node: 'js', mjs: 'js', json: 'json', python: 'py', htm: 'html', xml: 'html', svg: 'html', scss: 'css', less: 'css', bash: 'sh', shell: 'sh', zsh: 'sh' };
const CODE_KEYWORDS = {
  js: 'const|let|var|function|return|if|else|for|while|do|import|export|from|default|class|extends|new|await|async|try|catch|finally|throw|switch|case|break|continue|typeof|instanceof|null|undefined|true|false|this|of|in|interface|type',
  py: 'def|class|return|if|elif|else|for|while|import|from|as|try|except|finally|raise|with|lambda|None|True|False|and|or|not|in|is|pass|yield|async|await',
  json: 'true|false|null',
  sh: 'if|then|else|fi|for|do|done|while|case|esac|function|echo|cd|export|sudo|npm|git',
};
const buildCodeRe = (lang) => {
  const parts = []; // [type, source]
  if (lang === 'js') parts.push(['comment', '\\/\\/[^\\n]*|\\/\\*[\\s\\S]*?\\*\\/']);
  else if (lang === 'py' || lang === 'sh') parts.push(['comment', '#[^\\n]*']);
  else if (lang === 'css') parts.push(['comment', '\\/\\*[\\s\\S]*?\\*\\/']);
  else if (lang === 'html') parts.push(['comment', '<!--[\\s\\S]*?-->']);
  parts.push(['string', '"(?:\\\\.|[^"\\\\\\n])*"|\'(?:\\\\.|[^\'\\\\\\n])*\'' + (lang === 'js' ? '|`(?:\\\\.|[^`\\\\])*`' : '')]);
  if (lang === 'js' || lang === 'html') parts.push(['tag', '<\\/?[A-Za-z][\\w.:-]*|\\/?>']);
  if (lang === 'css') parts.push(['number', '#[0-9a-fA-F]{3,8}\\b']);
  parts.push(['number', '\\b\\d+(?:\\.\\d+)?(?:px|em|rem|vh|vw|%|s|ms)?\\b']);
  if (CODE_KEYWORDS[lang]) parts.push(['keyword', '\\b(?:' + CODE_KEYWORDS[lang] + ')\\b']);
  if (lang === 'css') parts.push(['attr', '[a-zA-Z-]+(?=\\s*:)']);
  else if (lang === 'json') parts.push(['attr', '(?<=")[^"\\n]+(?="\\s*:)']);
  else if (lang === 'js' || lang === 'html') parts.push(['attr', '[A-Za-z_-]+(?==)']);
  if (lang === 'js' || lang === 'py' || lang === 'sh') parts.push(['fn', '\\b[A-Za-z_$][\\w$]*(?=\\()']);
  return { types: parts.map(p => p[0]), re: new RegExp(parts.map(p => '(' + p[1] + ')').join('|'), 'g') };
};
const highlightCode = (code, langRaw) => {
  const lang = CODE_LANG_ALIAS[langRaw] || langRaw;
  if (!['js', 'py', 'json', 'css', 'html', 'sh'].includes(lang)) return code;
  const { types, re } = buildCodeRe(lang);
  const out = []; let last = 0, m, k = 0;
  while ((m = re.exec(code)) !== null) {
    if (m[0] === '') { re.lastIndex++; continue; }
    if (m.index > last) out.push(code.slice(last, m.index));
    let gi = 1; while (gi < m.length && m[gi] === undefined) gi++;
    out.push(<span key={k++} style={{ color: CODE_COLORS[types[gi - 1]] }}>{m[0]}</span>);
    last = m.index + m[0].length;
  }
  if (last < code.length) out.push(code.slice(last));
  return out;
};
const CodeBlock = ({ code, lang }) => (
  <span style={{ display:'block', margin:'4px 0', background:'rgba(8,10,18,.82)', border:'1px solid rgba(255,255,255,.12)', borderRadius:10, overflow:'hidden', maxWidth:'100%' }}>
    <span style={{ display:'flex', alignItems:'center', justifyContent:'space-between', padding:'3px 10px', background:'rgba(255,255,255,.07)', fontSize:10, fontWeight:700, letterSpacing:.5, color:'#9aa4b5', textTransform:'uppercase' }}>
      <span>{lang || 'code'}</span>
      <span onClick={(e) => { e.stopPropagation(); try { navigator.clipboard?.writeText(code); } catch {} }} style={{ cursor:'pointer', color:'#ff8ad8' }}>Copy</span>
    </span>
    <span style={{ display:'block', padding:'8px 10px', fontFamily:'ui-monospace, Menlo, Consolas, monospace', fontSize:'0.82em', lineHeight:1.45, color: CODE_COLORS.plain, whiteSpace:'pre', overflowX:'auto' }}>
      {highlightCode(code, lang)}
    </span>
  </span>
);

// ── Colour tags:  *blue*Good morning*/*   *pink*I love you*/*   (also *#ff8800*text*/*) ──
// The tag word is hidden once it is closed with */* . If it is NOT closed, nothing is coloured
// and the word stays visible like normal text.
const TAG_COLORS = {
  red:'#ff5a5f', pink:'#ff6ec7', hotpink:'#ff2d95', purple:'#b44cff', violet:'#8b5cf6', blue:'#5aa9ff', cyan:'#22e4ff', teal:'#2dd4bf',
  green:'#4ade80', lime:'#a3e635', yellow:'#facc15', gold:'#fbbf24', orange:'#fb923c', white:'#ffffff', grey:'#9ca3af', gray:'#9ca3af', black:'#111111', brown:'#b9770e',
  rooi:'#ff5a5f', pienk:'#ff6ec7', blou:'#5aa9ff', groen:'#4ade80', geel:'#facc15', oranje:'#fb923c', pers:'#b44cff', wit:'#ffffff', swart:'#111111',
};
const TAG_NAMES_RE = Object.keys(TAG_COLORS).sort((a, b) => b.length - a.length).join('|');
const COLOR_BLOCK_SRC = '\\*(?:' + TAG_NAMES_RE + '|#[0-9a-fA-F]{3,8})\\*[\\s\\S]*?\\*\\/\\*';
const COLOR_BLOCK_RE = new RegExp('^\\*(' + TAG_NAMES_RE + '|#[0-9a-fA-F]{3,8})\\*([\\s\\S]*?)\\*\\/\\*$', 'i');
const RICH_BASE_RE = /(```[\s\S]*?```|(?<![A-Za-z0-9])\*[^*\n]+\*(?![A-Za-z0-9])|(?<![A-Za-z0-9])_[^_\n]+_(?![A-Za-z0-9])|(?<![A-Za-z0-9])~[^~\n]+~(?![A-Za-z0-9])|`[^`\n]+`|https?:\/\/[^\s<]+|(?<![A-Za-z0-9_])@[A-Za-z0-9_.]{2,30})/g;
const RICH_RE = new RegExp('(' + COLOR_BLOCK_SRC + '|' + RICH_BASE_RE.source.slice(1, -1) + ')', 'gi');

// plain text → tone words coloured
const renderTone = (s, keyBase) => {
  const parts = s.split(TONE_RE);
  if (parts.length === 1) return s;
  return parts.map((w, i) => {
    const color = i % 2 ? TONE_MAP[w.toLowerCase()] : null;
    return color ? <span key={keyBase + '-' + i} style={{ color, fontWeight: 700 }}>{w}</span> : w;
  });
};

const renderRich = (raw, { linkColor = '#8fd3ff', mentionColor = '#ff8ad8', inColor = false } = {}) => {
  if (raw == null || raw === '') return raw;
  const text = expandAlias(String(raw));
  const tint = inColor ? null : heartTint(text);
  const nodes = text.split(RICH_RE).map((p, i) => {
    if (!p) return null;
    const first = p[0], last = p[p.length - 1];
    const cm = COLOR_BLOCK_RE.exec(p);
    if (cm) {
      const c = cm[1][0] === '#' ? cm[1] : TAG_COLORS[cm[1].toLowerCase()];
      return <span key={i} style={{ color: c }}>{renderRich(cm[2], { linkColor, mentionColor, inColor: true })}</span>;
    }
    if (p.length >= 6 && p.startsWith('```') && p.endsWith('```')) {
      let inner = p.slice(3, -3);
      const m = inner.match(/^([A-Za-z0-9+#-]*)[ \t]*\n/);
      const lang = m ? m[1].toLowerCase() : '';
      if (m) inner = inner.slice(m[0].length);
      return <CodeBlock key={i} code={inner.replace(/\n$/, '')} lang={lang} />;
    }
    if (p.length > 2 && first === '*' && last === '*') return <strong key={i}>{p.slice(1, -1)}</strong>;
    if (p.length > 2 && first === '_' && last === '_') return <em key={i}>{p.slice(1, -1)}</em>;
    if (p.length > 2 && first === '~' && last === '~') return <s key={i}>{p.slice(1, -1)}</s>;
    if (p.length > 2 && first === '`' && last === '`') return <code key={i} style={{ fontFamily:'monospace', background:'rgba(255,255,255,.14)', borderRadius:5, padding:'1px 5px', fontSize:'0.92em', color: CODE_COLORS.plain }}>{p.slice(1, -1)}</code>;
    if (/^https?:\/\//.test(p)) {
      const url = p.replace(/[.,!?)]+$/, ''), tail = p.slice(url.length);
      return <React.Fragment key={i}><a href={url} onClick={(e) => { e.preventDefault(); e.stopPropagation(); try { window.open(url, '_blank', 'noopener,noreferrer'); } catch {} }} style={{ color: linkColor, textDecoration:'underline', wordBreak:'break-all' }}>{url}</a>{tail}</React.Fragment>;
    }
    if (first === '@') return <span key={i} style={{ color: mentionColor, fontWeight: 700 }}>{p}</span>;
    return <React.Fragment key={i}>{inColor ? p : renderTone(p, i)}</React.Fragment>;
  });
  return tint ? <span style={{ color: tint }}>{nodes}</span> : nodes;
};

// ─── helpers ──────────────────────────────────────────────────────────
// ─── On-video text styles (record screen editor + feed player) ─────────────────────
const OVERLAY_FONTS = [
  { id:'classic', label:'Classic', family:'system-ui, -apple-system, Roboto, sans-serif', weight:800 },
  { id:'serif',   label:'Serif',   family:'Georgia, "Times New Roman", serif', weight:700 },
  { id:'mono',    label:'Mono',    family:'ui-monospace, Menlo, Consolas, monospace', weight:700 },
  { id:'script',  label:'Script',  family:'"Brush Script MT", "Segoe Script", cursive', weight:700 },
  { id:'impact',  label:'Impact',  family:'Impact, "Arial Black", sans-serif', weight:400 },
];
const OVERLAY_COLORS = ['#ffffff','#111111','#ff2d95','#b44cff','#5aa9ff','#22e4ff','#4ade80','#facc15','#fb923c','#ff5a5f'];
const DEFAULT_TEXT_STYLE = { color:'#ffffff', font:'classic', size:5.3, bg:'none', outline:false, glow:false };
const parseTextStyle = (raw) => {
  try {
    const o = typeof raw === 'string' ? JSON.parse(raw || '{}') : (raw || {});
    const size = Number(o.size);
    return {
      color: /^#[0-9a-f]{3,8}$/i.test(o.color || '') ? o.color : DEFAULT_TEXT_STYLE.color,
      font: OVERLAY_FONTS.some(f => f.id === o.font) ? o.font : DEFAULT_TEXT_STYLE.font,
      size: Number.isFinite(size) ? Math.min(14, Math.max(2.5, size)) : DEFAULT_TEXT_STYLE.size,
      bg: ['none','dark','light'].includes(o.bg) ? o.bg : 'none',
      outline: !!o.outline, glow: !!o.glow,
    };
  } catch { return DEFAULT_TEXT_STYLE; }
};
// Size is in vw, so the text is the same share of the screen in the recorder and in the feed.
const overlayTextCss = (ts) => {
  const f = OVERLAY_FONTS.find(x => x.id === ts.font) || OVERLAY_FONTS[0];
  return {
    color: ts.color, fontFamily: f.family, fontWeight: f.weight, fontSize: `${ts.size}vw`, lineHeight: 1.15,
    background: ts.bg === 'dark' ? 'rgba(0,0,0,.62)' : ts.bg === 'light' ? 'rgba(255,255,255,.88)' : 'transparent',
    padding: ts.bg === 'none' ? 0 : '0.25em 0.6em', borderRadius: '0.45em',
    textShadow: ts.glow ? `0 0 8px ${ts.color}, 0 0 20px ${ts.color}` : (ts.bg === 'none' ? '0 2px 8px rgba(0,0,0,.85)' : 'none'),
    WebkitTextStroke: ts.outline ? '1.2px #000' : undefined, paintOrder: ts.outline ? 'stroke fill' : undefined,
    whiteSpace: 'pre-wrap', wordBreak: 'break-word',
  };
};

const mediaHref = (rel) =>
  !rel ? null: rel.startsWith('http') ? rel : `${SNAP_URL}/snapsa/media/${rel}`;

// ─── End-of-video Snapsa signature sound ─────────────
let _snapEndCtx = null;
const stopSnapEndSound = () => {
  if (_snapEndCtx) {
    try { _snapEndCtx.close(); } catch {}
    _snapEndCtx = null;
  }
};
const playSnapEndSound = () => {
  try {
    stopSnapEndSound(); // never let a previous scheduled sound survive a scroll
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    _snapEndCtx = ctx;
    if (ctx.state === 'suspended') ctx.resume();
 
    // Compressor for loudness maximisation
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -6;
    comp.knee.value = 0;
    comp.ratio.value = 4;
    comp.attack.value = 0.001;
    comp.release.value = 0.1;
    comp.connect(ctx.destination);
 
    const play = (freq, startOffset, dur, vol, type = 'sine') => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.connect(g); g.connect(comp);
      o.type = type;
      const t0 = ctx.currentTime + startOffset;
      o.frequency.setValueAtTime(freq, t0);
      o.frequency.exponentialRampToValueAtTime(freq * 1.7, t0 + dur * 0.45);
      g.gain.setValueAtTime(vol, t0);
      g.gain.setValueAtTime(vol, t0 + 0.025);
      g.gain.exponentialRampToValueAtTime(vol * 0.6, t0 + dur * 0.4);
      g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
      o.start(t0); o.stop(t0 + dur);
    };
 
    // Sub-bass thump
    const playSub = (freq, startOffset, dur, vol) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.connect(g); g.connect(comp);
      o.type = 'sine';
      const t0 = ctx.currentTime + startOffset;
      o.frequency.setValueAtTime(freq, t0);
      o.frequency.exponentialRampToValueAtTime(freq * 0.7, t0 + dur);
      g.gain.setValueAtTime(vol, t0);
      g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
      o.start(t0); o.stop(t0 + dur);
    };
 
    // Much louder — vol 0.9 range, compressor keeps it clean
    play(880, 0,    0.24, 0.9, 'sine');
    play(440, 0.02, 0.30, 0.85, 'triangle');
    playSub(90, 0,  0.28, 0.8);
    play(1320, 0.20, 0.20, 0.65, 'sine');
    play(1760, 0.25, 0.18, 0.55, 'sine');
 
  } catch (e) {
    console.warn('[snapSound]', e.message);
  }
};
