const resolveSnapsaTier = (wernTier, snapsaTier) => snapsaTier || '';

const WERN_TIER_LABELS = {
  basic: 'WernTjat Verified',
  verified: 'WernTjat Verified',
  premium: 'WernTjat Premium Verified',
  pro: 'WernTjat Pro Verified',
};
const snapsaTierLabel = (t) => `Snapsa ${t.charAt(0).toUpperCase()+t.slice(1)} Verified`;

// Same scalloped-check shape as the WernTjat badge, in Snapsa's dark pink.
const SNAPSA_VERIFIED_PINK = '#C2185B'; // The official Snapsa account: shown as SNAPSA, in pink, with the Snapsa badge and logo. 
const isSnapsaOfficial = (u) => !!u && (u.isSystemAccount || String(u.authorName || u.username || '').toLowerCase() === 'snapsa');
const SnapsaVerifiedBadge = ({ size = 14 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" style={{ display:'block' }}>
    <path
      d="M12 2l2.4 1.4 2.7-.4 1.3 2.4 2.4 1.4-.4 2.7L22 12l-1.6 2.5.4 2.7-2.4 1.4-1.3 2.4-2.7-.4L12 22l-2.4-1.4-2.7.4-1.3-2.4-2.4-1.4.4-2.7L2 12l1.6-2.5-.4-2.7 2.4-1.4 1.3-2.4 2.7.4L12 2z"
      fill={SNAPSA_VERIFIED_PINK}
    />
    <path d="M8.4 12.4l2.4 2.4 4.8-5" stroke="white" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" fill="none" />
  </svg>
);

const countryFlag = (code) => (code && /^[A-Za-z]{2}$/.test(code))
  ? String.fromCodePoint(...[...code.toUpperCase()].map(c => 127397 + c.charCodeAt(0)))
  : '🌍';
const CountryTag = ({ code, name }) => (
  <span title="Country" style={{ display:'inline-flex', alignItems:'center', gap:5, background:'rgba(255,255,255,0.08)', border:`1px solid ${S.border}`, borderRadius:999, padding:'3px 10px', fontSize:11.5, color:'white', fontWeight:600 }}>
    <span style={{ fontSize:13 }}>{countryFlag(code)}</span>{name || code}
  </span>
);

