// ─── Live Watch ───────────────────────────────────────────────────────
const LiveWatchScreen = ({ live, onClose }) => {
  const [viewers, setViewers] = useState(live.viewers||'0');
  const [comments, setComments] = useState([]);
  const [commentText, setCommentText] = useState('');
  const wsRef = useRef(null);
  useEffect(() => {
    const token = getSnapToken();
    const WS_URL = SNAP_URL.replace(/^http/, 'ws');
    const ws = new WebSocket(`${WS_URL}/snapsa/live/ws?roomId=${live.id}&token=${token}`);
    wsRef.current = ws;
    ws.onmessage = e => {
      const msg = JSON.parse(e.data);
      if (msg.type==='viewer_joined') setViewers(p=>String(parseInt(p||'0')+1));
      if (msg.type==='live_comment') setComments(p=>[...p.slice(-49),{user:msg.from,text:msg.text}]);
    };
    return () => wsRef.current?.close();
  }, [live.id]);
  const sendComment = () => {
    if (!commentText.trim()||!wsRef.current) return;
    wsRef.current.send(JSON.stringify({type:'comment',text:commentText}));
    setCommentText('');
  };
  return (
    <div style={{ position:'absolute', inset:0, zIndex:60, background:`linear-gradient(135deg,${live.c?.[0]||'#134e4a'},${live.c?.[1]||'#4c1d95'})`, display:'flex', flexDirection:'column' }}>
      <div style={{ position:'absolute', inset:0, background:'linear-gradient(to top,rgba(0,0,0,.65) 30%,transparent 70%)' }}/>
      <div style={{ position:'relative', zIndex:10, display:'flex', alignItems:'center', justifyContent:'space-between', padding:'48px 16px 12px' }}>
        <div style={{ display:'flex', alignItems:'center', gap:10 }}>
          <div style={{ width:40, height:40, borderRadius:'50%', background:S.pink, display:'flex', alignItems:'center', justifyContent:'center', fontWeight:700, color:'white' }}>{live.name?.[0]?.toUpperCase()}</div>
          <div>
            <p style={{ color:'white', fontWeight:700, fontSize:14 }}>@{live.name}</p>
            <div style={{ display:'flex', alignItems:'center', gap:5 }}>
              <div style={{ width:6, height:6, borderRadius:'50%', background:S.pink }}/>
              <span style={{ color:S.pink, fontSize:11, fontWeight:700 }}>LIVE</span>
              <span style={{ color:'rgba(255,255,255,.65)', fontSize:11 }}>· {viewers} watching</span>
            </div>
          </div>
        </div>
        <button onClick={onClose} style={{ background:'rgba(0,0,0,.4)', borderRadius:'50%', padding:8, border:'none', cursor:'pointer' }}><X size={20} style={{ color:'white' }}/></button>
      </div>
      <div style={{ position:'absolute', bottom:0, left:0, right:0, zIndex:11, background:'rgba(0,0,0,.6)', padding:'16px' }}>
        <div style={{ maxHeight:160, overflowY:'auto', marginBottom:10 }}>
          {comments.map((c,i)=>(
            <div key={i} style={{ marginBottom:6, fontSize:12, color:'white' }}>
              <strong style={{ color:S.pink }}>@{c.user}</strong>: {renderRich(c.text)}
            </div>
          ))}
        </div>
        <div style={{ display:'flex', gap:8 }}>
          <input value={commentText} onChange={e=>setCommentText(e.target.value)} onKeyPress={e=>e.key==='Enter'&&sendComment()}
            placeholder="Say something..." style={{ flex:1, background:'rgba(255,255,255,.2)', border:'none', borderRadius:20, padding:'10px 16px', color:'white', outline:'none' }}/>
          <button onClick={sendComment} style={{ background:S.pink, border:'none', borderRadius:20, padding:'10px 20px', color:'white', cursor:'pointer', fontWeight:700 }}>Send</button>
        </div>
      </div>
    </div>
  );
};

//  notification timestamp: relative for the last hour, then a
// real calendar date + time (not a vague "2d ago" forever).
const formatNotifTime = (dateStr) => {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return ''; // missing/invalid createdAt — don't show garbage
  const now = new Date();
  const diffMs = now - d;
  const diffMin = Math.floor(diffMs / 60000);
  if (diffMin < 1) return 'Just now';
  if (diffMin < 60) return `${diffMin}m ago`;
  const isToday = d.toDateString() === now.toDateString();
  const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
  const isYesterday = d.toDateString() === yesterday.toDateString();
  const time = d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
  if (isToday) return `Today at ${time}`;
  if (isYesterday) return `Yesterday at ${time}`;
  const sameYear = d.getFullYear() === now.getFullYear();
  const dateStr2 = d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: sameYear ? undefined : 'numeric' });
  return `${dateStr2} at ${time}`;
};

