const NOTIF_FILTERS = [
  { id:'all',      label:'All',      emoji:'🔔', types:null },
  { id:'likes',    label:'Likes',    emoji:'💗', types:['like','story_like'] },
  { id:'comments', label:'Comments', emoji:'💬', types:['comment'] },
  { id:'follows',  label:'Follows',  emoji:'👤', types:['follow'] },
  { id:'gifts',    label:'Gifts',    emoji:'🎁', types:['gift_received','gift_sent','gift_failed','watch_reward','music_sale','product_sold'] },
];
const notifAgo = (d) => {
  const s = Math.max(0, (Date.now() - new Date(d).getTime()) / 1000);
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  if (s < 604800) return `${Math.floor(s / 86400)}d ago`;
  return new Date(d).toLocaleDateString(undefined, { day:'numeric', month:'short' });
};

const NotificationsScreen = ({ onBack, showToast, onOpenProfile }) => {
  const { t } = useLanguage();
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [confirmingDelete, setConfirmingDelete] = useState(null);
  const [confirmingClearAll, setConfirmingClearAll] = useState(false);

  useEffect(() => {
    const h = () => snapFetch('/snapsa/notifications').then(r => r.ok ? r.json() : null).then(d => { if (d?.notifications) setNotifications(d.notifications); }).catch(() => {});
    window.addEventListener('snapsa:appResume', h);
    return () => window.removeEventListener('snapsa:appResume', h);
  }, []);
  useEffect(() => {
    snapFetch('/snapsa/notifications')
      .then(r => r.ok ? r.json() : null)
      .then(d => { setNotifications(d?.notifications || []); setLoading(false); })
      .catch(() => { setLoading(false); });
  }, []);
  useEffect(() => {
    const h = (e) => {
      const n = e.detail?.notification;
      if (n) setNotifications(prev => [n, ...prev.filter(x => x._id !== n._id)]);
    };
    window.addEventListener('snapsa:realtimeNotification', h);
    return () => window.removeEventListener('snapsa:realtimeNotification', h);
  }, []);

  const openProfile = (n) => {
    const uid = n.data?.authorId || n.senderId;
    if (uid) onOpenProfile?.({ authorId: uid, id: uid });
  };

  const handleTap = async (n) => {
    try { await snapFetch(`/snapsa/notifications/${n._id}/read`, { method:'POST' }); } catch {}
    setNotifications(prev => prev.map(x => x._id === n._id ? { ...x, read: true } : x));
    if (n.data?.videoId) {
      try {
        const res = await snapFetch(`/snapsa/videos/${n.data.videoId}`);
        if (res.ok) {
          const v = await res.json();
          window.dispatchEvent(new CustomEvent('snapsa:playVideo', { detail: { video: {
            id: v._id, authorId: v.authorId, authorName: v.authorName,
            caption: v.caption||'', likes: v.likes||0, comments: v.comments||0, shares: v.shares||0,
            videoUrl: mediaHref(v.videoFile), thumbUrl: mediaHref(v.thumbFile),
            c: ['#1a1a4e','#4c1d95','#be185d'],
          } } }));
          return;
        }
      } catch {}
      showToast?.('That video is no longer available', 'info');
      return;
    }
    if (n.data?.storyId) {
      window.dispatchEvent(new CustomEvent('snapsa:openStoryById', { detail: { storyId: n.data.storyId, authorId: n.data.authorId } }));
      return;
    }
    openProfile(n);
  };

  const handleDelete = async (n) => {
    setConfirmingDelete(null);
    const prev = notifications;
    setNotifications(list => list.filter(x => x._id !== n._id));
    try {
      const res = await snapFetch(`/snapsa/notifications/${n._id}`, { method: 'DELETE' });
      if (!res.ok) { setNotifications(prev); showToast?.('Could not delete notification', 'error'); }
    } catch { setNotifications(prev); showToast?.('Could not delete notification', 'error'); }
  };
  const handleClearAll = async () => {
    setConfirmingClearAll(false);
    const prev = notifications;
    setNotifications([]);
    try {
      const res = await snapFetch('/snapsa/notifications', { method: 'DELETE' });
      if (!res.ok) { setNotifications(prev); showToast?.('Could not clear notifications', 'error'); }
      else showToast?.('Notifications cleared', 'success');
    } catch { setNotifications(prev); showToast?.('Could not clear notifications', 'error'); }
  };

  const splitTitle = (title) => {
    const m = /^(@[\w.]+)(\s+.*)$/.exec(title || '');
    return m ? { handle: m[1], rest: m[2] } : { handle: null, rest: title };
  };

  const active = NOTIF_FILTERS.find(f => f.id === filter) || NOTIF_FILTERS[0];
  const shown = active.types ? notifications.filter(n => active.types.includes(n.type)) : notifications;
  const countOf = (f) => f.types ? notifications.filter(n => f.types.includes(n.type)).length : notifications.length;

  const modalCard = { background:'linear-gradient(160deg,#241046,#0d0518)', border:'1px solid rgba(180,76,255,.5)', boxShadow:'0 0 24px rgba(180,76,255,.35)', borderRadius:20, padding:20, width:'100%', maxWidth:300 };

  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100%', position:'relative', zIndex:1,
      background:'radial-gradient(120% 55% at 50% 0%, #2b0f52 0%, #12061f 45%, #05020a 100%)' }}>
      {/* Header */}
      <div style={{ display:'flex', alignItems:'center', gap:14, padding:'14px 16px 8px' }}>
        <button onClick={onBack} style={{ background:'none', border:'none', cursor:'pointer', padding:4 }}><ArrowLeft size={26} style={{ color:'white' }}/></button>
        <h2 style={{ color:'white', fontWeight:800, fontSize:24, flex:1, textShadow:'0 0 14px rgba(180,76,255,.8)' }}>{t('alerts.title')}</h2>
        {notifications.length > 0 && (
          <button onClick={()=>setConfirmingClearAll(true)} style={{ background:'none', border:'none', cursor:'pointer', color:'#ff2d95', fontSize:12, fontWeight:800, textShadow:'0 0 8px rgba(255,45,149,.7)' }}>
            Clear all
          </button>
        )}
      </div>

      {/* Filter pills */}
      <div style={{ display:'flex', gap:8, overflowX:'auto', scrollbarWidth:'none', padding:'6px 16px 12px' }}>
        {NOTIF_FILTERS.map(f => {
          const on = f.id === filter, c = countOf(f);
          return (
            <button key={f.id} onClick={() => setFilter(f.id)} style={{
              flexShrink:0, display:'flex', alignItems:'center', gap:6, padding:'9px 16px', borderRadius:999, cursor:'pointer',
              fontSize:13, fontWeight:700, color:'white',
              background: on ? 'linear-gradient(135deg,#8b2cf5,#ff2d95)' : 'rgba(255,255,255,.05)',
              border: on ? '1px solid rgba(255,138,216,.9)' : '1px solid rgba(180,76,255,.3)',
              boxShadow: on ? '0 0 16px rgba(180,76,255,.7)' : 'none',
            }}>
              <span>{f.emoji}</span>{f.label}{f.id === 'all' || on ? ` (${c})` : ''}
            </button>
          );
        })}
      </div>

      {/* List */}
      <div style={{ flex:1, overflowY:'auto', padding:'0 14px 16px' }}>
        {loading ? (
          <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, minHeight:200 }}>
            <div style={{ width:36, height:36, borderRadius:'50%', border:'3px solid #b44cff', borderTopColor:'transparent', animation:'sp .8s linear infinite', boxShadow:'0 0 14px rgba(180,76,255,.6)' }}/>
            <p style={{ color:S.gray, fontSize:13 }}>{t('alerts.loading')}</p>
            <style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style>
          </div>
        ) : shown.length === 0 ? (
          <div style={{ padding:48, textAlign:'center' }}>
            <Bell size={44} style={{ color:'rgba(180,76,255,0.4)', display:'block', margin:'0 auto 12px', filter:'drop-shadow(0 0 10px rgba(180,76,255,.7))' }}/>
            <p style={{ color:S.gray }}>{t('alerts.none')}</p>
          </div>
        ) : shown.map(n => (
          <SwipeableNotifRow key={n._id} n={n} onTap={handleTap} onOpenProfile={openProfile}
            onSwipeConfirm={()=>setConfirmingDelete(n)} splitTitle={splitTitle} showToast={showToast}/>
        ))}
      </div>

      {confirmingDelete && (
        <div onClick={()=>setConfirmingDelete(null)} style={{ position:'fixed', inset:0, zIndex:700, background:'rgba(0,0,0,0.7)', display:'flex', alignItems:'center', justifyContent:'center', padding:24 }}>
          <div onClick={e=>e.stopPropagation()} style={modalCard}>
            <p style={{ color:'white', fontWeight:800, fontSize:15, marginBottom:6 }}>{t('common.deleteQ')}</p>
            <p style={{ color:S.gray, fontSize:13, marginBottom:18 }}>{t('common.cantBeUndone')}</p>
            <div style={{ display:'flex', gap:10 }}>
              <button onClick={()=>setConfirmingDelete(null)} style={{ flex:1, padding:'10px 0', borderRadius:12, background:'rgba(255,255,255,.08)', color:'white', fontWeight:600, fontSize:13, border:'none', cursor:'pointer' }}>{t('common.cancel')}</button>
              <button onClick={()=>handleDelete(confirmingDelete)} style={{ flex:1, padding:'10px 0', borderRadius:12, background:'linear-gradient(135deg,#ef4444,#ff2d95)', color:'white', fontWeight:800, fontSize:13, border:'none', cursor:'pointer' }}>{t('common.delete')}</button>
            </div>
          </div>
        </div>
      )}
      {confirmingClearAll && (
        <div onClick={()=>setConfirmingClearAll(false)} style={{ position:'fixed', inset:0, zIndex:700, background:'rgba(0,0,0,0.7)', display:'flex', alignItems:'center', justifyContent:'center', padding:24 }}>
          <div onClick={e=>e.stopPropagation()} style={modalCard}>
            <p style={{ color:'white', fontWeight:800, fontSize:15, marginBottom:6 }}>{t('common.clearAllQ')}</p>
            <p style={{ color:S.gray, fontSize:13, marginBottom:18 }}>{t('common.cantBeUndone')}</p>
            <div style={{ display:'flex', gap:10 }}>
              <button onClick={()=>setConfirmingClearAll(false)} style={{ flex:1, padding:'10px 0', borderRadius:12, background:'rgba(255,255,255,.08)', color:'white', fontWeight:600, fontSize:13, border:'none', cursor:'pointer' }}>{t('common.cancel')}</button>
              <button onClick={handleClearAll} style={{ flex:1, padding:'10px 0', borderRadius:12, background:'linear-gradient(135deg,#ef4444,#ff2d95)', color:'white', fontWeight:800, fontSize:13, border:'none', cursor:'pointer' }}>{t('common.clearAll')}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const SwipeableNotifRow = ({ n, onTap, onOpenProfile, onSwipeConfirm, splitTitle, showToast }) => {
  const [dragX, setDragX] = useState(0);
  const [followed, setFollowed] = useState(false);
  const dragging = useRef(false);
  const startX = useRef(0);
  const { Icon, color } = NOTIF_ICON[n.type] || { Icon: Bell, color: '#b44cff' };
  const parsedTitle = splitTitle(n.title);
  const followMatch = !parsedTitle.handle && n.type === 'follow' ? /^(\S+)(\s+.*)$/.exec(n.title || '') : null;
  const handle = parsedTitle.handle || (followMatch ? followMatch[1] : null);
  const rest = parsedTitle.handle ? parsedTitle.rest : (followMatch ? followMatch[2] : parsedTitle.rest);
  const THRESHOLD = -70;
  const avatar = n.senderAvatar ? mediaHref(n.senderAvatar) : null;
  const thumb = n.data?.thumbUrl ? mediaHref(n.data.thumbUrl) : null;
  const unread = !n.read;
  const burned = !!n.burned;   // sender burned their identity (DEFCON 1): no links back to them

  const onPointerDown = (e) => { dragging.current = true; startX.current = (e.touches ? e.touches[0].clientX : e.clientX) - dragX; };
  const onPointerMove = (e) => {
    if (!dragging.current) return;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    setDragX(Math.min(0, Math.max(-100, clientX - startX.current)));
  };
  const onPointerUp = () => {
    if (!dragging.current) return;
    dragging.current = false;
    if (dragX < THRESHOLD) onSwipeConfirm();
    setDragX(0);
  };
  const followBack = async (e) => {
    e.stopPropagation();
    const uid = n.senderId || n.data?.authorId;
    if (!uid || followed) return;
    setFollowed(true);
    try {
      const res = await snapFetch(`/snapsa/users/${uid}/follow`, { method:'POST' });
      if (!res.ok) { setFollowed(false); showToast?.('Could not follow', 'error'); }
    } catch { setFollowed(false); }
  };

  return (
    <div style={{ position:'relative', borderRadius:20, overflow:'hidden', marginBottom:10 }}>
      <div style={{ position:'absolute', inset:0, background:'linear-gradient(90deg,#ff2d95,#ef4444)', display:'flex', alignItems:'center', justifyContent:'flex-end', paddingRight:24 }}>
        <Trash2 size={20} style={{ color:'white' }}/>
      </div>
      <div role="button" tabIndex={0}
        onClick={() => { if (Math.abs(dragX) < 5 && !burned) onTap(n); }}
        data-noswipe="1"
        onMouseDown={onPointerDown} onMouseMove={onPointerMove} onMouseUp={onPointerUp} onMouseLeave={onPointerUp}
        onTouchStart={onPointerDown} onTouchMove={onPointerMove} onTouchEnd={onPointerUp}
        style={{
          display:'flex', gap:12, alignItems:'center', padding:'12px 14px', borderRadius:20, cursor:'pointer', position:'relative',
          background:'linear-gradient(135deg, rgba(72,24,130,.55), rgba(14,6,28,.92))',
          border: unread ? '1px solid rgba(255,45,149,.75)' : '1px solid rgba(180,76,255,.35)',
          boxShadow: unread ? '0 0 16px rgba(255,45,149,.3), inset 0 0 14px rgba(180,76,255,.12)' : '0 0 10px rgba(180,76,255,.15)',
          transform:`translateX(${dragX}px)`, transition: dragging.current ? 'none' : 'transform .2s ease', touchAction:'pan-y',
        }}>
        {/* Avatar with type badge */}
        <div style={{ position:'relative', width:54, height:54, flexShrink:0 }}>
          <div style={{ width:54, height:54, borderRadius:'50%', padding:2, background:'linear-gradient(135deg,#b44cff,#ff2d95)', boxSizing:'border-box' }}>
            <div style={{ width:'100%', height:'100%', borderRadius:'50%', overflow:'hidden', background:'#120a24', display:'flex', alignItems:'center', justifyContent:'center' }}>
              {avatar
                ? <img src={avatar} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }} onError={e=>{ e.target.style.display='none'; }}/>
                : <Icon size={22} style={{ color }} strokeWidth={1.8}/>}
            </div>
          </div>
          {avatar && (
            <div style={{ position:'absolute', bottom:-3, right:-3, width:22, height:22, borderRadius:'50%', background:'#120a24', border:`2px solid ${color}`, boxShadow:`0 0 8px ${color}`, display:'flex', alignItems:'center', justifyContent:'center' }}>
              <Icon size={11} style={{ color }} fill={n.type==='like'||n.type==='story_like' ? color : 'none'} strokeWidth={2}/>
            </div>
          )}
        </div>

        <div style={{ flex:1, minWidth:0 }}>
          <p style={{ color:'white', fontSize:14, lineHeight:1.35, fontWeight:500 }}>
            {handle && <span onClick={e => { e.stopPropagation(); if (!burned) onOpenProfile(n); }} style={{ fontWeight:800 }}>{handle}</span>}
            {rest}
          </p>
          {n.body && <p style={{ color:'rgba(255,255,255,.72)', fontSize:12.5, marginTop:2, lineHeight:1.35 }}>{renderRich(n.body)}</p>}
          <p style={{ color:'rgba(200,170,255,.6)', fontSize:11.5, marginTop:4, display:'flex', alignItems:'center', gap:8 }}>{notifAgo(n.createdAt)}{burned && <span style={{ background:'linear-gradient(90deg,#ff5a1f,#ff2d2d)', color:'#fff', fontSize:10, fontWeight:900, letterSpacing:.8, padding:'2px 9px', borderRadius:999 }}>DEFCON 1</span>}</p>
        </div>

        {n.type === 'follow' && !burned ? (
          <button onClick={followBack} style={{
            flexShrink:0, padding:'9px 14px', borderRadius:999, border:'none', cursor:'pointer', color:'white', fontWeight:800, fontSize:12.5,
            background: followed ? 'rgba(255,255,255,.1)' : 'linear-gradient(135deg,#8b2cf5,#ff2d95)', boxShadow: followed ? 'none' : '0 0 14px rgba(255,45,149,.55)',
          }}>{followed ? 'Following' : 'Follow Back'}</button>
        ) : thumb ? (
          <img src={thumb} alt="" style={{ width:62, height:62, borderRadius:14, objectFit:'cover', flexShrink:0, border:'1px solid rgba(180,76,255,.5)', boxShadow:'0 0 10px rgba(180,76,255,.4)' }} onError={e=>{ e.target.style.display='none'; }}/>
        ) : (
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#c9a6ff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink:0 }}><path d="M9 6l6 6-6 6"/></svg>
        )}
      </div>
    </div>
  );
};





const StoryViewer = ({ group, onClose, currentUser, showToast }) => {
  const [idx, setIdx] = useState(0);
  const [paused, setPaused] = useState(false);
  const [showSnapShot, setShowSnapShot] = useState(false);
  const [snapShotText, setSnapShotText] = useState('');
  const [viewerList, setViewerList] = useState([]);
  const [showViewers, setShowViewers] = useState(false);
  const [progressPct, setProgressPct] = useState(0);
  const longPressRef = useRef(null);
  const storyVideoRef = useRef(null);
  const progressRef = useRef(null);
  const elapsedRef = useRef(0);
  const lastTickRef = useRef(null);
  const [storyDurationMs, setStoryDurationMs] = useState(5000);
  const [mediaReady, setMediaReady] = useState(false);
  const [storyLiked, setStoryLiked] = useState(false);
  const [reactedEmoji, setReactedEmoji] = useState(null);
  const [showAvatarFull, setShowAvatarFull] = useState(false);
  const [reposting, setReposting] = useState(false);
  const [reposted, setReposted] = useState(false);
  const story = group.stories[idx];
  const isOwn = story?.authorId?.toString() === (currentUser?._id || currentUser?.id);
  const modalOpen = showSnapShot || showViewers;

  useEffect(() => {
    if (!story) return;
    // Burn-after-view stories only count as "seen" once the content has actually appeared (see the mediaReady effect below)
    if (!story.burn) snapFetch(`/snapsa/stories/${story._id}/view`, { method:'POST' }).catch(()=>{});
    setProgressPct(0);
    elapsedRef.current = 0;
  
    setStoryDurationMs(story.type === 'video' ? 15000 : story.type === 'voice' ? 30000 : 5000);
    // Text stories have no media to wait for; photo/video/voice gate on their load handlers below.
    setMediaReady(story.type === 'text');
    setStoryLiked(false);
    setReactedEmoji(null);
    setReposted(false);
    const safety = setTimeout(() => setMediaReady(true), 4000);
    return () => clearTimeout(safety);
  }, [idx]);

  const burnCountedRef = useRef({});
  useScreenGuard(!!story?.burn && !isOwn);
  useEffect(() => {
    if (story?.burn && mediaReady && !isOwn && !burnCountedRef.current[story._id]) {
      burnCountedRef.current[story._id] = true;
      snapFetch(`/snapsa/stories/${story._id}/view`, { method:'POST' }).catch(()=>{});
    }
  }, [mediaReady, idx]);

  useEffect(() => {
    if (paused || modalOpen || !story || !mediaReady) {
      lastTickRef.current = null;
      return;
    }
    lastTickRef.current = Date.now();
    const tick = () => {
      const now = Date.now();
      const delta = now - lastTickRef.current;
      lastTickRef.current = now;
      elapsedRef.current += delta;
      const pct = Math.min(100, (elapsedRef.current / storyDurationMs) * 100);
      setProgressPct(pct);
      if (pct < 100) { progressRef.current = requestAnimationFrame(tick); }
      else { cancelAnimationFrame(progressRef.current); if (idx < group.stories.length - 1) { setIdx(i => i+1); } else { onClose(); } }
    };
    progressRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(progressRef.current);
  }, [idx, paused, modalOpen, story, storyDurationMs, mediaReady]);

  
  useEffect(() => {
    const v = storyVideoRef.current;
    if (!v) return;
    if (paused || modalOpen) v.pause();
    else v.play().catch(() => {});
  }, [paused, modalOpen, idx]);

  const wasLongPressRef = useRef(false);
  const touchActiveRef = useRef(false);
  const startLongPress = (e) => {
    if (modalOpen) return;
    if (e.type === 'mousedown' && touchActiveRef.current) return; // ignore ghost mouse after touch
    if (e.type === 'touchstart') touchActiveRef.current = true;
    wasLongPressRef.current = false;
    longPressRef.current = setTimeout(() => { wasLongPressRef.current = true; setPaused(true); }, 400);
  };
  const endLongPress = (e) => {
    clearTimeout(longPressRef.current);
    if (e?.type === 'touchend') setTimeout(() => { touchActiveRef.current = false; }, 500);
    if (modalOpen) return;
    setPaused(false);
  };

  const sendReact = async (emoji) => {
    if (!currentUser || currentUser.isGuest) { showToast?.('Sign in to react', 'info'); return; }
    setReactedEmoji(emoji); // optimistic — instant pink-ring feedback
    try {
      if (emoji === '❤️') {
        const res = await snapFetch(`/snapsa/stories/${story._id}/like`, { method: 'POST' });
        if (res.ok) { setStoryLiked(true); showToast?.('❤️ Liked!', 'success'); }
        else { const d = await res.json().catch(()=>({})); showToast?.(d.error || 'Could not like story', 'error'); setReactedEmoji(null); }
      } else {
        const res = await snapFetch(`/snapsa/messages/${story.authorId}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: `${emoji} reacted to your story`, storyId: story._id, kind: 'story_reaction' }),
        });
        if (res.ok) showToast?.(`${emoji} Reaction sent!`, 'success');
        else { showToast?.('Could not send reaction', 'error'); setReactedEmoji(null); }
      }
    } catch { showToast?.('Could not send reaction', 'error'); setReactedEmoji(null); }
  };

  const sendRepost = async () => {
    if (!currentUser || currentUser.isGuest) { showToast?.('Sign in to repost', 'info'); return; }
    if (reposting || reposted) return;
    setReposting(true);
    try {
      const res = await snapFetch(`/snapsa/stories/${story._id}/repost`, { method: 'POST' });
      const d = await res.json().catch(() => ({}));
      if (res.ok) { setReposted(true); showToast?.('Reposted to your story ♻️', 'success'); }
      else showToast?.(d.error || 'Could not repost', 'error');
    } catch { showToast?.('Could not repost', 'error'); }
    setReposting(false);
  };

  const sendSnapShot = async () => {
    if (!snapShotText.trim()) return;
    if (!currentUser || currentUser.isGuest) { showToast?.('Sign in to comment', 'info'); return; }
    try {
      const res = await snapFetch(`/snapsa/messages/${story.authorId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          text: snapShotText,
          storyId: story._id,
          kind: 'story_reply',
        }),
      });
      if (res.ok) showToast?.('✅ Snap-Shot sent to their DMs!', 'success');
      else { const d = await res.json().catch(()=>({})); showToast?.(d.error || 'Could not send Snap-Shot', 'error'); }
    } catch { showToast?.('Could not send Snap-Shot', 'error'); }
    setSnapShotText(''); setShowSnapShot(false); setPaused(false);
  };

  if (!story) return null;

  const postedAgo = (() => {
    const d = new Date(story.createdAt);
    const now = new Date();
    const diff = now.getTime() - d.getTime();
    const m = Math.floor(diff / 60000);
    if (m < 1) return 'just now';
    if (m < 60) return `${m}m ago`;

    let h = d.getHours();
    const ampm = h >= 12 ? 'pm' : 'am';
    h = h % 12; if (h === 0) h = 12;
    const time = `${String(h).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}${ampm}`;

    const isSameDay = d.toDateString() === now.toDateString();
    const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
    const isYesterday = d.toDateString() === yesterday.toDateString();

    if (isSameDay) return `Today at ${time}`;
    if (isYesterday) return `Yesterday at ${time}`;
    return `${d.toLocaleDateString([], { month:'short', day:'numeric' })} at ${time}`;
  })();

   const handleZoneTap = (e) => {
    if (e.target.closest('button') || e.target.closest('input') || e.target.closest('textarea')) return;
    if (wasLongPressRef.current) { wasLongPressRef.current = false; return; }
    const rect = e.currentTarget.getBoundingClientRect();
    const clientX = e.clientX ?? rect.left + rect.width;
    const tapPct = (clientX - rect.left) / rect.width;
    if (tapPct < 0.3) {
      if (idx > 0) setIdx(i => i - 1);
    } else {
      if (idx < group.stories.length - 1) setIdx(i => i + 1); else onClose();
    }
  };

  return (
    <div style={{ position:'fixed', inset:0, zIndex:600, background:'#000', userSelect:'none', WebkitUserSelect:'none', WebkitTouchCallout:'none', touchAction:'none' }}
      onContextMenu={e=>e.preventDefault()}
      onMouseDown={startLongPress} onMouseUp={endLongPress}
      onTouchStart={startLongPress} onTouchEnd={endLongPress}
      onClick={handleZoneTap}>

      {/* Progress bars — animated */}
      <div style={{ position:'absolute', top:8, left:8, right:8, display:'flex', gap:3, zIndex:10 }}>
        {group.stories.map((_,i) => (
          <div key={i} style={{ flex:1, height:3, borderRadius:2, background:'rgba(255,255,255,0.25)', overflow:'hidden' }}>
            <div style={{
              height:'100%', borderRadius:2, background:S.pink,
              width: i < idx ? '100%' : i === idx ? `${progressPct}%` : '0%',
              transition: i === idx ? 'none' : undefined,
            }}/>
          </div>
        ))}
      </div>

      {/* Header */}
      <div style={{ position:'absolute', top:20, left:12, right:12, zIndex:10, display:'flex', alignItems:'center', justifyContent:'space-between' }}>
        <div style={{ display:'flex', alignItems:'center', gap:8 }}>
          <button
            onClick={e => { e.stopPropagation(); if (group.avatarUrl) { setPaused(true); setShowAvatarFull(true); } }}
            style={{ width:32, height:32, borderRadius:'50%', background:S.pink, overflow:'hidden', display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontWeight:700, fontSize:14, border:'none', padding:0, cursor: group.avatarUrl ? 'pointer' : 'default' }}
          >
            {group.avatarUrl
              ? <img src={mediaHref(group.avatarUrl)} style={{ width:'100%', height:'100%', objectFit:'cover' }} alt=""/>
              : group.authorName?.[0]?.toUpperCase()}
          </button>
          <div>
            <div style={{ display:'inline-flex', flexDirection:'column', alignItems:'flex-start', gap:2 }}><span style={{ color:'white', fontWeight:700, fontSize:13, display:'inline-flex', alignItems:'center', gap:4 }}>{group.authorDisplayName || group.authorName}<AuthorBadges snapsaTier={group.authorSnapsaTier} size={13} crew={group.crew}/></span>{group.official && <OfficialPill label={group.official === true ? 'OFFICIAL' : group.official} />}</div>
            <p style={{ color:'rgba(255,255,255,0.55)', fontSize:10, margin:0 }}>
              {postedAgo}
              {story.burn && <span style={{ color:'#fbbf24', fontWeight:700 }}> • 🔥 BURN · one view</span>}
              {story.repostOf && story.repostAuthorName && (
                <span style={{ color:S.pink, fontWeight:700 }}> • REPOST • {story.repostAuthorName}</span>
              )}
            </p>
          </div>
        </div>
        <div style={{ display:'flex', alignItems:'center', gap:8 }}>
          {/* Recyclable repost icon — only ever shown to viewers other than
              the author; tapping it instantly posts a copy to their own
              story, credited back to the original poster. */}
          {!isOwn && !story.burn && (
            <button
              onClick={e => { e.stopPropagation(); sendRepost(); }}
              disabled={reposting || reposted}
              title={reposted ? 'Reposted' : 'Repost to your story'}
              style={{ background:'rgba(0,0,0,.5)', border:'none', borderRadius:999, padding:'6px', display:'flex', alignItems:'center', justifyContent:'center', cursor: (reposting||reposted) ? 'default' : 'pointer', opacity: reposting ? 0.6 : 1 }}
            >
              <Repeat2 size={16} style={{ color: reposted ? S.pink : 'white' }}/>
            </button>
          )}
          {isOwn && (
            <button onClick={e=>{ e.stopPropagation(); snapFetch(`/snapsa/stories/${story._id}/viewers`).then(r=>r.ok?r.json():null).then(d=>{ if(d?.viewers) setViewerList(d.viewers); setShowViewers(true); }).catch(()=>{}); }}
              style={{ background:'rgba(0,0,0,.5)', border:'none', borderRadius:999, padding:'4px 10px', display:'flex', alignItems:'center', gap:4, cursor:'pointer' }}>
              <Eye size={12} style={{ color:'white' }}/>
              <span style={{ color:'white', fontSize:11, fontWeight:600 }}>{story.viewers?.length || 0}</span>
            </button>
          )}
          
          <button onClick={e=>{ e.stopPropagation(); onClose(); }} style={{ background:'rgba(0,0,0,.5)', borderRadius:'50%', padding:7, border:'none' }}>
            <X size={17} style={{ color:'white' }}/>
          </button>
        </div>
      </div>

      {/* Story content */}
      <div style={{ width:'100%', height:'100%', display:'flex', alignItems:'center', justifyContent:'center', position:'relative' }}>
        {story.type === 'text' ? (
          <div style={{ width:'100%', height:'100%', background:story.bgColor||S.pink, display:'flex', alignItems:'center', justifyContent:'center', padding:24 }}>
            <p style={{
            color: story.textColor || 'white',
            fontSize: 26,
            textAlign: 'center',
            textShadow: '0 2px 8px rgba(0,0,0,0.5)',
            ...(STORY_FONTS.find(f=>f.id===story.fontStyle)||STORY_FONTS[0]).style,
          }}>{renderRich(story.text)}</p>
          </div>
        ) : story.type === 'voice' ? (
          <StoryVoicePlayer key={story._id} src={mediaHref(story.mediaFile)} bg={story.bgColor} text={story.text} textColor={story.textColor} fontStyle={story.fontStyle}
            paused={paused} audioRef={storyVideoRef} onReady={() => setMediaReady(true)} onDuration={ms => setStoryDurationMs(ms)} />
        ) : story.type === 'video' ? (
          <video
            key={story._id}
            ref={el => { storyVideoRef.current = el; }}
            src={mediaHref(story.mediaFile)}
            autoPlay={!paused}
            muted
            playsInline
            onLoadedMetadata={e => { if (e.target.duration) setStoryDurationMs(e.target.duration * 1000); }}
            onCanPlayThrough={() => setMediaReady(true)}
            onError={() => setMediaReady(true)}
            style={{ maxWidth:'100%', maxHeight:'100%', objectFit:'contain' }}
          />
        ) : story.effect === '3d' ? (
          <Story3DPhoto key={story._id} src={mediaHref(story.mediaFile)} onLoad={() => setMediaReady(true)} onError={() => setMediaReady(true)} fill />
        ) : (
          <img
            key={story._id}
            src={mediaHref(story.mediaFile)}
            onLoad={() => setMediaReady(true)}
            onError={() => setMediaReady(true)}
            style={{ maxWidth:'100%', maxHeight:'100%', objectFit:'contain' }}
          />
        )}
        {story.text && (story.type === 'photo' || story.type === 'video') && (
          <div style={{ position:'absolute', left:0, right:0, bottom:150, textAlign:'center', padding:'0 18px', pointerEvents:'none', zIndex:6 }}>
            <span style={{ color: story.textColor || '#fff', fontSize:22, textShadow:'0 2px 8px rgba(0,0,0,.85)', ...(STORY_FONTS.find(f=>f.id===story.fontStyle)||STORY_FONTS[0]).style }}>{story.text}</span>
          </div>
        )}
        <StoryStickers key={'st'+story._id} story={story} isOwn={isOwn} snapFetch={snapFetch} showToast={showToast} mediaHref={mediaHref} onPause={() => setPaused(true)}
          onSendAnswer={async (txt) => { try { const r = await snapFetch(`/snapsa/messages/${story.authorId}`, { method:'POST', headers:{ 'Content-Type':'application/json' }, body: JSON.stringify({ text: txt, storyId: story._id, kind: 'story_reply' }) }); if (r.ok) return true; const d = await r.json().catch(()=>({})); showToast?.(d.error || 'Could not send', 'error'); } catch { showToast?.('Could not send', 'error'); } return false; }} />
        {!mediaReady && story.type !== 'text' && (
          <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center', background:'#000', zIndex:5 }}>
            <div style={{ width:36, height:36, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>
            <style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style>
          </div>
        )}
      </div>

      {/* Bottom actions */}
      {!isOwn && (
        <div style={{ position:'absolute', bottom:32, left:12, right:12, zIndex:10, display:'flex', flexDirection:'column', gap:10 }} onClick={e=>e.stopPropagation()}>
          <div style={{ display:'flex', gap:8 }}>
            <button onClick={()=>{ setPaused(true); setShowSnapShot(true); }}
              style={{ flex:1, padding:'10px 0', borderRadius:999, background:'rgba(255,255,255,0.12)', backdropFilter:'blur(8px)', border:'1px solid rgba(255,255,255,0.25)', color:'white', fontWeight:700, fontSize:13, cursor:'pointer' }}>
              💬 Snap-Shot
            </button>
          </div>
          {/* On-screen emoji row — reacting is a single instant tap, nothing
              to pause and nothing that can race the progress bar. */}
          <div
            onMouseDown={e=>e.stopPropagation()} onMouseUp={e=>e.stopPropagation()}
            onTouchStart={e=>e.stopPropagation()} onTouchEnd={e=>e.stopPropagation()}
            style={{ display:'flex', gap:8, justifyContent:'space-between', background:'rgba(20,20,30,0.55)', backdropFilter:'blur(10px)', borderRadius:999, padding:'6px 8px', border:'1px solid rgba(255,255,255,0.15)' }}>
            {['😍','😡','🥺','😭','❤️','💯','🔥'].map(em => {
              const active = reactedEmoji === em;
              return (
                <button key={em} onClick={()=>sendReact(em)}
                  style={{
                    fontSize:22, lineHeight:1, background: active ? 'rgba(255,32,85,0.18)' : 'transparent',
                    border: active ? `2px solid ${S.pink}` : '2px solid transparent',
                    borderRadius:'50%', width:38, height:38, display:'flex', alignItems:'center', justifyContent:'center',
                    cursor:'pointer', transition:'transform 120ms, border-color 120ms',
                    transform: active ? 'scale(1.08)' : 'scale(1)',
                  }}>
                  {em}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Snap-Shot (comment to DM) */}
      <AnimatePresence>
        {showSnapShot && (
          <motion.div initial={{ y:60, opacity:0 }} animate={{ y:0, opacity:1 }} exit={{ y:60, opacity:0 }}
            style={{ position:'absolute', bottom:0, left:0, right:0, zIndex:20, background:'rgba(20,20,30,0.97)', backdropFilter:'blur(16px)', borderTopLeftRadius:20, borderTopRightRadius:20, padding:'20px 20px 40px' }}
            onClick={e=>e.stopPropagation()}>
            <p style={{ color:'white', fontWeight:700, fontSize:15, marginBottom:4 }}>💬 Snap-Shot</p>
            <p style={{ color:S.gray, fontSize:12, marginBottom:14 }}>Your comment goes to their DMs as a notification</p>
            <textarea value={snapShotText} onChange={e=>setSnapShotText(e.target.value)} maxLength={200}
              placeholder="What did you think of this story?"
              style={{ width:'100%', background:'rgba(255,255,255,0.08)', border:`1px solid ${S.border}`, borderRadius:12, padding:'12px 14px', color:'white', fontSize:14, resize:'none', outline:'none', height:80, boxSizing:'border-box' }}/>
            <div style={{ display:'flex', gap:10, marginTop:10 }}>
              <button onClick={()=>{ setShowSnapShot(false); setPaused(false); }} style={{ flex:1, padding:'10px', borderRadius:12, background:'rgba(255,255,255,0.08)', color:S.gray, border:'none', cursor:'pointer' }}>Cancel</button>
              <button onClick={sendSnapShot} disabled={!snapShotText.trim()} style={{ flex:2, padding:'10px', borderRadius:12, background:snapShotText.trim()?S.pink:'rgba(255,32,85,0.3)', color:'white', fontWeight:700, border:'none', cursor:'pointer' }}>Send Snap-Shot</button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Viewers list (own stories only) */}
      <AnimatePresence>
        {showViewers && (
          <motion.div initial={{ y:60, opacity:0 }} animate={{ y:0, opacity:1 }} exit={{ y:60, opacity:0 }}
            style={{ position:'absolute', bottom:0, left:0, right:0, zIndex:20, background:'rgba(20,20,30,0.97)', backdropFilter:'blur(16px)', borderTopLeftRadius:20, borderTopRightRadius:20, padding:'20px 20px 40px', maxHeight:'60vh', overflowY:'auto' }}
            onClick={e=>e.stopPropagation()}>
            <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:14 }}>
              <p style={{ color:'white', fontWeight:700, fontSize:15, margin:0 }}>👁 {story.viewers?.length || 0} Views</p>
              <button onClick={()=>{ setShowViewers(false); setPaused(false); }} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={18} style={{ color:S.gray }}/></button>
            </div>
            <p style={{ color:S.gray, fontSize:11, marginBottom:12 }}>Posted {postedAgo}</p>
            {viewerList.length === 0
              ? <p style={{ color:S.gray, fontSize:13, textAlign:'center', padding:20 }}>No view data yet</p>
              : viewerList.map((v,i) => (
                <div key={i} style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 0', borderBottom:`1px solid ${S.border}` }}>
                  <div style={{ width:36, height:36, borderRadius:'50%', background:S.pink, display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontWeight:700, fontSize:13, overflow:'hidden', flexShrink:0 }}>
                    {v.avatarUrl ? <img src={mediaHref(v.avatarUrl)} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : (v.displayName||v.username||'U')[0].toUpperCase()}
                  </div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <p style={{ color:'white', fontSize:13, fontWeight:600, margin:0, display:'flex', alignItems:'center', gap:4 }}>{v.displayName||v.username||'User'}<AuthorBadges snapsaTier={v.authorSnapsaTier} size={12}/></p>
                    {v.viewedAt && <p style={{ color:S.gray, fontSize:10, margin:0 }}>{new Date(v.viewedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</p>}
                  </div>
                </div>
              ))}
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showAvatarFull && group.avatarUrl && (
          <motion.div
            initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
            style={{ position:'fixed', inset:0, zIndex:700, background:'rgba(0,0,0,.92)', display:'flex', alignItems:'center', justifyContent:'center' }}
            onClick={e => { e.stopPropagation(); setShowAvatarFull(false); setPaused(false); }}
          >
            <motion.img
              initial={{ scale:.7 }} animate={{ scale:1 }} exit={{ scale:.7 }}
              transition={{ type:'spring', damping:20, stiffness:250 }}
              src={mediaHref(group.avatarUrl)} alt=""
              style={{ width:280, height:280, borderRadius:'50%', border:`4px solid ${S.yellow}`, objectFit:'cover' }}
              onClick={e => e.stopPropagation()}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

const BuyCoinsModal = ({ currentUser, showToast, onClose, onPurchased }) => {
  const [balance, setBalance] = useState(currentUser?.coins || 0);
  const [customCoinAmount, setCustomCoinAmount] = useState('');
  const [buyingCoins, setBuyingCoins] = useState(false);

  useEffect(() => {
    let cancelled = false;
    snapFetch('/snapsa/wallet/balance')
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (d && !cancelled) setBalance(d.coins || 0); })
      .catch(() => {});
    return () => { cancelled = true; };
  }, []);

  const pollCustomCoinPurchase = (txRef, coins, attemptsLeft = 10) => {
    snapFetch(`/snapsa/coins/purchase/status/${txRef}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (d?.status === 'completed') {
          setBuyingCoins(false);
          setCustomCoinAmount('');
          showToast?.(`+${fmt(coins)} coins added!`, 'success');
          const next = d.newBalance != null ? d.newBalance : balance + coins;
          setBalance(next);
          onPurchased?.(next);
          return;
        }
        if (attemptsLeft > 0) setTimeout(() => pollCustomCoinPurchase(txRef, coins, attemptsLeft - 1), 1500);
        else { setBuyingCoins(false); showToast?.('Payment still processing — check back shortly', 'info'); }
      })
      .catch(() => setBuyingCoins(false));
  };

  const handleBuyCoins = async () => {
    const coins = Math.floor(Number(customCoinAmount));
    if (!coins || coins <= 0) { showToast?.('Enter how many Snapsa Coins to buy', 'error'); return; }
    if (currentUser?.isGuest) {
      showToast?.('Sign in to buy Snapsa Coin', 'info');
      window.dispatchEvent(new CustomEvent('snapsa:requestAuth'));
      return;
    }
    setBuyingCoins(true);
    try {
      const zarAmount = coins * SNAPSA_COIN_VALUE_ZAR;
      const initRes = await snapFetch('/snapsa/coins/purchase/custom/init', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ coins }),
      });
      if (!initRes.ok) throw new Error('init failed');
      const { txRef, amount } = await initRes.json();

      if (!FLW_PUBLIC_KEY) { showToast?.('Payments not configured yet', 'error'); setBuyingCoins(false); return; }
      await ensureFlutterwaveScript();
      window.FlutterwaveCheckout({
        public_key: FLW_PUBLIC_KEY,
        tx_ref: txRef,
        amount: amount != null ? amount : zarAmount,
        currency: 'ZAR',
        customer: { email: currentUser?.email || `${currentUser?._id || 'guest'}@snapsa.app` },
        customizations: { title: 'Snapsa Coin', description: `${fmt(coins)} Snapsa Coin` },
        callback: () => pollCustomCoinPurchase(txRef, coins),
        onclose: () => setBuyingCoins(false),
      });
    } catch {
      showToast?.('Could not start checkout', 'error');
      setBuyingCoins(false);
    }
  };

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'absolute', inset:0, background:'rgba(0,0,0,.75)', backdropFilter:'blur(4px)', zIndex:60, display:'flex', alignItems:'flex-end' }}
      onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
        onClick={e=>e.stopPropagation()}
        style={{ width:'100%', background:S.dark, borderTop:`1px solid ${S.border}`, borderRadius:'20px 20px 0 0', padding:20, paddingBottom:'calc(20px + env(safe-area-inset-bottom,0px))' }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16 }}>
          <h2 style={{ color:'white', fontWeight:800, fontSize:17 }}><SnapCoin/> Snapsa Coin</h2>
          <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={20} style={{ color:S.gray }}/></button>
        </div>

        <div style={{ background:'linear-gradient(135deg,#111827,#374151)', borderRadius:16, padding:20, color:'white', textAlign:'center', marginBottom:14 }}>
          <div style={{ fontSize:12, opacity:0.7, fontWeight:700, letterSpacing:0.5 }}>YOUR BALANCE</div>
          <div style={{ fontSize:36, fontWeight:900, marginTop:4 }}><SnapCoin/> {fmt(balance)}</div>
          <div style={{ fontSize:12, opacity:0.6, marginTop:2 }}>≈ {'$'}{((balance * SNAPSA_COIN_VALUE_USD)).toFixed(2)}</div>
        </div>

        <div>
          <label style={{ fontSize:13, fontWeight:700, color:'rgba(255,255,255,0.7)', display:'block', marginBottom:6 }}>
            How many Snapsa Coins?
          </label>
          <div style={{ display:'flex', alignItems:'center', gap:8, border:`2px solid ${S.border}`, borderRadius:12, padding:'10px 14px' }}>
            <span style={{ fontSize:20 }}><SnapCoin/></span>
            <input
              type="number"
              min="1"
              inputMode="numeric"
              value={customCoinAmount}
              onChange={e => setCustomCoinAmount(e.target.value.replace(/[^0-9]/g, ''))}
              placeholder="Enter amount"
              style={{ flex:1, border:'none', outline:'none', background:'transparent', fontSize:18, fontWeight:800, color:'white' }}
            />
          </div>

          <div style={{ display:'flex', gap:8, marginTop:10 }}>
            {[100, 500, 1000, 5000].map(n => (
              <button
                key={n}
                onClick={() => setCustomCoinAmount(String(n))}
                style={{
                  flex:1, padding:'8px 0', borderRadius:10, border:`1px solid ${S.border}`,
                  background: customCoinAmount === String(n) ? 'white' : 'transparent',
                  color: customCoinAmount === String(n) ? '#111827' : 'rgba(255,255,255,0.7)',
                  fontSize:12, fontWeight:700, cursor:'pointer',
                }}
              >
                {n.toLocaleString()}
              </button>
            ))}
          </div>
        </div>

        {Number(customCoinAmount) > 0 && (
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', padding:'14px 4px 0' }}>
            <span style={{ color:S.gray, fontSize:13 }}>Total</span>
            <span style={{ color:'white', fontWeight:800, fontSize:20 }}>
              {'$'}{((Number(customCoinAmount) * SNAPSA_COIN_VALUE_USD)).toFixed(2)}
            </span>
          </div>
        )}

        <button
          onClick={handleBuyCoins}
          disabled={buyingCoins || !Number(customCoinAmount)}
          style={{
            width:'100%', marginTop:16, padding:'15px 0', borderRadius:14, border:'none',
            background: 'linear-gradient(90deg,#fbbf24,#f97316)', color:'white', fontWeight:800, fontSize:15,
            cursor: (buyingCoins || !Number(customCoinAmount)) ? 'default' : 'pointer',
            opacity: (buyingCoins || !Number(customCoinAmount)) ? 0.5 : 1,
          }}
        >
          {buyingCoins ? 'Processing…' : Number(customCoinAmount) > 0 ? `Buy ${fmt(Number(customCoinAmount))} Coins` : 'Enter an amount'}
        </button>
      </motion.div>
    </motion.div>
  );
};

