// ─── Discover  ──────────────────────────────

let _activeDiscoverAudioEl = null;
const DiscoverScreen = ({ showToast, onViewProfile }) => {
  const [q,        setQ]        = useState('');
  const [results,  setResults]  = useState(null);
  const [trending, setTrending] = useState([]);
  const [loading,  setLoading]  = useState(false);
  const [tab,       setTab]     = useState('all'); // 'all' | 'users' | 'videos'
  const [view, setView] = useState('discover'); // 'discover' | 'shops'
  const [shops, setShops] = useState(null);
  const [shopsLoading, setShopsLoading] = useState(false);
  const [shopQ, setShopQ] = useState('');
  const [openStore, setOpenStore] = useState(null); // sellerId
  const debounceRef = useRef(null);

  useEffect(() => {
    snapFetch('/snapsa/videos/feed?sort=recent&limit=9').then(r=>r.ok?r.json():null).then(d=>{
      setTrending(d?.videos || []);
    }).catch(()=>{});
  }, []);

  useEffect(() => {
    if (view !== 'Snapsa Marketplace') return;
    setShopsLoading(true);
    const t = setTimeout(() => {
      snapFetch(`/snapsa/marketplace/stores${shopQ ? `?q=${encodeURIComponent(shopQ)}` : ''}`)
        .then(r => r.ok ? r.json() : null)
        .then(d => setShops(d?.stores || []))
        .catch(() => setShops([]))
        .finally(() => setShopsLoading(false));
    }, shopQ ? 300 : 0);
    return () => clearTimeout(t);
  }, [view, shopQ]);

  const doSearch = (val) => {
    clearTimeout(debounceRef.current);
    setQ(val);
    if (!val.trim()) { setResults(null); setTab('all'); return; }
    setLoading(true);
    debounceRef.current = setTimeout(async () => {
      try {
        const res = await snapFetch(`/snapsa/search?q=${encodeURIComponent(val)}`);
        setResults(res.ok ? await res.json() : { videos:[], sounds:[], users:[] });
      } catch { setResults({ videos:[], sounds:[], users:[] }); }
      setLoading(false);
    }, 350);
  };

  const playVideo = (v) => {
    window.dispatchEvent(new CustomEvent('snapsa:playVideo', { detail: { video: { ...v, videoUrl: mediaHref(v.videoUrl), thumbUrl: mediaHref(v.thumbUrl) } } }));
  };

  const cols = [S.pink,'#F59E0B','#10B981','#3B82F6','#8B5CF6'];
  const VideoTile = ({ v, autoplay = false }) => {
    const vidRef = useRef(null);

    const claimAudio = (el) => {
      if (_activeDiscoverAudioEl && _activeDiscoverAudioEl !== el) {
        try { _activeDiscoverAudioEl.muted = true; } catch {}
      }
      _activeDiscoverAudioEl = el;
      el.muted = false;
      el.play().catch(() => {
       
        el.muted = true;
        el.play().catch(()=>{});
      });
    };

    const unmuteOnInteract = (e) => claimAudio(e.currentTarget);

    useEffect(() => {
      const el = vidRef.current;
      if (!el) return;
      const io = new IntersectionObserver(([entry]) => {
        if (entry.isIntersecting && entry.intersectionRatio >= 0.6) {
          el.play().catch(()=>{});
        } else {
          el.pause();
          if (_activeDiscoverAudioEl === el) _activeDiscoverAudioEl = null;
        }
      }, { threshold: [0, 0.6, 1] });
      io.observe(el);
      return () => io.disconnect();
    }, []);

    useEffect(() => {
      if (autoplay && vidRef.current) claimAudio(vidRef.current);
    }, [autoplay]);

    return (
    <button
      onClick={()=>playVideo(v)}
      style={{ position:'relative', aspectRatio:'9/14', borderRadius:10, overflow:'hidden', background:'#1a1a24', border:'none', cursor:'pointer', padding:0 }}
    >
      {v.videoUrl ? (
        <video
          ref={vidRef}
          src={mediaHref(v.videoUrl)}
          poster={v.thumbUrl ? mediaHref(v.thumbUrl) : undefined}
          style={{ width:'100%', height:'100%', objectFit:'cover' }}
          muted={!autoplay} loop playsInline preload="metadata"
          autoPlay={autoplay}
          onMouseEnter={unmuteOnInteract}
          onTouchStart={unmuteOnInteract}
          onMouseLeave={e=>{ if(!autoplay){ e.currentTarget.muted = true; if (_activeDiscoverAudioEl === e.currentTarget) _activeDiscoverAudioEl = null; } }}
        />
      ) : v.thumbUrl ? (
        <img src={mediaHref(v.thumbUrl)} style={{ width:'100%', height:'100%', objectFit:'cover' }} alt=""
          onError={e=>{ e.target.style.display='none'; e.target.parentNode.style.background=S.card; }}/>
      ) : (
        <div style={{ width:'100%', height:'100%', background:`linear-gradient(135deg,${S.dark},${S.pink}44)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
          <Play size={20} style={{ color:S.gray }}/>
        </div>
      )}
      <div style={{ position:'absolute', bottom:0, left:0, right:0, padding:'16px 8px 6px', background:'linear-gradient(transparent,rgba(0,0,0,.75))' }}>
        <p style={{ color:'white', fontSize:11, fontWeight:600, textAlign:'left', overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>@{v.authorName||'snapsa'}</p>
        <div style={{ display:'flex', alignItems:'center', gap:3, marginTop:2 }}>
          <Play size={9} fill="white" style={{ color:'white' }}/>
          <span style={{ color:'white', fontSize:10 }}>{fmt(v.views||v.likes||0)}</span>
        </div>
      </div>
      <div style={{ position:'absolute', top:6, left:6 }}>
        <img src="/SnapsaLogo.png" alt="" style={{ width:14, height:14, borderRadius:'50%', opacity:0.85 }} onError={e=>e.target.style.display='none'}/>
      </div>
    </button>
    );
  };

  const UserRow = ({ u }) => (
    <button
      onClick={()=>onViewProfile?.({ authorId:u.userId||u.id, id:u.userId||u.id, authorName:u.username })}
      style={{ width:'100%', display:'flex', alignItems:'center', gap:12, padding:'10px 0', borderBottom:`1px solid ${S.border}`, background:'none', border:'none', cursor:'pointer', textAlign:'left' }}>
      <div style={{ width:44, height:44, borderRadius:'50%', background:S.pink, flexShrink:0, display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontWeight:800, fontSize:16, overflow:'hidden' }}>
        {u.avatarUrl ? <img src={mediaHref(u.avatarUrl)} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : (u.username?.[0]?.toUpperCase()||'S')}
      </div>
      <div style={{ flex:1, minWidth:0 }}>
        <div style={{ display:'flex', alignItems:'center', gap:6 }}>
          <span style={{ color:'white', fontWeight:700, fontSize:13 }}>@{u.username}</span>
          <AuthorBadges wernTier={u.tier} snapsaTier={u.snapsaTier} size={12} crew={u.crew}/>
        </div>
        {u.bio && <p style={{ color:S.gray, fontSize:11, marginTop:2, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{u.bio}</p>}
      </div>
      <span style={{ color:S.gray, fontSize:11 }}>{fmt(u.followerCount||0)} followers</span>
    </button>
  );

  return (
    <div style={{ flex:1, overflowY:'auto', background:'transparent', position:'relative', zIndex:1 }}>
      <div style={{ display:'flex', gap:8, padding:'14px 16px 0' }}>
        {[['discover','Discover'],['Snapsa Marketplace','Snapsa Marketplace']].map(([id,label]) => (
          <button key={id} onClick={()=>setView(id)}
            style={{ flex:1, padding:'9px', borderRadius:10, border:`1px solid ${view===id?S.pink:S.border}`, background:view===id?S.pink:'transparent', color:'white', fontSize:13, fontWeight:700, cursor:'pointer' }}>
            {label}
          </button>
        ))}
      </div>

      {view === 'Snapsa Marketplace' ? (
        <div style={{ padding:'14px 16px 16px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:10, background:S.card, borderRadius:12, padding:'11px 14px', border:`1px solid ${S.border}`, marginBottom:14 }}>
            <Search size={17} style={{ color:S.gray }}/>
            <input value={shopQ} onChange={e=>setShopQ(e.target.value)} placeholder="Search Snapsa Marketplace…"
              style={{ flex:1, background:'transparent', border:'none', outline:'none', color:'white', fontSize:14 }}/>
            {shopQ && <button onClick={()=>setShopQ('')} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={15} style={{ color:S.gray }}/></button>}
          </div>

          {shopsLoading && <p style={{ color:S.gray, textAlign:'center', padding:20, fontSize:13 }}>Loading Snapsa Marketplace…</p>}
          {!shopsLoading && shops?.length===0 && (
            <div style={{ textAlign:'center', padding:'40px 0' }}>
              <Store size={36} style={{ color:'rgba(255,255,255,0.12)', display:'block', margin:'0 auto 10px' }}/>
              <p style={{ color:S.gray, fontSize:13 }}>No shops found in the Snapsa Marketplace</p>
            </div>
          )}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(2,1fr)', gap:12 }}>
            {shops?.map(s => (
              <button key={s.sellerId} onClick={()=>setOpenStore(s.sellerId)}
                style={{ textAlign:'left', borderRadius:14, overflow:'hidden', background:S.card, border:`1px solid ${S.border}`, cursor:'pointer' }}>
                <div style={{ position:'relative', height:64, background: s.store?.bannerUrl ? `url(${s.store.bannerUrl}) center/cover` : `linear-gradient(135deg,#1a1a4e,${S.pink}44)` }}>
                  {(s.store?.avatarUrl || s.avatar) && (
                    <img src={s.store?.avatarUrl || s.avatar} alt="" style={{ position:'absolute', left:10, bottom:-14, width:32, height:32, borderRadius:'50%', objectFit:'cover', border:`2px solid ${S.card}` }}/>
                  )}
                </div>
                <div style={{ padding: (s.store?.avatarUrl || s.avatar) ? '20px 10px 12px' : '10px 10px 12px' }}>
                  <div style={{ display:'flex', alignItems:'center', gap:6 }}>
                    <p style={{ color:'white', fontSize:12, fontWeight:700, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{s.store?.name || `@${s.username}`}</p>
                    <AuthorBadges wernTier={s.tier} snapsaTier={s.snapsaTier} size={10} crew={s.crew}/>
                  </div>
                  <p style={{ color:S.gray, fontSize:10.5, marginTop:4 }}>{s.productCount} product{s.productCount===1?'':'s'}</p>
                </div>
              </button>
            ))}
          </div>

          {openStore && (
            <div style={{ position:'fixed', inset:0, zIndex:80, background:S.dark }}>
              <StoreScreen sellerId={openStore} isOwner={false} currentUser={null} showToast={showToast} onBack={()=>setOpenStore(null)}/>
            </div>
          )}
        </div>
      ) : (
      <>
      <div style={{ padding:'14px 16px 8px' }}>
        <div style={{ display:'flex', alignItems:'center', gap:10, background:S.card, borderRadius:12, padding:'11px 14px', border:`1px solid ${S.border}` }}>
          <Search size={17} style={{ color:S.gray }}/>
          <input value={q} onChange={e=>doSearch(e.target.value)} placeholder="Search videos, creators, sounds…"
            style={{ flex:1, background:'transparent', border:'none', outline:'none', color:'white', fontSize:14 }}/>
          {q && <button onClick={()=>doSearch('')} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={15} style={{ color:S.gray }}/></button>}
        </div>
      </div>

      {results && !loading && (
        <div style={{ display:'flex', gap:6, padding:'0 16px 10px' }}>
          {[['all','All'],['users','Users'],['videos','Videos']].map(([id,label]) => (
            <button key={id} onClick={()=>setTab(id)}
              style={{ padding:'6px 16px', borderRadius:999, border:`1px solid ${tab===id?S.pink:S.border}`, background:tab===id?S.pink:'transparent', color:'white', fontSize:12, fontWeight:700, cursor:'pointer' }}>
              {label}
            </button>
          ))}
        </div>
      )}

      {loading && <p style={{ color:S.gray, textAlign:'center', padding:20, fontSize:13 }}>Searching…</p>}

      {results && !loading && (
        <div style={{ padding:'0 16px 16px' }}>
          {(results.videos?.length||0)===0 && (results.users?.length||0)===0 && (results.sounds?.length||0)===0 && (
            <p style={{ color:S.gray, fontSize:13, textAlign:'center', paddingTop:20 }}>No results for "{q}"</p>
          )}

          {/* Users tab (and the Users section of All) */}
          {(tab==='all' || tab==='users') && results.users?.length>0 && (
            <div style={{ marginBottom: tab==='all' ? 16 : 0 }}>
              {tab==='all' && <h3 style={{ color:'white', fontWeight:700, fontSize:13, marginBottom:8 }}>Users</h3>}
              {results.users.map(u => <UserRow key={u.userId||u.id} u={u}/>)}
            </div>
          )}

          {/* Videos tab (and the Videos section of All) — first result autoplays */}
          {(tab==='all' || tab==='videos') && results.videos?.length>0 && (
            <div>
              {tab==='all' && <h3 style={{ color:'white', fontWeight:700, fontSize:13, marginBottom:8 }}>Videos</h3>}
              <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:6 }}>
                {results.videos.map((v,i) => <VideoTile key={v.id||v._id} v={v} autoplay={i===0}/>)}
              </div>
            </div>
          )}

          {tab==='all' && results.sounds?.length>0 && (
            <div style={{ marginTop:16 }}>
              <h3 style={{ color:'white', fontWeight:700, fontSize:13, marginBottom:8 }}>Sounds</h3>
              {results.sounds.map(s => (
                <div key={s.id} style={{ display:'flex', alignItems:'center', gap:12, padding:'10px 0', borderBottom:`1px solid ${S.border}` }}>
                  <div style={{ width:44, height:44, borderRadius:10, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
                    <Music2 size={18} style={{ color:'white' }}/>
                  </div>
                  <div>
                    <p style={{ color:'white', fontWeight:600, fontSize:13 }}>{s.title}</p>
                    <p style={{ color:S.gray, fontSize:11 }}>{s.artist} · {s.uses} uses</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Default landing state  */}
      {!results && !loading && (
        <div style={{ padding:'0 16px 16px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:12 }}>
            <Sparkles size={14} style={{ color:S.pink }}/>
            <h3 style={{ color:'white', fontWeight:700, fontSize:14 }}>Recent</h3>
          </div>
          {trending.length===0 && <p style={{ color:S.gray, fontSize:13 }}>You Seem Offline, Restore your Internet</p>}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:6 }}>
            {trending.map(v => <VideoTile key={v.id||v._id} v={v}/>)}
          </div>
        </div>
      )}
      </>
      )}
    </div>
  );
};

// ─── Music Screen — Snapsa Music Marketplace ───────────────────────────
const FLW_PUBLIC_KEY = import.meta?.env?.VITE_FLW_PUBLIC_KEY || '';
let _flwScriptPromise = null;
const ensureFlutterwaveScript = () => {
  if (window.FlutterwaveCheckout) return Promise.resolve();
  if (_flwScriptPromise) return _flwScriptPromise;
  _flwScriptPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://checkout.flutterwave.com/v3.js';
    s.onload = resolve;
    s.onerror = () => reject(new Error('Could not load payment SDK'));
    document.body.appendChild(s);
  });
  return _flwScriptPromise;
};

const MusicTrackCard = ({ track, isPlayingPreview, purchasing, onTogglePreview, onBuy, onPlayFull, onDownload, onUseSound, onShowDetails }) => {
  const owned = !!track.owned;
  return (
    <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', borderBottom:`1px solid ${S.border}` }}>
      <button onClick={()=>onShowDetails(track)}
        style={{ position:'relative', width:52, height:52, borderRadius:12, flexShrink:0, border:'none', cursor:'pointer', overflow:'hidden',
          background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
        {track.coverUrl && <img src={track.coverUrl} alt="" style={{ position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover' }}/>}
        <div style={{ position:'relative' }}>
          {isPlayingPreview
            ? <Pause size={20} style={{ color:'white' }}/>
            : <Music2 size={20} style={{ color:'white', opacity: track.coverUrl ? 0 : 1 }}/>}
        </div>
        {!owned && (
          <div style={{ position:'absolute', bottom:-4, right:-4, background:S.yellow, borderRadius:6, padding:'1px 4px', fontSize:8, fontWeight:800, color:'#000' }}>
            30s
          </div>
        )}
      </button>

      <div style={{ flex:1, minWidth:0 }}>
        <p style={{ color:'white', fontWeight:700, fontSize:14, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>
          {track.title}
        </p>
        <div style={{ display:'flex', alignItems:'center', gap:4 }}>
          <span style={{ color:S.pink, fontSize:12, fontWeight:600 }}>@{track.artistName || 'unknown'}</span>
          {track.artistVerified && <BadgeCheck size={12} style={{ color:S.pink }}/>}
          {track.album && <span style={{ color:S.gray, fontSize:11 }}>· {track.album}</span>}
        </div>
        <p style={{ color:S.gray, fontSize:11, marginTop:2 }}>
          {fmt(track.purchaseCount||0)} bought · {fmt(track.playCount||0)} plays
        </p>
      </div>

      <div style={{ display:'flex', flexDirection:'column', gap:6, alignItems:'flex-end', flexShrink:0 }}>
        <button onClick={()=>onUseSound(track)}
          style={{ display:'flex', alignItems:'center', gap:4, background:'none', border:'none', cursor:'pointer', padding:0 }}>
          <span style={{ color:S.gray, fontSize:10, fontWeight:600 }}>Use sound</span>
        </button>
        {owned ? (
          <div style={{ display:'flex', gap:6 }}>
            <button onClick={()=>onPlayFull(track)}
              style={{ display:'flex', alignItems:'center', gap:4, background:S.card, border:`1px solid ${S.border}`, borderRadius:999, padding:'6px 10px', cursor:'pointer' }}>
              <Play size={12} style={{ color:'white' }} fill="white"/>
            </button>
            <button onClick={()=>onDownload(track)}
              style={{ display:'flex', alignItems:'center', gap:4, background:S.card, border:`1px solid ${S.border}`, borderRadius:999, padding:'6px 10px', cursor:'pointer' }}>
              <Download size={12} style={{ color:'white' }}/>
            </button>
          </div>
        ) : (
          <button onClick={()=>onBuy(track)} disabled={purchasing}
            style={{ display:'flex', alignItems:'center', gap:6, background:purchasing?S.border:S.pink, border:'none', borderRadius:999, padding:'8px 14px', cursor:purchasing?'default':'pointer' }}>
            <ShoppingBag size={12} style={{ color:'white' }}/>
            <span style={{ color:'white', fontSize:12, fontWeight:700 }}>
              {purchasing ? 'Processing…' : `$${Number.isFinite(track.priceUsd) ? track.priceUsd.toFixed(2) : (track.price != null ? (track.price/100).toFixed(2) : '1.00')}`}
            </span>
          </button>
        )}
      </div>
    </div>
  );
};

const emptyAlbumTrack = () => ({ key: Math.random().toString(36).slice(2), title:'', genre:'', fullFile:null, previewFile:null, videoFile:null });

const MusicUploadModal = ({ onClose, showToast, onUploaded, artistProfile, onArtistProfileSaved }) => {
  const needsArtistProfile = !artistProfile?.enabled;
  const artistPending = artistProfile?.status === 'pending';
  const [artistName, setArtistName] = useState(artistProfile?.artistName || '');
  const [artistCountry, setArtistCountry] = useState(artistProfile?.country || '');
  const [mode, setMode] = useState('single'); // 'single' | 'album'
  const [contentType, setContentType] = useState('track'); // 'track' | 'video' — single-track uploads only
  const [title, setTitle] = useState('');       // single-track title
  const [genre, setGenre] = useState('');        // single-track genre
  const [albumTitle, setAlbumTitle] = useState('');
  const [albumTracks, setAlbumTracks] = useState([emptyAlbumTrack(), emptyAlbumTrack()]);
  const [fullFile, setFullFile] = useState(null);
  const [previewFile, setPreviewFile] = useState(null);
  const [musicVideoFile, setMusicVideoFile] = useState(null);
  const [thumbnail, setThumbnail] = useState(null);
  const [thumbnailPreviewUrl, setThumbnailPreviewUrl] = useState(null);
  const [price, setPrice] = useState('1.00');
  const [isFree, setIsFree] = useState(false);
  const [adSupported, setAdSupported] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [agreedToRights, setAgreedToRights] = useState(false);
  const uploadInFlightRef = useRef(false);

  const pickThumbnail = (file) => {
    setThumbnail(file);
    setThumbnailPreviewUrl(file ? URL.createObjectURL(file) : null);
  };

  const [fullFileUrl, setFullFileUrl] = useState(null);
  const [previewFileUrl, setPreviewFileUrl] = useState(null);
  const [musicVideoFileUrl, setMusicVideoFileUrl] = useState(null);
  useEffect(() => {
    if (!fullFile) { setFullFileUrl(null); return; }
    const url = URL.createObjectURL(fullFile);
    setFullFileUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [fullFile]);
  useEffect(() => {
    if (!previewFile) { setPreviewFileUrl(null); return; }
    const url = URL.createObjectURL(previewFile);
    setPreviewFileUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [previewFile]);
  useEffect(() => {
    if (!musicVideoFile) { setMusicVideoFileUrl(null); return; }
    const url = URL.createObjectURL(musicVideoFile);
    setMusicVideoFileUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [musicVideoFile]);

  const objectUrlCacheRef = useRef(new Map());
  const getCachedObjectUrl = (file) => {
    if (!file) return null;
    const cache = objectUrlCacheRef.current;
    if (!cache.has(file)) cache.set(file, URL.createObjectURL(file));
    return cache.get(file);
  };
  useEffect(() => () => {
    objectUrlCacheRef.current.forEach(url => URL.revokeObjectURL(url));
  }, []);

  const updateAlbumTrack = (key, patch) => setAlbumTracks(prev => prev.map(t => t.key===key ? { ...t, ...patch } : t));
  const addAlbumTrack = () => setAlbumTracks(prev => [...prev, emptyAlbumTrack()]);
  const removeAlbumTrack = (key) => setAlbumTracks(prev => prev.length > 2 ? prev.filter(t => t.key!==key) : prev);

  const ensureArtistProfile = async () => {
    if (!needsArtistProfile) return true;
    if (!artistName.trim()) { showToast?.('Enter an artist name', 'error'); return false; }
    if (!artistCountry.trim()) { showToast?.('Enter your country', 'error'); return false; }
    try {
      const res = await snapFetch('/snapsa/music/artist-profile', {
        method: 'POST',
        body: JSON.stringify({ artistName: artistName.trim(), country: artistCountry.trim() }),
      });
      const data = await res.json();
      if (!res.ok || !data?.artistProfile) throw new Error(data.error || 'Could not create artist profile');
      onArtistProfileSaved?.(data.artistProfile);
      if (!data.artistProfile.enabled) {
        showToast?.('⏳ Sent to the admin for approval — you can upload once it is approved.', 'success');
        return false;
      }
      return true;

    } catch (err) {
      showToast?.(err.message || 'Could not create artist profile', 'error');
      return false;
    }
  };

  const handleUploadSingle = async () => {
    if (uploadInFlightRef.current) return;
    const hasRequiredMedia = contentType === 'track' ? !!fullFile : !!musicVideoFile;
    if (!title.trim() || !hasRequiredMedia) {
      showToast?.(contentType === 'track' ? 'Add a title and the full track' : 'Add a title and the music video', 'error');
      return;
    }
    if (!agreedToRights) { showToast?.('You must confirm the copyright agreement before uploading', 'error'); return; }
    uploadInFlightRef.current = true;
    setUploading(true);
    setUploadProgress(0);
    try {
      if (!(await ensureArtistProfile())) { setUploading(false); return; }
      const fd = new FormData();
      fd.append('title', title.trim());
      if (genre) fd.append('genre', genre);
      if (fullFile) fd.append('audio', fullFile);
      if (previewFile) fd.append('preview', previewFile);
      if (musicVideoFile) fd.append('musicVideo', musicVideoFile);
      fd.append('price', price);
      fd.append('isFree', isFree ? 'true' : 'false');
      fd.append('adSupported', (!isFree && adSupported) ? 'true' : 'false');
      if (thumbnail) fd.append('thumbnail', thumbnail);
      fd.append('copyrightAgreementAccepted', 'true');

      const res = await snapUploadWithProgress('/snapsa/music/tracks/upload', fd, { onProgress: setUploadProgress });
      if (!res.ok) throw new Error(res.json?.error || 'Upload failed');
      showToast?.('🎵 Track submitted!', 'success');
      onUploaded?.();
      onClose();
    } catch (err) {
      showToast?.(err.message || 'Upload failed — try again', 'error');
    } finally {
      uploadInFlightRef.current = false;
      setUploading(false);
      setUploadProgress(0);
    }
  };

  const handleUploadAlbum = async () => {
    if (uploadInFlightRef.current) return;
    if (!albumTitle.trim()) { showToast?.('Give the album a title', 'error'); return; }
    if (albumTracks.some(t => !t.title.trim() || !t.fullFile)) {
      showToast?.('Every track needs a title and its full audio file', 'error');
      return;
    }
    if (!agreedToRights) { showToast?.('You must confirm the copyright agreement before uploading', 'error'); return; }
    uploadInFlightRef.current = true;
    setUploading(true);
    setUploadProgress(0);
    try {
      if (!(await ensureArtistProfile())) { setUploading(false); return; }
      const fd = new FormData();
      fd.append('albumTitle', albumTitle.trim());
      if (genre) fd.append('genre', genre);
      fd.append('price', price);
    fd.append('isFree', isFree ? 'true' : 'false');
      fd.append('adSupported', (!isFree && adSupported) ? 'true' : 'false');
      fd.append('titles', JSON.stringify(albumTracks.map(t => t.title.trim())));
      albumTracks.forEach(t => fd.append('audio', t.fullFile));
      
      const previewIndexes = [];
      albumTracks.forEach((t, i) => { if (t.previewFile) { fd.append('preview', t.previewFile); previewIndexes.push(i); } });
      fd.append('previewIndexes', JSON.stringify(previewIndexes));

      const videoIndexes = [];
      albumTracks.forEach((t, i) => { if (t.videoFile) { fd.append('musicVideo', t.videoFile); videoIndexes.push(i); } });
      fd.append('videoIndexes', JSON.stringify(videoIndexes));

      if (thumbnail) fd.append('thumbnail', thumbnail);
      fd.append('copyrightAgreementAccepted', 'true');

      const res = await snapUploadWithProgress('/snapsa/music/tracks/upload-album', fd, { onProgress: setUploadProgress, timeoutMs: 5 * 60 * 1000 });
      if (!res.ok) throw new Error(res.json?.error || 'Album upload failed');
      showToast?.(`🎵 Album with ${albumTracks.length} tracks submitted!`, 'success');
      onUploaded?.();
      onClose();
    } catch (err) {
      showToast?.(err.message || 'Upload failed — try again', 'error');
    } finally {
      uploadInFlightRef.current = false;
      setUploading(false);
      setUploadProgress(0);
    }
  };

  const canSubmit = !uploading && agreedToRights && !artistPending && (!needsArtistProfile || (artistName.trim() && artistCountry.trim())) && (
    mode === 'single'
      ? title.trim() && (contentType === 'track' ? fullFile : musicVideoFile)
      : albumTitle.trim() && albumTracks.every(t => t.title.trim() && t.fullFile)
  );

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.85)', zIndex:70, display:'flex', alignItems:'flex-end' }}
      onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
        onClick={e=>e.stopPropagation()}
        style={{ width:'100%', background:S.dark, borderTop:`1px solid ${S.border}`, borderRadius:'20px 20px 0 0', padding:20, paddingBottom:'calc(20px + env(safe-area-inset-bottom,0px))', maxHeight:'88vh', overflowY:'auto' }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16 }}>
          <h2 style={{ color:'white', fontWeight:800, fontSize:17 }}>{mode==='single' ? 'Upload a Track' : 'Upload an Album'}</h2>
          <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={20} style={{ color:S.gray }}/></button>
        </div>

                {artistPending && <div style={{ display:'flex', marginBottom:16 }}><CreatorStatusCard profile={artistProfile}/></div>}
        {needsArtistProfile && !artistPending && (
          <div style={{ background:S.card, border:`1px solid ${S.border}`, borderRadius:12, padding:14, marginBottom:16 }}>
            <p style={{ color:'white', fontWeight:700, fontSize:13.5, marginBottom:4 }}>Set up your artist name</p>
            <p style={{ color:S.gray, fontSize:12, lineHeight:1.5, marginBottom:12 }}>
              This is what listeners see as the artist — separate from your @username. Only needs to be done once.
            </p>
            <input value={artistName} onChange={e=>setArtistName(e.target.value.slice(0,60))} placeholder="Artist name"
              style={{ width:'100%', background:S.dark, border:`1px solid ${S.border}`, borderRadius:10, padding:'11px 14px', color:'white', outline:'none', fontSize:14, marginBottom:8, boxSizing:'border-box' }}/>
            <input value={artistCountry} onChange={e=>setArtistCountry(e.target.value.slice(0,60))} placeholder="Country"
              style={{ width:'100%', background:S.dark, border:`1px solid ${S.border}`, borderRadius:10, padding:'11px 14px', color:'white', outline:'none', fontSize:14, boxSizing:'border-box' }}/>
          </div>
        )}

        {/* Single vs Album */}
        <div style={{ display:'flex', gap:8, marginBottom:16 }}>
          {[['single','Single'],['album','Album']].map(([id,label]) => (
            <button key={id} onClick={()=>setMode(id)}
              style={{ flex:1, padding:'9px 0', borderRadius:999, border:'none', cursor:'pointer',
                background: mode===id ? S.pink : S.card, color: mode===id ? 'white' : S.gray, fontWeight:700, fontSize:13 }}>
              {label}
            </button>
          ))}
        </div>

        {/* Shared thumbnail picker */}
        <label style={{ display:'flex', alignItems:'center', gap:12, background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'10px 14px', marginBottom:12, cursor:'pointer' }}>
          <div style={{ width:44, height:44, borderRadius:8, overflow:'hidden', flexShrink:0, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
            {thumbnailPreviewUrl ? <img src={thumbnailPreviewUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <ImagePlus size={18} style={{ color:'white' }}/>}
          </div>
          <span style={{ color:thumbnail?'white':S.gray, fontSize:13, flex:1 }}>{thumbnail ? thumbnail.name : (mode==='single' ? 'Track thumbnail (optional)' : 'Album cover (optional)')}</span>
          <Upload size={16} style={{ color:S.pink }}/>
          <input type="file" accept="image/*" style={{ display:'none' }} onChange={e=>pickThumbnail(e.target.files?.[0]||null)}/>
        </label>

        {mode === 'single' ? (
          <>
            <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Track title"
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:12, boxSizing:'border-box' }}/>

            <select value={genre} onChange={e=>setGenre(e.target.value)}
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color: genre ? 'white' : S.gray, outline:'none', fontSize:14, marginBottom:12, boxSizing:'border-box' }}>
              <option value="">Genre (optional)</option>
              {MUSIC_GENRES.map(g => <option key={g} value={g}>{g}</option>)}
            </select>

            {/* Track vs music video — determines which upload is required below */}
            <div style={{ display:'flex', gap:8, marginBottom:12 }}>
              {[['track','Music track'],['video','Music video']].map(([id,label]) => (
                <button key={id} onClick={()=>setContentType(id)}
                  style={{ flex:1, padding:'8px 0', borderRadius:999, border:'none', cursor:'pointer',
                    background: contentType===id ? S.pink : S.card, color: contentType===id ? 'white' : S.gray, fontWeight:700, fontSize:12.5 }}>
                  {label}
                </button>
              ))}
            </div>

            {contentType === 'track' && (
              <div style={{ marginBottom:10 }}>
                <label style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', cursor:'pointer' }}>
                  <span style={{ color:fullFile?'white':S.gray, fontSize:13 }}>{fullFile ? fullFile.name : 'Full track (mp3/wav)'}</span>
                  <Upload size={16} style={{ color:S.pink }}/>
                  <input type="file" accept="audio/*" style={{ display:'none' }} onChange={e=>setFullFile(e.target.files?.[0]||null)}/>
                </label>
                {fullFileUrl && (
                  <audio controls src={fullFileUrl} style={{ width:'100%', height:32, marginTop:6 }} />
                )}
              </div>
            )}

            {contentType === 'track' && (
              <div style={{ marginBottom:16 }}>
                <label style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', cursor:'pointer' }}>
                  <span style={{ color:previewFile?'white':S.gray, fontSize:13 }}>{previewFile ? previewFile.name : 'Preview clip (optional)'}</span>
                  <Upload size={16} style={{ color:S.pink }}/>
                  <input type="file" accept="audio/*" style={{ display:'none' }} onChange={e=>setPreviewFile(e.target.files?.[0]||null)}/>
                </label>
                {previewFileUrl && (
                  <audio controls src={previewFileUrl} style={{ width:'100%', height:32, marginTop:6 }} />
                )}
              </div>
            )}

            <div style={{ marginBottom:16 }}>
              <label style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', cursor:'pointer' }}>
                <span style={{ color:musicVideoFile?'white':S.gray, fontSize:13 }}>{musicVideoFile ? musicVideoFile.name : (contentType === 'video' ? 'Music video' : 'Music video (optional)')}</span>
                <Upload size={16} style={{ color:S.pink }}/>
                <input type="file" accept="video/*" style={{ display:'none' }} onChange={e=>setMusicVideoFile(e.target.files?.[0]||null)}/>
              </label>
              {musicVideoFileUrl && (
                <video controls src={musicVideoFileUrl} style={{ width:'100%', maxHeight:180, marginTop:6, borderRadius:8 }} />
              )}
            </div>
          </>
        ) : (
          <>
            <input value={albumTitle} onChange={e=>setAlbumTitle(e.target.value)} placeholder="Album title"
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:12, boxSizing:'border-box' }}/>

            <select value={genre} onChange={e=>setGenre(e.target.value)}
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color: genre ? 'white' : S.gray, outline:'none', fontSize:14, marginBottom:12, boxSizing:'border-box' }}>
              <option value="">Genre for all tracks (optional)</option>
              {MUSIC_GENRES.map(g => <option key={g} value={g}>{g}</option>)}
            </select>

            {albumTracks.map((t, i) => (
              <div key={t.key} style={{ background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:12, marginBottom:10 }}>
                <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:8 }}>
                  <span style={{ color:S.gray, fontSize:11, fontWeight:700 }}>TRACK {i+1}</span>
                  {albumTracks.length > 2 && (
                    <button onClick={()=>removeAlbumTrack(t.key)} style={{ background:'none', border:'none', cursor:'pointer' }}>
                      <X size={14} style={{ color:S.gray }}/>
                    </button>
                  )}
                </div>
                <input value={t.title} onChange={e=>updateAlbumTrack(t.key, { title:e.target.value })} placeholder={`Track ${i+1} title`}
                  style={{ width:'100%', background:S.dark, border:`1px solid ${S.border}`, borderRadius:8, padding:'10px 12px', color:'white', outline:'none', fontSize:13, marginBottom:8, boxSizing:'border-box' }}/>
                <label style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:S.dark, border:`1px solid ${S.border}`, borderRadius:8, padding:'9px 12px', marginBottom:6, cursor:'pointer' }}>
                  <span style={{ color:t.fullFile?'white':S.gray, fontSize:12 }}>{t.fullFile ? t.fullFile.name : 'Full track audio'}</span>
                  <Upload size={14} style={{ color:S.pink }}/>
                  <input type="file" accept="audio/*" style={{ display:'none' }} onChange={e=>updateAlbumTrack(t.key, { fullFile:e.target.files?.[0]||null })}/>
                </label>
                {t.fullFile && (
                  <audio controls src={getCachedObjectUrl(t.fullFile)} style={{ width:'100%', height:30, marginBottom:6 }} />
                )}
                <label style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:S.dark, border:`1px solid ${S.border}`, borderRadius:8, padding:'9px 12px', marginBottom:6, cursor:'pointer' }}>
                  <span style={{ color:t.previewFile?'white':S.gray, fontSize:12 }}>{t.previewFile ? t.previewFile.name : 'Preview clip (optional)'}</span>
                  <Upload size={14} style={{ color:S.pink }}/>
                  <input type="file" accept="audio/*" style={{ display:'none' }} onChange={e=>updateAlbumTrack(t.key, { previewFile:e.target.files?.[0]||null })}/>
                </label>
                {t.previewFile && (
                  <audio controls src={getCachedObjectUrl(t.previewFile)} style={{ width:'100%', height:30, marginBottom:6 }} />
                )}
                <label style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:S.dark, border:`1px solid ${S.border}`, borderRadius:8, padding:'9px 12px', cursor:'pointer' }}>
                  <span style={{ color:t.videoFile?'white':S.gray, fontSize:12 }}>{t.videoFile ? t.videoFile.name : 'Music video (optional)'}</span>
                  <Upload size={14} style={{ color:S.pink }}/>
                  <input type="file" accept="video/*" style={{ display:'none' }} onChange={e=>updateAlbumTrack(t.key, { videoFile:e.target.files?.[0]||null })}/>
                </label>
                {t.videoFile && (
                  <video controls src={getCachedObjectUrl(t.videoFile)} style={{ width:'100%', maxHeight:150, marginTop:6, borderRadius:6 }} />
                )}
              </div>
            ))}
            <button onClick={addAlbumTrack} style={{ width:'100%', display:'flex', alignItems:'center', justifyContent:'center', gap:6, background:'none', border:`1px dashed ${S.border}`, borderRadius:10, padding:'10px', marginBottom:16, cursor:'pointer' }}>
              <Plus size={14} style={{ color:S.pink }}/>
              <span style={{ color:S.pink, fontSize:13, fontWeight:600 }}>Add another track</span>
            </button>
          </>
        )}

        {/* Free / paid toggle */}
        <button type="button" onClick={()=>setIsFree(v=>!v)}
          style={{ display:'flex', alignItems:'center', gap:10, width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:12, cursor:'pointer', textAlign:'left' }}>
          <div style={{ width:20, height:20, borderRadius:6, border:`2px solid ${isFree?S.pink:S.gray}`, background:isFree?S.pink:'transparent', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
            {isFree && <Check size={13} style={{ color:'white' }}/>}
          </div>
          <div>
            <p style={{ color:'white', fontSize:13, fontWeight:700, margin:0 }}>Make this {mode==='album'?'album':'track'} free</p>
            <p style={{ color:S.gray, fontSize:11, margin:'2px 0 0' }}>Anyone can play it in full, no purchase needed</p>
          </div>
        </button>

        {/* Price */}
        {!isFree && (
        <div style={{ marginBottom:12 }}>
          <label style={{ display:'block', color:S.gray, fontSize:12, fontWeight:600, marginBottom:6 }}>
            {mode==='single' ? 'Price per track (USD)' : 'Price per track in this album (USD)'}
          </label>
          <div style={{ display:'flex', alignItems:'center', gap:8, background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'10px 14px' }}>
            <span style={{ color:'white', fontSize:14 }}>$</span>
            <input value={price} onChange={e=>setPrice(e.target.value.replace(/[^0-9.]/g,''))} inputMode="decimal" placeholder="1.00"
              style={{ flex:1, background:'transparent', border:'none', outline:'none', color:'white', fontSize:14 }}/>
          </div>
        </div>
        )}

        {!isFree && (
        <div style={{ background:`${S.pink}12`, border:`1px solid ${S.pink}33`, borderRadius:10, padding:'10px 12px', marginBottom:12 }}>
          <p style={{ color:'white', fontSize:12, lineHeight:1.5, margin:0 }}>
            You'll keep <strong style={{ color:S.yellow }}>70%</strong> of every sale.
          </p>
        </div>
        )}
                {!isFree && (
          <label style={{ display:'flex', alignItems:'flex-start', gap:10, background:S.card, border:`1px solid ${adSupported ? S.pink : S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:12, cursor:'pointer' }}>
            <input type="checkbox" checked={adSupported} onChange={e=>setAdSupported(e.target.checked)} style={{ marginTop:3 }}/>
            <span style={{ color:'white', fontSize:12.5, lineHeight:1.5 }}>
              <strong>Also let people listen with ads</strong><br/>
              <span style={{ color:S.gray }}>Listeners who don't buy can play the full track free after watching one ad. Buying still removes the ad.</span>
            </span>
          </label>
        )}

        {/* Real, required copyright agreement — must be actively checked, not just
            passive text, so Snapsa has an actual accepted-by-this-user record. */}
        <label style={{
          display:'flex', alignItems:'flex-start', gap:10, background:S.card,
          border:`1px solid ${agreedToRights?S.pink:S.border}`, borderRadius:10,
          padding:'12px 14px', marginBottom:16, cursor:'pointer'
        }}>
          <input
            type="checkbox"
            checked={agreedToRights}
            onChange={e=>setAgreedToRights(e.target.checked)}
            style={{ marginTop:2, width:16, height:16, accentColor:S.pink, flexShrink:0, cursor:'pointer' }}
          />
          <span style={{ color:'rgba(255,255,255,0.85)', fontSize:12, lineHeight:1.5 }}>
            I confirm I own the rights to this recording, or have permission to distribute it,
            and I agree to hold Snapsa harmless from any copyright claims arising from this upload.
            I grant Snapsa a license to use any preview clip or music video I upload in creator videos.
          </span>
        </label>

        {uploading && (
          <div style={{ marginBottom:10 }}>
            <div style={{ width:'100%', height:6, borderRadius:999, background:S.card, overflow:'hidden' }}>
              <div style={{ width:`${uploadProgress}%`, height:'100%', background:S.pink, transition:'width .15s linear' }} />
            </div>
            <p style={{ color:S.gray, fontSize:11, marginTop:4, textAlign:'center' }}>
              {uploadProgress > 0 ? `Uploading… ${uploadProgress}%` : 'Starting upload…'}
            </p>
          </div>
        )}

        <button onClick={mode==='single' ? handleUploadSingle : handleUploadAlbum} disabled={!canSubmit}
          style={{ width:'100%', background: canSubmit?S.pink:S.border, border:'none', borderRadius:999, padding:'13px', color:'white', fontWeight:700, fontSize:14, cursor:canSubmit?'pointer':'not-allowed', opacity:canSubmit?1:.6 }}>
          {uploading ? `Uploading… ${uploadProgress}%` : mode==='single' ? 'Submit Track' : `Submit Album (${albumTracks.length} tracks)`}
        </button>
      </motion.div>
    </motion.div>
  );
};

// ─── Artist profile — required once before a user can upload music
 // ─── Creator profile approval status (shown while a profile waits for admin review, or after a rejection)
const CreatorStatusCard = ({ profile, onEdit }) => {
  const rejected = profile?.status === 'rejected';
  return (
    <div style={{ flex:1, background:S.card, border:`1px solid ${rejected ? '#ef4444' : S.border}`, borderRadius:12, padding:'12px 14px' }}>
      <p style={{ color:'white', fontWeight:700, fontSize:13.5, marginBottom:4 }}>
        {rejected ? '❌ Not approved' : '⏳ Waiting for approval'}{profile?.artistName ? ` · ${profile.artistName}` : ''}
      </p>
      <p style={{ color:S.gray, fontSize:12, lineHeight:1.5, marginBottom:10 }}>
        {rejected
          ? (profile.reviewNote || 'Your request was not approved. You can fix the details and apply again.')
          : 'An admin is reviewing your profile. You will get a notification as soon as it is approved.'}
      </p>
      {onEdit && (
        <button onClick={onEdit}
          style={{ padding:'8px 14px', borderRadius:9, border:`1px solid ${S.border}`, background:'transparent', color:S.pink, fontWeight:700, fontSize:12.5, cursor:'pointer' }}>
          {rejected ? 'Edit & apply again' : 'Edit request'}
        </button>
      )}
    </div>
  );
};

// ─── Admin dashboard → Creator approvals (music, TV, radio, podcast, news)
const CreatorApprovalsAdminScreen = ({ onClose, showToast }) => {
  const [view, setView] = useState('pending');
  const [data, setData] = useState(null);
  const [busyKey, setBusyKey] = useState(null);
  const [rejecting, setRejecting] = useState(null);
  const [reason, setReason] = useState('');

  const load = (v = view) => {
    setData(null);
    snapFetch(`/snapsa/admin/creator-profiles?view=${v}`).then(r => r.ok ? r.json() : null)
      .then(d => setData(d || { items: [], counts: {} })).catch(() => setData({ items: [], counts: {} }));
  };
  useEffect(() => { load(view); }, [view]);

  const act = async (it, action, body, okMsg) => {
    const key = `${it.userId}:${it.accountType}`;
    setBusyKey(key);
    try {
      const res = await snapFetch(`/snapsa/admin/creator-profiles/${it.userId}/${it.accountType}/${action}`, { method:'POST', body: JSON.stringify(body || {}) });
      const d = await res.json().catch(() => ({}));
      if (!res.ok) showToast?.(d.error || 'Failed', 'error');
      else { showToast?.(okMsg, 'success'); setRejecting(null); setReason(''); load(view); }
    } catch { showToast?.('No connection', 'error'); }
    setBusyKey(null);
  };

  const c = data?.counts || {};
  const tabs = [['pending', `Requests${c.pending ? ` (${c.pending})` : ''}`], ['approved', 'Approved'], ['rejected', 'Rejected']];
  const btn = (bg) => ({ flex:1, padding:'9px 0', borderRadius:9, border:'none', background:bg, color:'white', fontWeight:700, fontSize:12.5, cursor:'pointer' });

  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100%', background:'transparent', position:'relative', zIndex:1 }}>
      <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', borderBottom:`1px solid ${S.border}` }}>
        <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><ArrowLeft size={20} style={{ color:'white' }}/></button>
        <h2 style={{ color:'white', fontWeight:700, flex:1 }}>Creator approvals</h2>
        <button onClick={() => load(view)} style={{ background:'none', border:'none', cursor:'pointer' }}><RefreshCw size={18} style={{ color:S.gray }}/></button>
      </div>
      <div style={{ display:'flex', gap:8, padding:'10px 16px' }}>
        {tabs.map(([id, label]) => (
          <button key={id} onClick={() => setView(id)}
            style={{ flex:1, padding:'9px 0', borderRadius:10, border:'none', cursor:'pointer', fontWeight:700, fontSize:12.5, background: view===id ? S.pink : S.card, color: view===id ? 'white' : S.gray }}>{label}</button>
        ))}
      </div>
      <div style={{ flex:1, overflowY:'auto', padding:'0 16px 24px' }}>
        {!data ? <p style={{ color:S.gray, textAlign:'center', padding:30, fontSize:13 }}>Loading…</p>
        : data.items.length === 0 ? <p style={{ color:S.gray, textAlign:'center', padding:30, fontSize:13 }}>Nothing here</p>
        : data.items.map(it => {
            const key = `${it.userId}:${it.accountType}`;
            const busy = busyKey === key;
            return (
              <div key={key} style={{ background:S.card, border:`1px solid ${S.border}`, borderRadius:14, padding:14, marginBottom:10 }}>
                <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                  <div style={{ width:44, height:44, borderRadius:'50%', overflow:'hidden', flexShrink:0, background:`linear-gradient(135deg,${S.pink},#7c3aed)` }}>
                    {it.avatarUrl && <img src={it.avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/>}
                  </div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ color:'white', fontWeight:800, fontSize:14.5 }}>{it.artistName}</div>
                    <div style={{ color:S.pink, fontWeight:700, fontSize:12 }}>{it.label}</div>
                  </div>
                </div>
                <div style={{ color:S.gray, fontSize:12, lineHeight:1.6, marginTop:8 }}>
                  {it.username ? `@${it.username}` : 'No username'} · ID {it.userId}<br/>
                  {it.country}{it.genre ? ` · ${it.genre}` : ''}
                  {it.bio ? <><br/>{it.bio}</> : null}
                  {it.requestedAt ? <><br/>Requested {new Date(it.requestedAt).toLocaleString()}</> : null}
                  {it.reviewNote ? <><br/>Note: {it.reviewNote}</> : null}
                </div>
                {rejecting === key ? (
                  <div style={{ marginTop:10 }}>
                    <input value={reason} onChange={e => setReason(e.target.value.slice(0, 200))} placeholder="Reason (optional, shown to the user)"
                      style={{ width:'100%', background:S.dark, border:`1px solid ${S.border}`, borderRadius:9, padding:'10px 12px', color:'white', outline:'none', fontSize:13, boxSizing:'border-box', marginBottom:8 }}/>
                    <div style={{ display:'flex', gap:8 }}>
                      <button disabled={busy} onClick={() => act(it, 'reject', { reason }, 'Rejected')} style={btn('#ef4444')}>Confirm reject</button>
                      <button onClick={() => { setRejecting(null); setReason(''); }} style={btn(S.border)}>Cancel</button>
                    </div>
                  </div>
                ) : (
                  <div style={{ display:'flex', gap:8, marginTop:10 }}>
                    {view !== 'approved' && <button disabled={busy} onClick={() => act(it, 'approve', {}, 'Approved')} style={btn(S.pink)}>Approve</button>}
                    {view !== 'rejected' && <button disabled={busy} onClick={() => setRejecting(key)} style={btn(S.border)}>{view === 'approved' ? 'Revoke' : 'Reject'}</button>}
                  </div>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
};

     
const ACCOUNT_TYPE_OPTIONS = [
  { id:'artist', label:'Artist', icon:Music2 },
  { id:'radio_station', label:'Radio Station', icon:Radio },
  { id:'tv_channel', label:'TV Channel', icon:Tv },
  { id:'podcast', label:'Podcast', icon:Mic },
  { id:'news_channel', label:'News Channel', icon:Newspaper },
];

const ArtistProfileModal = ({ onClose, onCreated, onUpdated, showToast, existingProfile, lockedType }) => {
  const { t } = useLanguage();
  const isEdit = !!existingProfile;
  const [accountType, setAccountType] = useState(existingProfile?.accountType || lockedType || 'artist');
  const [artistName, setArtistName] = useState(existingProfile?.artistName || '');
  const [country, setCountry] = useState(existingProfile?.country || '');
  const [genre, setGenre] = useState(existingProfile?.genre || '');
  const [bio, setBio] = useState(existingProfile?.bio || '');
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreview, setAvatarPreview] = useState(existingProfile?.avatarUrl || null);
  const [subscriptionPriceCoins, setSubscriptionPriceCoins] = useState(existingProfile?.subscriptionPriceCoins ? String(existingProfile.subscriptionPriceCoins) : '');
  const [saving, setSaving] = useState(false);
  const nameLabel = { artist:'Artist name', radio_station:'Station name', tv_channel:'Channel name', podcast:'Podcast name', news_channel:'News channel name' }[accountType] || 'Name';

  const pickAvatar = (file) => {
    if (!file) { setAvatarFile(null); setAvatarPreview(existingProfile?.avatarUrl || null); return; }
    if (file.size > MAX_AVATAR_IMAGE_BYTES) {
      showToast?.(`That photo is too big — please choose one under ${MAX_AVATAR_IMAGE_LABEL}.`, 'error');
      return;
    }
    setAvatarFile(file);
    const reader = new FileReader();
    reader.onload = () => setAvatarPreview(reader.result);
    reader.readAsDataURL(file);
  };

  const submit = async () => {
    if (!artistName.trim()) { showToast?.(`Enter a ${nameLabel.toLowerCase()}`, 'error'); return; }
    if (!country.trim()) { showToast?.('Enter your country', 'error'); return; }
    setSaving(true);
    try {
      const body = { accountType, artistName: artistName.trim(), country: country.trim(), bio: bio.trim() };     
      if (accountType === 'artist') body.genre = genre.trim();
      if (accountType === 'tv_channel') body.subscriptionPriceCoins = Number(subscriptionPriceCoins) || 0;
      if (avatarFile && avatarPreview) body.avatarBase64 = avatarPreview;
      const res = await snapFetch('/snapsa/music/artist-profile', { method:'POST', body: JSON.stringify(body) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || `Could not ${isEdit ? 'update' : 'create'} profile`);
            if (!data?.artistProfile?.artistName) {
        throw new Error("That didn't save properly — please try again.");
      }
      if (data.status === 'pending') showToast?.('⏳ Sent to the admin for approval — we will notify you.', 'success');
      else showToast?.(isEdit ? '🎤 Profile updated!' : '🎤 Profile created!', 'success');

      if (isEdit) onUpdated?.(data.artistProfile);
      else onCreated?.(data.artistProfile);
    } catch (err) {
      showToast?.(err.message || 'Something went wrong', 'error');
    }
    setSaving(false);
  };

  const canSubmit = artistName.trim() && country.trim() && !saving;

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.85)', zIndex:70, display:'flex', alignItems:'flex-end' }}
      onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
        onClick={e=>e.stopPropagation()}
        style={{ width:'100%', background:S.dark, borderTop:`1px solid ${S.border}`, borderRadius:'20px 20px 0 0', padding:20, paddingBottom:'calc(20px + env(safe-area-inset-bottom,0px))', maxHeight:'88vh', overflowY:'auto' }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:6 }}>
          <h2 style={{ color:'white', fontWeight:800, fontSize:17 }}>{isEdit ? 'Edit Creator Profile' : 'Create Your Creator Profile'}</h2>
          <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={20} style={{ color:S.gray }}/></button>
        </div>
        <p style={{ color:S.gray, fontSize:12.5, lineHeight:1.5, marginBottom:16 }}>
          This is a separate identity from your @username — it's what people see as the creator on anything you publish.
        </p>

        {!isEdit && !lockedType && (
          <div style={{ marginBottom:16 }}>
            <label style={{ display:'block', color:S.gray, fontSize:12, fontWeight:600, marginBottom:8 }}>Account type</label>
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8 }}>
              {ACCOUNT_TYPE_OPTIONS.map(opt => {
                const Icon = opt.icon;
                const active = accountType === opt.id;
                return (
                  <button key={opt.id} type="button" onClick={()=>setAccountType(opt.id)}
                    style={{ display:'flex', alignItems:'center', gap:8, padding:'12px 10px', borderRadius:12,
                      background: active ? `${S.pink}18` : S.card, border:`1.5px solid ${active?S.pink:S.border}`, cursor:'pointer' }}>
                    <Icon size={16} style={{ color: active?S.pink:S.gray }}/>
                    <span style={{ color: active?'white':S.gray, fontSize:12.5, fontWeight:700 }}>{opt.label}</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        <label style={{ display:'flex', alignItems:'center', gap:12, marginBottom:16, cursor:'pointer' }}>
          <div style={{ width:56, height:56, borderRadius:'50%', overflow:'hidden', flexShrink:0, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
            {avatarPreview ? <img src={avatarPreview} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Music2 size={22} style={{ color:'white' }}/>}
          </div>
          <span style={{ color:S.pink, fontSize:13, fontWeight:600 }}>{avatarFile ? 'Change photo' : (isEdit ? 'Change photo' : 'Add photo (optional)')}</span>
          <input type="file" accept="image/*" style={{ display:'none' }} onChange={e=>pickAvatar(e.target.files?.[0]||null)}/>
        </label>

        <input value={artistName} onChange={e=>setArtistName(e.target.value.slice(0,60))} placeholder={nameLabel}
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}/>
        <input value={country} onChange={e=>setCountry(e.target.value.slice(0,60))} placeholder="Country"
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}/>
        <input hidden={accountType !== 'artist'} value={genre} onChange={e=>setGenre(e.target.value.slice(0,60))} placeholder="Genre"
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}/>
        <textarea value={bio} onChange={e=>setBio(e.target.value.slice(0,300))} placeholder="Short bio (optional)" rows={3}
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:accountType==='tv_channel'?10:16, boxSizing:'border-box', resize:'vertical', fontFamily:'inherit' }}/>

        {accountType === 'tv_channel' && (
          <div style={{ marginBottom:16 }}>
            <label style={{ display:'block', color:S.gray, fontSize:12, fontWeight:600, marginBottom:6 }}>Monthly subscription price (coins)</label>
            <input value={subscriptionPriceCoins} onChange={e=>setSubscriptionPriceCoins(e.target.value.replace(/[^0-9]/g,''))} inputMode="numeric" placeholder="e.g. 50"
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, boxSizing:'border-box' }}/>
            <p style={{ color:S.gray, fontSize:11, marginTop:6, lineHeight:1.5 }}>Viewers pay this once a month to watch anything on your channel. You can change it any time.</p>
          </div>
        )}

        <button onClick={submit} disabled={!canSubmit}
          style={{ width:'100%', background: canSubmit?S.pink:S.border, border:'none', borderRadius:999, padding:'13px', color:'white', fontWeight:700, fontSize:14, cursor:canSubmit?'pointer':'not-allowed', opacity:canSubmit?1:.6 }}>
          {saving ? t('common.processing') : (isEdit ? t('common.save') : t('common.create'))}
        </button>
      </motion.div>
    </motion.div>
  );
};

// ─── Streams tab — an artist's own dashboard: per-track streams, purchases,

const MusicStreamsTab = ({ showToast }) => {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [deletingId, setDeletingId] = useState(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);

  useEffect(() => {
    snapFetch('/snapsa/music/artist/mine/stats')
      .then(r => r.ok ? r.json() : null)
      .then(d => setStats(d))
      .catch(() => showToast?.('Could not load streams', 'error'))
      .finally(() => setLoading(false));
  }, []);

  const handleDelete = async (track) => {
    setDeletingId(track.id);
    try {
      const res = await snapFetch(`/snapsa/music/tracks/${track.id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error();
      setStats(prev => prev ? { ...prev, tracks: prev.tracks.filter(t => t.id !== track.id) } : prev);
      showToast?.(`🗑️ "${track.title}" deleted`, 'success');
    } catch {
      showToast?.('Could not delete track', 'error');
    } finally {
      setDeletingId(null);
      setConfirmDeleteId(null);
    }
  };

  if (loading) {
    return (
      <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', padding:40 }}>
        <div style={{ width:32, height:32, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>
      </div>
    );
  }
  if (!stats || stats.tracks.length === 0) {
    return (
      <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, padding:32 }}>
        <Music2 size={40} style={{ color:S.gray, opacity:0.5 }}/>
        <p style={{ color:S.gray, fontSize:13, textAlign:'center' }}>Upload a track to start tracking streams</p>
      </div>
    );
  }
  return (
    <div style={{ padding:'0 16px 16px' }}>
      <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:8, marginBottom:16 }}>
        {[
          ['Streams', fmt(stats.totals.streams)],
          ['Purchases', fmt(stats.totals.purchases)],
          ['Revenue', `$${(stats.totals.revenueCents/100).toFixed(2)}`],
        ].map(([label, val]) => (
          <div key={label} style={{ background:S.card, border:`1px solid ${S.border}`, borderRadius:12, padding:'12px 10px', textAlign:'center' }}>
            <p style={{ color:'white', fontWeight:800, fontSize:16, margin:0 }}>{val}</p>
            <p style={{ color:S.gray, fontSize:10.5, marginTop:2 }}>{label}</p>
          </div>
        ))}
      </div>
      {stats.tracks.map(t => (
        <div key={t.id} style={{ display:'flex', alignItems:'center', gap:12, padding:'10px 0', borderBottom:`1px solid ${S.border}` }}>
          <div style={{ width:40, height:40, borderRadius:8, overflow:'hidden', flexShrink:0, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
            {t.coverUrl ? <img src={t.coverUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Music2 size={16} style={{ color:'white' }}/>}
          </div>
          <div style={{ flex:1, minWidth:0 }}>
            <p style={{ color:'white', fontWeight:700, fontSize:13, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{t.title}</p>
            <p style={{ color:S.gray, fontSize:11 }}>{fmt(t.streams)} streams · {fmt(t.purchases)} bought · ${(t.revenueCents/100).toFixed(2)}</p>
          </div>
          {confirmDeleteId === t.id ? (
            <div style={{ display:'flex', gap:6, flexShrink:0 }}>
              <button onClick={()=>handleDelete(t)} disabled={deletingId===t.id}
                style={{ background:'#dc2626', border:'none', borderRadius:8, padding:'6px 10px', color:'white', fontSize:11, fontWeight:700, cursor:'pointer' }}>
                {deletingId===t.id ? '…' : 'Confirm'}
              </button>
              <button onClick={()=>setConfirmDeleteId(null)}
                style={{ background:S.card, border:`1px solid ${S.border}`, borderRadius:8, padding:'6px 10px', color:S.gray, fontSize:11, fontWeight:700, cursor:'pointer' }}>
                Cancel
              </button>
            </div>
          ) : (
            <button onClick={()=>setConfirmDeleteId(t.id)} title="Delete track"
              style={{ flexShrink:0, background:'none', border:'none', cursor:'pointer', padding:6 }}>
              <Trash2 size={16} style={{ color:S.gray }}/>
            </button>
          )}
        </div>
      ))}
    </div>
  );
};

const TrackVideoPlayer = ({ url, title, artist, onClose, brandBadge = false }) => {
  const videoRef = useRef(null);
  const [playing, setPlaying] = useState(true);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);

  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;
    const onTime = () => setCurrentTime(v.currentTime);
    const onMeta = () => setDuration(v.duration || 0);
    const onEnd = () => setPlaying(false);
    v.addEventListener('timeupdate', onTime);
    v.addEventListener('loadedmetadata', onMeta);
    v.addEventListener('ended', onEnd);
    return () => {
      v.removeEventListener('timeupdate', onTime);
      v.removeEventListener('loadedmetadata', onMeta);
      v.removeEventListener('ended', onEnd);
    };
  }, []);

  const togglePlay = () => {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) { v.play().catch(()=>{}); setPlaying(true); } else { v.pause(); setPlaying(false); }
  };

  const seek = (e) => {
    const v = videoRef.current;
    if (!v || !duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
    v.currentTime = pct * duration;
    setCurrentTime(v.currentTime);
  };

  const fmtTime = (s) => {
    if (!isFinite(s) || s < 0) return '0:00';
    const m = Math.floor(s / 60);
    const sec = Math.floor(s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  };

  const pct = duration ? (currentTime / duration) * 100 : 0;

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, zIndex:200, background:'#000', display:'flex', flexDirection:'column' }}>
      <div style={{ position:'absolute', top:0, left:0, right:0, zIndex:2, display:'flex', alignItems:'center', gap:12, padding:'48px 16px 24px', background:'linear-gradient(180deg, rgba(0,0,0,0.85), transparent)' }}>
        <button onClick={onClose}
          style={{ flexShrink:0, background:'rgba(255,255,255,0.12)', border:'none', borderRadius:'50%', width:36, height:36, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer' }}>
          <X size={18} style={{ color:'white' }}/>
        </button>
        <div style={{ minWidth:0 }}>
          <p style={{ color:'white', fontWeight:700, fontSize:14, margin:0, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{title}</p>
          {artist && <p style={{ color:'rgba(255,255,255,0.65)', fontSize:11.5, margin:0 }}>{artist}</p>}
        </div>
      </div>

      <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', position:'relative' }} onClick={togglePlay}>
        <video ref={videoRef} src={url} autoPlay playsInline style={{ maxWidth:'100%', maxHeight:'100%' }}/>
        {!playing && (
          <div style={{ position:'absolute', width:64, height:64, borderRadius:'50%', background:'rgba(0,0,0,0.5)', display:'flex', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
            <Play size={26} fill="white" style={{ color:'white', marginLeft:3 }}/>
          </div>
        )}
        {brandBadge && (
          <img src={SNAPSA_BADGE_DATA_URI} alt="Snapsa Music" style={{ position:'absolute', bottom:16, right:16, width:44, height:44, opacity:0.92, pointerEvents:'none', filter:'drop-shadow(0 2px 6px rgba(0,0,0,0.6))' }}/>
        )}
      </div>

      <div style={{ padding:'8px 16px 28px', background:'linear-gradient(0deg, rgba(0,0,0,0.9), transparent)' }}>
        <div onClick={seek} style={{ height:4, borderRadius:2, background:'rgba(255,255,255,0.25)', position:'relative', cursor:'pointer', marginBottom:10 }}>
          <div style={{ position:'absolute', left:0, top:0, bottom:0, width:`${pct}%`, background:S.pink, borderRadius:2 }}/>
          <div style={{ position:'absolute', left:`${pct}%`, top:'50%', transform:'translate(-50%,-50%)', width:12, height:12, borderRadius:'50%', background:S.pink, boxShadow:'0 0 0 3px rgba(255,32,85,0.25)' }}/>
        </div>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
          <span style={{ color:'rgba(255,255,255,0.7)', fontSize:11, minWidth:36 }}>{fmtTime(currentTime)}</span>
          <button onClick={togglePlay}
            style={{ background:S.pink, border:'none', borderRadius:'50%', width:46, height:46, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer' }}>
            {playing ? <Pause size={18} fill="white" style={{ color:'white' }}/> : <Play size={18} fill="white" style={{ color:'white', marginLeft:2 }}/>}
          </button>
          <span style={{ color:'rgba(255,255,255,0.7)', fontSize:11, minWidth:36, textAlign:'right' }}>{fmtTime(duration)}</span>
        </div>
      </div>
    </motion.div>
  );
};

const TrackAudioPlayer = ({ track, audio, onClose, onDeleted, showToast }) => {
  const [playing, setPlaying] = useState(!audio.paused);
  const [currentTime, setCurrentTime] = useState(audio.currentTime || 0);
  const [duration, setDuration] = useState(audio.duration || 0);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const onTime = () => setCurrentTime(audio.currentTime);
    const onMeta = () => setDuration(audio.duration || 0);
    const onPlay = () => setPlaying(true);
    const onPause = () => setPlaying(false);
    audio.addEventListener('timeupdate', onTime);
    audio.addEventListener('loadedmetadata', onMeta);
    audio.addEventListener('play', onPlay);
    audio.addEventListener('pause', onPause);
    return () => {
      audio.removeEventListener('timeupdate', onTime);
      audio.removeEventListener('loadedmetadata', onMeta);
      audio.removeEventListener('play', onPlay);
      audio.removeEventListener('pause', onPause);
    };
  }, [audio]);

  const togglePlay = () => {
    if (audio.paused) audio.play().catch(()=>{}); else audio.pause();
  };

  const skip = (seconds) => {
    audio.currentTime = Math.min(Math.max(0, audio.currentTime + seconds), duration || Infinity);
  };

  const seek = (e) => {
    if (!duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
    audio.currentTime = pct * duration;
    setCurrentTime(audio.currentTime);
  };

  const fmtTime = (s) => {
    if (!isFinite(s) || s < 0) return '0:00';
    const m = Math.floor(s / 60);
    const sec = Math.floor(s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  };

  const handleDelete = async () => {
    setDeleting(true);
    try {
      const res = await snapFetch(`/snapsa/music/tracks/${track.id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error();
      audio.pause();
      showToast?.(`🗑️ "${track.title}" deleted`, 'success');
      onDeleted?.(track.id);
      onClose();
    } catch {
      showToast?.('Could not delete track', 'error');
      setDeleting(false);
      setConfirmingDelete(false);
    }
  };

  const pct = duration ? (currentTime / duration) * 100 : 0;

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, zIndex:200, background:'#000', display:'flex', flexDirection:'column' }}>
      <div style={{ padding:'48px 16px 12px' }}>
        <button onClick={onClose}
          style={{ background:'rgba(255,255,255,0.12)', border:'none', borderRadius:'50%', width:36, height:36, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer' }}>
          <X size={18} style={{ color:'white' }}/>
        </button>
      </div>

      <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', padding:'0 32px', position:'relative' }}>
        <div style={{ position:'relative', width:'100%', maxWidth:340 }}>
          {track.coverUrl
            ? <img src={track.coverUrl} alt="" style={{ width:'100%', aspectRatio:'1/1', borderRadius:16, objectFit:'cover', boxShadow:'0 20px 60px rgba(0,0,0,0.5)', display:'block' }}/>
            : <img src={SNAPSA_MUSIC_LOGO_URL} alt="Snapsa Music" style={{ width:'100%', aspectRatio:'1/1', borderRadius:16, objectFit:'cover', boxShadow:'0 20px 60px rgba(0,0,0,0.5)', display:'block' }}/>}
          {/* Persistent brand badge — sits on top of the art itself, corner-anchored like Spotify's logo watermark, on every track regardless of whether it has its own cover art */}
          <img src={SNAPSA_BADGE_DATA_URI} alt="Snapsa Music" style={{ position:'absolute', bottom:10, right:10, width:40, height:40, filter:'drop-shadow(0 2px 6px rgba(0,0,0,0.6))', pointerEvents:'none' }}/>
        </div>
      </div>

      <div style={{ padding:'0 24px 8px' }}>
        <p style={{ color:'#22d3ee', fontWeight:800, fontSize:12, letterSpacing:1, margin:'0 0 4px', textTransform:'uppercase' }}>Snapsa Music</p>
        <p style={{ color:'white', fontWeight:800, fontSize:20, margin:0 }}>{track.title}</p>
        <p style={{ color:S.gray, fontSize:14, margin:'2px 0 0' }}>{track.artist}</p>
      </div>

      <div style={{ padding:'16px 24px 36px' }}>
        <div onClick={seek} style={{ height:4, borderRadius:2, background:'rgba(255,255,255,0.2)', position:'relative', cursor:'pointer', marginBottom:8 }}>
          <div style={{ position:'absolute', left:0, top:0, bottom:0, width:`${pct}%`, background:S.pink, borderRadius:2 }}/>
          <div style={{ position:'absolute', left:`${pct}%`, top:'50%', transform:'translate(-50%,-50%)', width:14, height:14, borderRadius:'50%', background:S.pink, boxShadow:'0 0 0 4px rgba(255,32,85,0.25)' }}/>
        </div>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:20 }}>
          <span style={{ color:S.gray, fontSize:11.5 }}>{fmtTime(currentTime)}</span>
          <span style={{ color:S.gray, fontSize:11.5 }}>{fmtTime(duration)}</span>
        </div>

        <div style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:36 }}>
          <button onClick={()=>skip(-10)} style={{ background:'none', border:'none', cursor:'pointer', padding:8 }}>
            <SkipBack size={26} fill="white" style={{ color:'white' }}/>
          </button>
          <button onClick={togglePlay}
            style={{ background:S.pink, border:'none', borderRadius:'50%', width:64, height:64, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer' }}>
            {playing ? <Pause size={26} fill="white" style={{ color:'white' }}/> : <Play size={26} fill="white" style={{ color:'white', marginLeft:3 }}/>}
          </button>
          <button onClick={()=>skip(10)} style={{ background:'none', border:'none', cursor:'pointer', padding:8 }}>
            <SkipForward size={26} fill="white" style={{ color:'white' }}/>
          </button>
        </div>

        {track.isOwnTrack && (
          <div style={{ display:'flex', justifyContent:'center', marginTop:22 }}>
            {confirmingDelete ? (
              <div style={{ display:'flex', gap:8 }}>
                <button onClick={handleDelete} disabled={deleting}
                  style={{ background:'#dc2626', border:'none', borderRadius:999, padding:'8px 16px', color:'white', fontSize:12, fontWeight:700, cursor:'pointer' }}>
                  {deleting ? 'Deleting…' : 'Confirm delete'}
                </button>
                <button onClick={()=>setConfirmingDelete(false)} disabled={deleting}
                  style={{ background:'rgba(255,255,255,0.1)', border:'none', borderRadius:999, padding:'8px 16px', color:S.gray, fontSize:12, fontWeight:700, cursor:'pointer' }}>
                  Cancel
                </button>
              </div>
                        ) : null}
          </div>
        )}
      </div>
    </motion.div>
  );
};

const TransferToWalletModal = ({ coins, onClose, onDone, showToast }) => {
  const [amount, setAmount] = useState(String(coins || ''));
  const [wallet, setWallet] = useState(undefined); // undefined = loading, null = none
  const [quote, setQuote] = useState(null);
  const [busy, setBusy] = useState(false);
  const reqIdRef = useRef(null);
  const n = parseInt(amount, 10);
  const valid = /^\d+$/.test(amount) && n >= 1 && n <= (coins || 0);

  useEffect(() => {
    snapFetch('/snapsa/wallet/me').then(r => r.ok ? r.json() : null)
      .then(d => setWallet(d?.wallet || null)).catch(() => setWallet(null));
  }, []);

  useEffect(() => {
    setQuote(null);
    if (!valid || !wallet) return;
    const t = setTimeout(() => {
      snapFetch(`/snapsa/wallet/transfer-from-coins/quote?coins=${n}`)
        .then(r => r.json()).then(d => setQuote(d)).catch(() => {});
    }, 250);
    return () => clearTimeout(t);
  }, [n, valid, wallet]);

  const confirm = async () => {
    if (!valid || busy) return;
    setBusy(true);
    if (!reqIdRef.current) reqIdRef.current = newRequestId(); // reused on retry, so it can never apply twice
    try {
      const res = await snapFetch('/snapsa/wallet/transfer-from-coins', {
        method: 'POST', body: JSON.stringify({ coins: n, requestId: reqIdRef.current }),
      });
      const d = await res.json().catch(() => ({}));
      if (!res.ok) { showToast?.(d.error || 'Transfer failed', 'error'); setBusy(false); return; }
      showToast?.(`✅ ${fmt(n)} coins moved — ${d.currency} ${Number(d.amount).toFixed(2)} added to your Snapsa Wallet`, 'success');
      onDone?.(d.newBalance);
      onClose();
    } catch {
      showToast?.('Transfer failed — check your connection and try again', 'error');
      setBusy(false);
    }
  };

  return createPortal(
    <div style={{ position:'fixed', inset:0, zIndex:9000, display:'flex', alignItems:'flex-end', justifyContent:'center', background:'rgba(0,0,0,.7)' }} onClick={onClose}>
      <div onClick={e => e.stopPropagation()}
        style={{ width:'100%', maxWidth:420, background:S.card, borderTopLeftRadius:24, borderTopRightRadius:24, padding:'24px 24px calc(28px + env(safe-area-inset-bottom,0px))' }}>
        <p style={{ color:'white', fontWeight:800, fontSize:18, margin:'0 0 4px' }}>Transfer to Snapsa Wallet</p>
        <p style={{ color:S.gray, fontSize:13, margin:'0 0 16px' }}>Move Snapsa Coins into your Snapsa Wallet balance.</p>

        {wallet === undefined && <p style={{ color:S.gray, textAlign:'center', padding:16 }}>Loading…</p>}
        {wallet === null && (
          <p style={{ color:'white', fontSize:14, background:`${S.pink}22`, border:`1px solid ${S.pink}55`, borderRadius:12, padding:14 }}>
            You need a Snapsa Wallet first. Apply for one in Snapsa Wallet, then come back to transfer.
          </p>
        )}
        {wallet && (
          <>
            <label style={{ color:S.gray, fontSize:12 }}>Coins to transfer (you have {fmt(coins || 0)})</label>
            <input value={amount} onChange={e => setAmount(e.target.value.replace(/\D/g, ''))} inputMode="numeric"
              style={{ width:'100%', margin:'6px 0 10px', padding:'12px 14px', borderRadius:12, background:S.dark, border:`1px solid ${S.border}`, color:'white', fontSize:18, fontWeight:700, boxSizing:'border-box' }}/>
            <p style={{ color:'white', fontSize:14, minHeight:20, margin:'0 0 16px' }}>
              {valid ? (quote?.amount != null ? `You will receive ${quote.currency} ${Number(quote.amount).toFixed(2)}` : '…') : 'Enter a whole number of coins'}
            </p>
            <button onClick={confirm} disabled={!valid || busy}
              style={{ width:'100%', padding:'13px 0', borderRadius:12, background: valid ? S.pink : S.border, color:'white', fontWeight:700, fontSize:14, border:'none', cursor: valid ? 'pointer' : 'default', marginBottom:10 }}>
              {busy ? 'Transferring…' : 'Transfer'}
            </button>
          </>
        )}
        <button onClick={onClose} style={{ width:'100%', padding:'13px 0', borderRadius:12, background:S.border, color:S.gray, fontWeight:600, fontSize:14, border:'none', cursor:'pointer' }}>Close</button>
      </div>
    </div>,
    document.body
  );
};
  

// ── Following / Followers list ─────────────────────────────────────────────
const FollowListModal = ({ type, onClose, onChange }) => {
    const [users, setUsers] = useState(null);
  const [busyId, setBusyId] = useState(null);
  const [requests, setRequests] = useState([]);
  useEffect(() => {
    if (type !== 'followers') return;
    snapFetch('/snapsa/follow-requests').then(r => r.ok ? r.json() : null)
      .then(d => setRequests(d?.requests || [])).catch(() => {});
  }, [type]);
  const answerRequest = async (u, approve) => {
    try {
      const res = await snapFetch(`/snapsa/follow-requests/${u.userId}/${approve ? 'approve' : 'deny'}`, { method: 'POST' });
      if (!res.ok) throw new Error();
      setRequests(prev => prev.filter(x => x.userId !== u.userId));
      if (approve) { setUsers(prev => [u, ...(prev || [])]); onChange?.(1); }
    } catch {}
  };
  
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const res = await snapFetch(`/snapsa/users/me/follows?type=${type}`);
        const d = await res.json();
        if (alive) setUsers(d.users || []);
      } catch { if (alive) setUsers([]); }
    })();
    return () => { alive = false; };
  }, [type]);

  const act = async (u) => {
    setBusyId(u.userId);
    try {
      const url = type === 'followers'
        ? `/snapsa/users/me/followers/${u.userId}`
        : `/snapsa/users/${u.userId}/follow`;
      const res = await snapFetch(url, { method: 'DELETE' });
      if (!res.ok) throw new Error();
      setUsers(prev => prev.filter(x => x.userId !== u.userId));
      onChange?.(-1);
    } catch {}
    setBusyId(null);
  };

  return createPortal(
    <div style={{ position:'fixed', inset:0, zIndex:300, background:'#000', display:'flex', flexDirection:'column' }}>
      <div style={{ display:'flex', alignItems:'center', gap:12, padding:'48px 16px 12px', borderBottom:`1px solid ${S.border}` }}>
        <button onClick={onClose} style={{ background:'rgba(255,255,255,0.12)', border:'none', borderRadius:'50%', width:36, height:36, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer' }}>
          <X size={18} style={{ color:'white' }}/>
        </button>
        <p style={{ color:'white', fontWeight:800, fontSize:17, margin:0 }}>{type === 'followers' ? 'Followers' : 'Following'}</p>
      </div>
      <div style={{ flex:1, overflowY:'auto', padding:'8px 16px' }}>
        {requests.length > 0 && (           <div style={{ marginBottom:12, paddingBottom:8, borderBottom:`1px solid ${S.border}` }}>             <p style={{ color:S.gray, fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:1, margin:'8px 0' }}>Follow requests</p>             {requests.map(u => (               <div key={u.userId} style={{ display:'flex', alignItems:'center', gap:12, padding:'8px 0' }}>                 <div style={{ width:42, height:42, borderRadius:'50%', overflow:'hidden', background:'rgba(255,255,255,0.1)', display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontWeight:800, flexShrink:0 }}>                   {u.avatarUrl ? <img src={u.avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : (u.displayName || u.username || 'U')[0].toUpperCase()}                 </div>                 <span style={{ flex:1, minWidth:0, color:'white', fontWeight:700, fontSize:14, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{u.displayName || u.username || 'User'}</span>                 <button onClick={() => answerRequest(u, true)} style={{ padding:'7px 14px', borderRadius:999, border:'none', background:S.pink, color:'white', fontSize:12.5, fontWeight:700, cursor:'pointer' }}>Approve</button>                 <button onClick={() => answerRequest(u, false)} style={{ padding:'7px 14px', borderRadius:999, border:`1px solid ${S.border}`, background:'transparent', color:S.gray, fontSize:12.5, fontWeight:700, cursor:'pointer' }}>Deny</button>               </div>             ))}           </div>         )}         {users === null && <p style={{ color:S.gray, textAlign:'center', marginTop:40 }}>Loading…</p>}
        {users && users.length === 0 && (
          <p style={{ color:S.gray, textAlign:'center', marginTop:40 }}>
            {type === 'followers' ? 'No followers yet' : 'You are not following anyone yet'}
          </p>
        )}
        {users && users.map(u => (
          <div key={u.userId} style={{ display:'flex', alignItems:'center', gap:12, padding:'10px 0' }}>
            <div style={{ width:46, height:46, borderRadius:'50%', overflow:'hidden', background:'rgba(255,255,255,0.1)', display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontWeight:800, flexShrink:0 }}>
              {u.avatarUrl ? <img src={u.avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : (u.displayName || u.username || 'U')[0].toUpperCase()}
            </div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:'flex', alignItems:'center', gap:4 }}>
                <span style={{ color:'white', fontWeight:700, fontSize:14, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{u.displayName || u.username || 'User'}</span>
                <AuthorBadges snapsaTier={u.snapsaTier} crew={u.crew} />
              </div>
            </div>
            <button onClick={() => act(u)} disabled={busyId === u.userId}
              style={{ padding:'7px 16px', borderRadius:999, border:`1px solid ${S.border}`, background:'rgba(255,255,255,0.08)', color:'white', fontSize:12.5, fontWeight:700, cursor:'pointer' }}>
              {busyId === u.userId ? '…' : (type === 'followers' ? 'Remove' : 'Unfollow')}
            </button>
          </div>
        ))}
      </div>
    </div>,
    document.body
  );
};

const FollowStat = ({ label, value, type }) => {
  const [open, setOpen] = useState(false);
  const [delta, setDelta] = useState(0);
  const shown = typeof value === 'string' && /^\d+$/.test(value) ? String(Math.max(0, Number(value) + delta)) : value;
  return (
    <>
      <div onClick={() => setOpen(true)} style={{ flex:1, textAlign:'center', cursor:'pointer' }}>
        <p style={{ fontWeight:900, fontSize:17, color:'white', margin:0 }}>{shown}</p>
        <p style={{ fontSize:11, color:S.gray, margin:0 }}>{label}</p>
      </div>
      {open && <FollowListModal type={type} onClose={() => setOpen(false)} onChange={d => setDelta(x => x + d)} />}
    </>
  );
};

// ── Snapsa Music player: chat-bubble style (round pink play button, thin
// scrub bar with round handle, time readout), enlarged to full screen.
// Tracks with a music video show the video where the cover art would be.
const SnapsaMusicPlayer = ({ track, audio = null, videoUrl = null, onClose, onDeleted, showToast, label = 'SNAPSA MUSIC', audioOnly = false }) => {
  const videoRef = useRef(null);
  const media = () => audio || videoRef.current;
  const [playing, setPlaying] = useState(audio ? !audio.paused : !!videoUrl);
  const [currentTime, setCurrentTime] = useState(audio?.currentTime || 0);
  const [duration, setDuration] = useState(audio?.duration || 0);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const m = media();
    if (!m) return;
    const onTime = () => setCurrentTime(m.currentTime);
    const onMeta = () => setDuration(m.duration || 0);
    const onPlay = () => setPlaying(true);
    const onPause = () => setPlaying(false);
    m.addEventListener('timeupdate', onTime);
    m.addEventListener('loadedmetadata', onMeta);
    m.addEventListener('durationchange', onMeta);
    m.addEventListener('play', onPlay);
    m.addEventListener('pause', onPause);
    onMeta();
    return () => {
      m.removeEventListener('timeupdate', onTime);
      m.removeEventListener('loadedmetadata', onMeta);
      m.removeEventListener('durationchange', onMeta);
      m.removeEventListener('play', onPlay);
      m.removeEventListener('pause', onPause);
    };
  }, [audio, videoUrl]);

  const togglePlay = () => { const m = media(); if (!m) return; if (m.paused) m.play().catch(()=>{}); else m.pause(); };
  const skip = (s) => { const m = media(); if (!m) return; m.currentTime = Math.min(Math.max(0, m.currentTime + s), duration || Infinity); };
  const seek = (e) => {
    const m = media();
    if (!m || !duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
    m.currentTime = pct * duration;
    setCurrentTime(m.currentTime);
  };
  const fmtTime = (s) => {
    if (!isFinite(s) || s < 0) return '0:00';
    return `${Math.floor(s / 60)}:${Math.floor(s % 60).toString().padStart(2, '0')}`;
  };
  const handleClose = () => { if (!audio) videoRef.current?.pause(); onClose(); };
  const handleDelete = async () => {
    setDeleting(true);
    try {
      const res = await snapFetch(`/snapsa/music/tracks/${track.id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error();
      media()?.pause();
      showToast?.(`🗑️ "${track.title}" deleted`, 'success');
      onDeleted?.(track.id);
      onClose();
    } catch {
      showToast?.('Could not delete track', 'error');
      setDeleting(false);
      setConfirmingDelete(false);
    }
  };

  const pct = duration ? Math.min(100, (currentTime / duration) * 100) : 0;
  const mono = "'Courier New', ui-monospace, monospace";
  const showVideo = !!videoUrl && !audioOnly;
  const artStyle = { height:'100%', maxWidth:'100%', aspectRatio:'1/1', borderRadius:26, boxShadow:'0 20px 60px rgba(0,0,0,0.6)', display:'block', objectFit:'cover' };

  return createPortal(
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, zIndex:900, background:'#04080a', display:'flex', flexDirection:'column' }}>
      {/* banner (drop /SnapsaPlayerBanner.png into public to use your own; falls back to the logo) */}
      <div style={{ position:'relative', flexShrink:0, background:'#05020a', paddingTop:'var(--sat, env(safe-area-inset-top, 0px))' }}>
        <img src="/SnapsaPlayerBanner.png" alt="" style={{ width:'100%', display:'block', maxHeight:140, objectFit:'cover' }}
          onError={e => { e.target.onerror = null; e.target.src = '/SnapsaHub.png'; e.target.style.cssText = 'height:52px;width:auto;margin:14px auto;display:block'; }}/>
        <button onClick={handleClose} aria-label="Close"
          style={{ position:'absolute', left:12, top:'calc(var(--sat, env(safe-area-inset-top, 0px)) + 10px)', background:'rgba(0,0,0,0.55)', border:'none', borderRadius:'50%', width:36, height:36, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer' }}>
          <X size={18} style={{ color:'white' }}/>
        </button>
      </div>

      <div style={{ textAlign:'center', padding:'8px 12px 4px', flexShrink:0 }}>
        <span style={{ fontFamily:'Arial Black, Impact, sans-serif', fontWeight:900, fontSize:30, letterSpacing:1, color:'#4ff5ea', WebkitTextStroke:'1.5px #c026d3', textShadow:'0 0 16px rgba(192,38,211,.75)' }}>{label}</span>
      </div>

      <div style={{ flex:1, minHeight:0, display:'flex', alignItems:'center', justifyContent:'center', padding:'8px 14px' }}>
        {videoUrl && (
          <video ref={videoRef} src={videoUrl} autoPlay playsInline controlsList="nodownload" onClick={togglePlay}
            style={showVideo ? { ...artStyle, objectFit:'contain', background:'#000', aspectRatio:'auto', width:'100%' } : { position:'absolute', width:1, height:1, opacity:0 }}/>
        )}
        {!showVideo && <img src={track.coverUrl || SNAPSA_MUSIC_LOGO_URL} alt="" style={artStyle}/>}
      </div>

      <div style={{ padding:'6px 22px 0', flexShrink:0 }}>
        <p style={{ color:'white', fontFamily:mono, fontSize:22, letterSpacing:3, margin:0, textTransform:'uppercase', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{track.title}</p>
        <p style={{ color:'#b48cff', fontFamily:mono, fontSize:15, letterSpacing:2, margin:'4px 0 0', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{track.artist}</p>
      </div>

      <div style={{ padding:'6px 18px 0', flexShrink:0 }}>
        <div onClick={seek} style={{ padding:'10px 0', cursor:'pointer' }}>
          <div style={{ height:10, borderRadius:6, background:'rgba(255,255,255,0.12)', overflow:'hidden' }}>
            <div style={{ width:`${pct}%`, height:'100%', borderRadius:6, background:'linear-gradient(90deg,#ff2d55,#ff9500,#ffd60a)', transition:'width .25s linear' }}/>
          </div>
        </div>
        <div style={{ display:'flex', justifyContent:'space-between' }}>
          <span style={{ color:S.gray, fontSize:11, fontFamily:mono }}>{fmtTime(currentTime)}</span>
          <span style={{ color:S.gray, fontSize:11, fontFamily:mono }}>{fmtTime(duration)}</span>
        </div>
      </div>

      <div style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:34, padding:'6px 0 10px', flexShrink:0 }}>
        <button onClick={()=>skip(-10)} aria-label="Back 10 seconds" style={{ background:'none', border:'none', cursor:'pointer', padding:8 }}>
          <SkipBack size={24} fill="white" style={{ color:'white' }}/>
        </button>
        <button onClick={togglePlay} aria-label={playing ? 'Pause' : 'Play'}
          style={{ background:'#e11d2e', border:'none', borderRadius:'50%', width:78, height:78, display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer', boxShadow:'0 0 28px rgba(225,29,46,.6)' }}>
          {playing ? <Pause size={32} fill="white" style={{ color:'white' }}/> : <Play size={32} fill="white" style={{ color:'white', marginLeft:4 }}/>}
        </button>
        <button onClick={()=>skip(10)} aria-label="Forward 10 seconds" style={{ background:'none', border:'none', cursor:'pointer', padding:8 }}>
          <SkipForward size={24} fill="white" style={{ color:'white' }}/>
        </button>
      </div>

      {track.isOwnTrack && (
        <div style={{ display:'flex', justifyContent:'center', paddingBottom:6, flexShrink:0 }}>
          {confirmingDelete ? (
            <div style={{ display:'flex', gap:8 }}>
              <button onClick={handleDelete} disabled={deleting}
                style={{ background:'#dc2626', border:'none', borderRadius:999, padding:'8px 16px', color:'white', fontSize:12, fontWeight:700, cursor:'pointer' }}>
                {deleting ? 'Deleting…' : 'Confirm delete'}
              </button>
              <button onClick={()=>setConfirmingDelete(false)} disabled={deleting}
                style={{ background:'rgba(255,255,255,0.1)', border:'none', borderRadius:999, padding:'8px 16px', color:S.gray, fontSize:12, fontWeight:700, cursor:'pointer' }}>
                Cancel
              </button>
            </div>
          ) : (
            <button onClick={()=>setConfirmingDelete(true)} style={{ display:'flex', alignItems:'center', gap:6, background:'none', border:'none', cursor:'pointer', padding:6 }}>
              <Trash2 size={16} style={{ color:S.gray }}/>
              <span style={{ color:S.gray, fontSize:12 }}>Delete this track</span>
            </button>
          )}
        </div>
      )}

      {/* bottom nav: ember glow, Music highlighted. Any tab closes the player and goes there. */}
      <BottomNav activeTab="music" emberActive
        onTabChange={(id) => { handleClose(); if (id !== 'music') window.dispatchEvent(new CustomEvent('snapsa:navTab', { detail: id })); }}
        onCreatePress={() => { handleClose(); window.dispatchEvent(new CustomEvent('snapsa:openCreate')); }}/>
    </motion.div>,
    document.body
  );
};

// ─── Music "play with ads": full-screen ad shown before a for-sale track plays in full
const MusicAdGate = ({ minSeconds = 8, onDone, onCancel }) => {
  const startRef = useRef(Date.now());
  const doneRef = useRef(false);
  const finish = () => {
    if (doneRef.current) return;
    doneRef.current = true;
    const wait = Math.max(0, minSeconds * 1000 - (Date.now() - startRef.current) + 400);
    setTimeout(onDone, wait);   // if the ad ended/failed early, hold until the minimum time has passed
  };
  return (
    <div style={{ position:'fixed', inset:0, zIndex:700, background:'#000' }}>
      <SnapsaAdVideo onEnded={finish} style={{ position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover' }}/>
      <div style={{ position:'absolute', inset:0, background:'linear-gradient(180deg, rgba(0,0,0,0.5) 0%, rgba(0,0,0,0) 25%, rgba(0,0,0,0) 70%, rgba(0,0,0,0.8) 100%)', pointerEvents:'none' }}/>
      <div style={{ position:'absolute', top:44, left:16, right:16, display:'flex', alignItems:'center', justifyContent:'space-between' }}>
        <span style={{ background:'rgba(0,0,0,0.6)', color:'white', fontSize:12, fontWeight:700, borderRadius:999, padding:'6px 12px' }}>Ad · your song plays next</span>
        <button onClick={onCancel} style={{ width:38, height:38, borderRadius:'50%', border:'none', background:'rgba(0,0,0,0.6)', color:'white', fontSize:18, cursor:'pointer' }}>✕</button>
      </div>
    </div>
  );
};

const TrackDetailsModal = ({ track, onClose, onPlayFull, onTogglePreview, onBuy, purchasing, onPlayWithAds }) => {

  const addedDate = track.createdAt ? new Date(track.createdAt) : null;
  const addedLabel = addedDate && !isNaN(addedDate.getTime())
    ? addedDate.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })
    : null;

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.85)', zIndex:70, display:'flex', alignItems:'flex-end' }}
      onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
        onClick={e=>e.stopPropagation()}
        style={{ width:'100%', background:S.dark, borderTop:`1px solid ${S.border}`, borderRadius:'20px 20px 0 0', padding:20, paddingBottom:'calc(20px + env(safe-area-inset-bottom,0px))' }}>
        <div style={{ display:'flex', justifyContent:'flex-end' }}>
          <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={20} style={{ color:S.gray }}/></button>
        </div>

        <div style={{ display:'flex', justifyContent:'center', marginBottom:16 }}>
          <div style={{ position:'relative', width:140, height:140 }}>
            {track.coverUrl
              ? <img src={track.coverUrl} alt="" style={{ width:140, height:140, borderRadius:16, objectFit:'cover', display:'block' }}/>
              : <img src={SNAPSA_MUSIC_LOGO_URL} alt="Snapsa Music" style={{ width:140, height:140, borderRadius:16, objectFit:'cover', display:'block' }}/>}
            <img src={SNAPSA_BADGE_DATA_URI} alt="Snapsa Music" style={{ position:'absolute', bottom:6, right:6, width:26, height:26, filter:'drop-shadow(0 1px 4px rgba(0,0,0,0.6))', pointerEvents:'none' }}/>
          </div>
        </div>

        <p style={{ color:'white', fontWeight:800, fontSize:18, textAlign:'center' }}>{track.title}</p>
        <p style={{ color:S.pink, fontSize:14, fontWeight:600, textAlign:'center', marginTop:2 }}>@{track.artistName || 'unknown'}</p>

        <div style={{ display:'flex', justifyContent:'center', gap:16, marginTop:14, flexWrap:'wrap' }}>
          {track.genre && (
            <div style={{ textAlign:'center' }}>
              <p style={{ color:S.gray, fontSize:10.5, textTransform:'uppercase', letterSpacing:0.5 }}>Genre</p>
              <p style={{ color:'white', fontSize:13, fontWeight:600, marginTop:2 }}>{track.genre}</p>
            </div>
          )}
          {addedLabel && (
            <div style={{ textAlign:'center' }}>
              <p style={{ color:S.gray, fontSize:10.5, textTransform:'uppercase', letterSpacing:0.5 }}>Added</p>
              <p style={{ color:'white', fontSize:13, fontWeight:600, marginTop:2 }}>{addedLabel}</p>
            </div>
          )}
          <div style={{ textAlign:'center' }}>
            <p style={{ color:S.gray, fontSize:10.5, textTransform:'uppercase', letterSpacing:0.5 }}>Plays</p>
            <p style={{ color:'white', fontSize:13, fontWeight:600, marginTop:2 }}>{fmt(track.playCount||0)}</p>
          </div>
        </div>

        <div style={{ display:'flex', justifyContent:'center', marginTop:20 }}>
          {track.owned ? (
            <button onClick={()=>{ onPlayFull(track); onClose(); }}
              style={{ display:'flex', alignItems:'center', gap:8, background:S.pink, border:'none', borderRadius:999, padding:'12px 24px', cursor:'pointer' }}>
              <Play size={15} fill="white" style={{ color:'white' }}/>
              <span style={{ color:'white', fontWeight:700, fontSize:14 }}>Play</span>
            </button>
          ) : (
          <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:10 }}>
              {track.adSupported && onPlayWithAds && (
                <button onClick={()=>{ onPlayWithAds(track); onClose(); }}
                  style={{ display:'flex', alignItems:'center', gap:8, background:'transparent', border:`1.5px solid ${S.pink}`, borderRadius:999, padding:'12px 24px', cursor:'pointer' }}>
                  <Play size={14} fill={S.pink} style={{ color:S.pink }}/>
                  <span style={{ color:S.pink, fontWeight:800, fontSize:13 }}>Play free with an ad</span>
                </button>
              )}
            <div style={{ display:'flex', gap:10 }}>
              <button onClick={()=>{ onTogglePreview(track); onClose(); }}
                style={{ display:'flex', alignItems:'center', gap:8, background:S.card, border:`1px solid ${S.border}`, borderRadius:999, padding:'12px 20px', cursor:'pointer' }}>
                <Play size={14} fill="white" style={{ color:'white' }}/>
                <span style={{ color:'white', fontWeight:700, fontSize:13 }}>30s Preview</span>
              </button>
              <button onClick={()=>onBuy(track)} disabled={purchasing}
                style={{ display:'flex', alignItems:'center', gap:8, background:purchasing?S.border:S.pink, border:'none', borderRadius:999, padding:'12px 20px', cursor:purchasing?'default':'pointer' }}>
                <ShoppingBag size={14} style={{ color:'white' }}/>
                <span style={{ color:'white', fontWeight:700, fontSize:13 }}>
                  {purchasing ? 'Processing…' : `$${Number.isFinite(track.priceUsd) ? track.priceUsd.toFixed(2) : '1.00'}`}
                </span>
              </button>
            </div>
          </div>
          )}
        </div>
      </motion.div>
    </motion.div>
  );
};

