const MusicScreen = ({ currentUser, showToast, isActive = true }) => {
  const { t } = useLanguage();
  const [contentSection, setContentSection] = useState('music'); // 'music' | 'radio' | 'tv' | 'news' | 'podcasts'
  const [subTab, setSubTab] = useState('browse'); // 'browse' | 'library' | 'streams'
  const [query, setQuery] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('All');
  const [showSearchInput, setShowSearchInput] = useState(false);
  const [tracks, setTracks] = useState([]);
  const [library, setLibrary] = useState([]);
  const [loading, setLoading] = useState(true);
  const [purchasingId, setPurchasingId] = useState(null);
  const [adGate, setAdGate] = useState(null); // { track, token, minSeconds } while an ad is showing
  const [playingPreviewId, setPlayingPreviewId] = useState(null);
  const [videoPlayerTrack, setVideoPlayerTrack] = useState(null); // { url, title, artist } | null
  const [audioPlayerTrack, setAudioPlayerTrack] = useState(null); // { track, audio } | null
  const [detailsTrack, setDetailsTrack] = useState(null); // track | null — thumbnail-tap info sheet
  const [showUpload, setShowUpload] = useState(false);
  const [artistProfile, setArtistProfile] = useState(undefined); // undefined = loading, null = none yet, object = has one
  const [showArtistProfileModal, setShowArtistProfileModal] = useState(false);
  const audioRef = useRef(null);
  const debounceRef = useRef(null);

  const isGuest = currentUser?.isGuest === true;

  const loadBrowse = (q = '', genreFilter = '') => {
    setLoading(true);
    const params = new URLSearchParams();
    if (q) params.set('search', q);
    if (genreFilter && genreFilter !== 'All') params.set('genre', genreFilter);
    const qs = params.toString();
    snapFetch(`/snapsa/music/tracks${qs ? `?${qs}` : ''}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => setTracks(d?.tracks || []))
      .catch(() => setTracks([]))
      .finally(() => setLoading(false));
  };

  const loadLibrary = () => {
    if (isGuest) { setLibrary([]); setLoading(false); return; }
    setLoading(true);
    snapFetch('/snapsa/music/library')
      .then(r => r.ok ? r.json() : null)
      .then(d => setLibrary((d?.tracks || []).map(t => ({ ...t, owned: true }))))
      .catch(() => setLibrary([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    if (isGuest) { setArtistProfile(null); return; }
    snapFetch('/snapsa/music/artist-profile/mine?type=artist')
      .then(r => r.ok ? r.json() : null)
      .then(d => setArtistProfile(d?.artistProfile || null))
      .catch(() => setArtistProfile(null));
  }, [isGuest]);

  useEffect(() => {
    if (subTab === 'browse') loadBrowse(query, selectedGenre);
    else if (subTab === 'library') loadLibrary();
    else setLoading(false); // 'streams' loads its own data
  }, [subTab]);

  useEffect(() => {
    return () => { audioRef.current?.pause(); };
  }, []);

  useEffect(() => {
    if (!isActive) {
      audioRef.current?.pause();
      setPlayingPreviewId(null);
    }
  }, [isActive]);

  const handleSearchChange = (val) => {
    setQuery(val);
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => loadBrowse(val, selectedGenre), 350);
  };

  const handleGenreSelect = (g) => {
    setSelectedGenre(g);
    loadBrowse(query, g);
  };

  // Populates the browser/OS native "now playing" widget (Media Session
  // API) so it shows the real track title/artist/artwork instead of a raw
  // filename, and wires its transport buttons to the actual <audio>
  // element currently playing.
  const applyMediaSession = (audio, track) => {
    if (!('mediaSession' in navigator)) return;
    navigator.mediaSession.metadata = new MediaMetadata({
      title: track.title || 'Untitled track',
      artist: track.artist || track.artistName || '',
      album: 'Snapsa',
      artwork: track.coverUrl ? [
        { src: track.coverUrl, sizes: '512x512', type: 'image/jpeg' },
      ] : [],
    });
    navigator.mediaSession.setActionHandler('play', () => { audio.play().catch(()=>{}); navigator.mediaSession.playbackState = 'playing'; });
    navigator.mediaSession.setActionHandler('pause', () => { audio.pause(); navigator.mediaSession.playbackState = 'paused'; });
    navigator.mediaSession.setActionHandler('stop', () => { audio.pause(); audio.currentTime = 0; navigator.mediaSession.playbackState = 'none'; setPlayingPreviewId(null); });
    navigator.mediaSession.setActionHandler('seekbackward', (details) => { audio.currentTime = Math.max(0, audio.currentTime - (details.seekOffset || 10)); });
    navigator.mediaSession.setActionHandler('seekforward', (details) => { audio.currentTime = Math.min(audio.duration || Infinity, audio.currentTime + (details.seekOffset || 10)); });
    navigator.mediaSession.setActionHandler('seekto', (details) => { if (details.seekTime != null) audio.currentTime = details.seekTime; });
    navigator.mediaSession.playbackState = 'playing';
  };

  const clearMediaSession = () => {
    if (!('mediaSession' in navigator)) return;
    navigator.mediaSession.playbackState = 'none';
  };

  const togglePreview = (track) => {
    if (playingPreviewId === track.id) {
      audioRef.current?.pause();
      setPlayingPreviewId(null);
      return;
    }
    const url = track.previewUrl || mediaHref(track.previewKey);
    if (!url) { showToast?.('Preview unavailable', 'error'); return; }
    if (audioRef.current) { audioRef.current.pause(); }
    const audio = new Audio(url);
    audio.play().catch(() => showToast?.('Could not play preview', 'error'));
    audio.onended = () => setPlayingPreviewId(null);
    audioRef.current = audio;
    // No applyMediaSession here either — see the note in handlePlayFull.
    setPlayingPreviewId(track.id);
  };

  const pollPurchaseStatus = (txRef, track, attemptsLeft = 10) => {
    snapFetch(`/snapsa/music/purchase/status/${txRef}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (d?.status === 'completed') {
          setTracks(prev => prev.map(t => t.id === track.id ? { ...t, owned:true } : t));
          setPurchasingId(null);
          showToast?.(`🎵 "${track.title}" is yours!`, 'success');
          if (subTab === 'library') loadLibrary();
          return;
        }
        if (attemptsLeft > 0) setTimeout(() => pollPurchaseStatus(txRef, track, attemptsLeft - 1), 1500);
        else { setPurchasingId(null); showToast?.('Payment still processing — check back shortly', 'info'); }
      })
      .catch(() => { setPurchasingId(null); });
  };

  const handleBuy = async (track) => {
    if (isGuest) {
      showToast?.('Sign in to buy tracks', 'info');
      window.dispatchEvent(new CustomEvent('snapsa:requestAuth'));
      return;
    }
    setPurchasingId(track.id);
    try {
      const initRes = await snapFetch('/snapsa/music/purchase/init', { method:'POST', body: JSON.stringify({ trackId: track.id }) });
      if (!initRes.ok) throw new Error('init failed');
      const { txRef, amount, trackTitle } = await initRes.json();

      if (!FLW_PUBLIC_KEY) {
        showToast?.('Payments not configured yet', 'error');
        setPurchasingId(null);
        return;
      }
      await ensureFlutterwaveScript();
      window.FlutterwaveCheckout({
        public_key: FLW_PUBLIC_KEY,
        tx_ref: txRef,
        amount,
        currency: 'USD',
        customer: { email: currentUser?.email || `${currentUser?._id || 'guest'}@snapsa.app` },
        customizations: { title: 'Snapsa Music', description: trackTitle || track.title },
        callback: () => pollPurchaseStatus(txRef, track),
        onclose: () => setPurchasingId(prev => prev === track.id ? null : prev),
      });
    } catch {
      showToast?.('Could not start checkout', 'error');
      setPurchasingId(null);
    }
  };

    const handlePlayFull = async (track, adToken) => {
    try {
      const res = await snapFetch(`/snapsa/music/tracks/${track.id}/play-full${adToken ? `?adToken=${encodeURIComponent(adToken)}` : ''}`);

      if (!res.ok) throw new Error();
      const { audioUrl, videoUrl } = await res.json();
      audioRef.current?.pause();
      clearMediaSession();
      if (audioUrl) {
        const audio = new Audio(audioUrl);
        audio.play().catch(() => showToast?.('Could not play track', 'error'));
        audio.onended = () => setAudioPlayerTrack(null);
        audioRef.current = audio;
        // NOT calling applyMediaSession here on purpose — registering Media
        // Session metadata/action handlers makes some Android browsers show
        // their own native "expanded media" overlay, which can visually
        // take over instead of this custom in-page player. The custom
        // TrackAudioPlayer below is now the only "now playing" UI for a
        // full track; lock-screen/notification controls are traded off.
        setPlayingPreviewId(null);
        setAudioPlayerTrack({ track, audio });
      } else if (videoUrl) {
        setPlayingPreviewId(null);
        setVideoPlayerTrack({ url: videoUrl, title: track.title, artist: track.artist, track });
      } else {
        showToast?.('Nothing to play for this track', 'error');
      }
    } catch { showToast?.('Could not load track', 'error'); }
  };

const handlePlayWithAds = async (track) => {
    try {
      const res = await snapFetch(`/snapsa/music/tracks/${track.id}/ad-start`, { method:'POST', body: JSON.stringify({}) });
      const d = await res.json().catch(() => ({}));
      if (!res.ok) { showToast?.(d.error || 'Could not start the ad', 'error'); return; }
      setAdGate({ track, token: d.token, minSeconds: d.minSeconds || 8 });
    } catch { showToast?.('No connection', 'error'); }
  };

  const finishAdGate = async () => {
    const g = adGate; setAdGate(null);
    if (!g) return;
    try {
      const res = await snapFetch(`/snapsa/music/tracks/${g.track.id}/ad-complete`, { method:'POST', body: JSON.stringify({ token: g.token }) });
      const d = await res.json().catch(() => ({}));
      if (!res.ok || !d.adToken) { showToast?.(d.error || 'The ad did not finish', 'error'); return; }
      handlePlayFull(g.track, d.adToken);
    } catch { showToast?.('No connection', 'error'); }
  };
  
  const handleDownload = async (track) => {
    try {
      const res = await snapFetch(`/snapsa/music/tracks/${track.id}/download`);
      if (!res.ok) throw new Error();
      const { downloadUrl } = await res.json();
      window.open(downloadUrl, '_blank');
    } catch { showToast?.('Could not download track', 'error'); }
  };

  const handleUseSound = (track) => {
    window.dispatchEvent(new CustomEvent('snapsa:switchTab', { detail:'feed' }));
    window.dispatchEvent(new CustomEvent('snapsa:useSound', { detail:{ soundId: track.id, title: track.title, previewUrl: track.previewUrl } }));
    showToast?.(`🎵 "${track.title}" ready to use`, 'info');
  };

  const list = subTab === 'browse' ? tracks : library;

  const handleUploadClick = () => setShowUpload(true);

  return (
    <div style={{ flex:1, overflowY:'auto', position:'relative', zIndex:1, display:'flex', flexDirection:'column' }}>
      <div style={{ padding:'14px 16px 8px' }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
          <p style={{ color:'#22d3ee', fontWeight:800, fontSize:12, letterSpacing:1, margin:0, textTransform:'uppercase' }}>
            {contentSection === 'music' ? 'Snapsa Music' : contentSection === 'tv' ? 'Snapsa TV' : contentSection === 'radio' ? 'Snapsa Radio' : contentSection === 'news' ? 'Snapsa News' : 'Snapsa Podcasts'}
          </p>
          <div style={{ display:'flex', alignItems:'center', gap:8 }}>
            {contentSection === 'music' && subTab === 'browse' && (
              <button onClick={()=>setShowSearchInput(v=>!v)} title="Search"
                style={{ display:'flex', alignItems:'center', justifyContent:'center', width:34, height:34, background: showSearchInput ? S.pink : S.card, border:`1px solid ${S.border}`, borderRadius:'50%', cursor:'pointer' }}>
                <Search size={15} style={{ color: showSearchInput ? 'white' : S.gray }}/>
              </button>
            )}
            {contentSection === 'music' && !isGuest && (
              <button onClick={handleUploadClick} title="Upload"
                style={{ display:'flex', alignItems:'center', justifyContent:'center', width:34, height:34, background:S.card, border:`1px solid ${S.border}`, borderRadius:'50%', cursor:'pointer' }}>
                <Upload size={15} style={{ color:S.pink }}/>
              </button>
            )}
          </div>
        </div>
        {contentSection === 'music' && !isGuest && artistProfile && (
          <button onClick={()=>setShowArtistProfileModal(true)}
            style={{ display:'block', textAlign:'left', background:'none', border:'none', padding:0, marginTop:6, cursor:'pointer' }}>
            <span style={{ color:'white', fontWeight:700, fontSize:15 }}>{artistProfile.artistName}</span>          
            {artistProfile.status === 'pending' && <span style={{ color:'#fbbf24', fontSize:11.5, fontWeight:700 }}> ⏳ awaiting approval</span>}             {artistProfile.status === 'rejected' && <span style={{ color:'#ef4444', fontSize:11.5, fontWeight:700 }}> ❌ not approved</span>}
            {(artistProfile.country || artistProfile.genre || artistProfile.trackCount != null) && (
              <span style={{ color:S.gray, fontSize:12.5 }}>
                {' '}{[
                  [flagForCountry(artistProfile.country), artistProfile.country].filter(Boolean).join(' '),
                  artistProfile.genre,
                  artistProfile.trackCount != null ? `${artistProfile.trackCount} song${artistProfile.trackCount===1?'':'s'}` : null,
                ].filter(Boolean).join(' | ')}
              </span>
            )}
          </button>
        )}
      </div>

      {/* Content-type tabs — Music / Radio / TV / News / Podcasts */}
      <div style={{ display:'flex', gap:8, padding:'0 16px 14px', overflowX:'auto' }}>
        {CONTENT_SECTIONS.map(sec => {
          const Icon = sec.icon;
          const active = contentSection === sec.id;
          return (
            <button key={sec.id} onClick={()=>setContentSection(sec.id)}
              style={{ flexShrink:0, display:'flex', alignItems:'center', gap:6, padding:'8px 14px', borderRadius:999, border:'none', cursor:'pointer',
                background: active ? `linear-gradient(135deg,${S.pink},#7c3aed)` : S.card, color: active ? 'white' : S.gray, fontWeight:700, fontSize:12.5 }}>
              <Icon size={13}/>
              {t(`contentSections.${sec.id}`)}
            </button>
          );
        })}
      </div>

      {contentSection === 'radio' && <ChannelPostsScreen accountType="radio_station" currentUser={currentUser} showToast={showToast}/>}
      {contentSection === 'tv' && <TVScreen currentUser={currentUser} showToast={showToast} isActive={isActive}/>}
      {contentSection === 'news' && <ChannelPostsScreen accountType="news_channel" currentUser={currentUser} showToast={showToast}/>}
      {contentSection === 'podcasts' && <ChannelPostsScreen accountType="podcast" currentUser={currentUser} showToast={showToast}/>}

      {contentSection === 'music' && (<>
      <div style={{ display:'flex', gap:8, padding:'4px 16px 12px' }}>
        {['browse','library', ...(artistProfile ? ['streams'] : [])].map(tabId => (
          <button key={tabId} onClick={()=>setSubTab(tabId)}
            style={{ flex:1, padding:'9px 0', borderRadius:999, border:'none', cursor:'pointer',
              background: subTab===tabId ? S.pink : S.card,
              color: subTab===tabId ? 'white' : S.gray, fontWeight:700, fontSize:13 }}>
            {tabId==='browse' ? t('music.browse') : tabId==='library' ? t('music.myLibrary') : 'Streams'}
          </button>
        ))}
      </div>

      {subTab==='streams' ? (
        <MusicStreamsTab showToast={showToast}/>
      ) : (
        <>
          {subTab==='browse' && (
            <div style={{ padding:'0 16px 12px' }}>
              {showSearchInput && (
                <div style={{ display:'flex', alignItems:'center', gap:10, background:S.card, borderRadius:12, padding:'11px 14px', border:`1px solid ${S.border}`, marginBottom:10 }}>
                  <Search size={17} style={{ color:S.gray }}/>
                  <input value={query} onChange={e=>handleSearchChange(e.target.value)} placeholder={t('music.searchPlaceholder')} autoFocus
                    style={{ flex:1, background:'transparent', border:'none', outline:'none', color:'white', fontSize:14 }}/>
                  {query && <button onClick={()=>handleSearchChange('')} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={15} style={{ color:S.gray }}/></button>}
                </div>
              )}
              <div style={{ display:'flex', gap:8, overflowX:'auto', paddingBottom:2 }}>
                {['All', ...MUSIC_GENRES].map(g => (
                  <button key={g} onClick={()=>handleGenreSelect(g)}
                    style={{ flexShrink:0, padding:'7px 14px', borderRadius:999, border:'none', cursor:'pointer', whiteSpace:'nowrap',
                      background: selectedGenre===g ? S.pink : S.card, color: selectedGenre===g ? 'white' : S.gray, fontWeight:600, fontSize:12.5 }}>
                    {g}
                  </button>
                ))}
              </div>
            </div>
          )}

          {loading && (
            <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:14 }}>
              <div style={{ width:36, height:36, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>
              <p style={{ color:S.gray, fontSize:13, fontWeight:600 }}>Loading tracks…</p>
              <style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style>
            </div>
          )}

          {!loading && subTab==='library' && isGuest && (
            <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, padding:32 }}>
              <ShoppingBag size={40} style={{ color:S.gray, opacity:0.5 }}/>
              <p style={{ color:S.gray, fontSize:13, textAlign:'center' }}>{t('music.signInToSeePurchases')}</p>
            </div>
          )}

          {!loading && list.length===0 && !(subTab==='library' && isGuest) && (
            <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, padding:32 }}>
              <Music2 size={40} style={{ color:S.gray, opacity:0.5 }}/>
              <p style={{ color:S.gray, fontSize:13, textAlign:'center' }}>
                {subTab==='browse' ? (query ? `${t('music.noneMatch')} "${query}"` : t('music.noTracksYet')) : "You haven't bought any tracks yet"}
              </p>
            </div>
          )}

          {/* "Recommended for today" — Spotify-style horizontal cards using
              covered tracks, only on the default (unsearched, All genre) browse view */}
          {!loading && subTab==='browse' && !query && selectedGenre==='All' && list.some(t=>t.coverUrl) && (
            <div style={{ marginBottom:18 }}>
              <p style={{ color:'white', fontWeight:800, fontSize:16, margin:'0 0 12px', padding:'0 16px' }}>{t('music.recommendedForToday')}</p>
              <div style={{ display:'flex', gap:12, overflowX:'auto', padding:'0 16px 4px' }}>
                {list.filter(t=>t.coverUrl).slice(0,10).map(track => (
                  <button key={`rec-${track.id}`} onClick={()=>setDetailsTrack(track)}
                    style={{ flexShrink:0, width:132, background:'none', border:'none', padding:0, cursor:'pointer', textAlign:'left' }}>
                    <div style={{ position:'relative', width:132, height:132, borderRadius:12, overflow:'hidden', marginBottom:8, boxShadow:'0 6px 16px rgba(0,0,0,0.4)' }}>
                      <img src={track.coverUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover', display:'block' }}/>
                      {!track.owned && (
                        <div style={{ position:'absolute', top:6, right:6, background:S.yellow, borderRadius:6, padding:'2px 5px', fontSize:8.5, fontWeight:800, color:'#000' }}>
                          {Number.isFinite(track.priceUsd) ? `$${track.priceUsd.toFixed(2)}` : ''}
                        </div>
                      )}
                      {track.owned && (
                        <div style={{ position:'absolute', top:6, right:6, background:'rgba(0,0,0,0.6)', borderRadius:6, padding:'2px 6px', fontSize:8.5, fontWeight:800, color:S.pink }}>
                          FREE
                        </div>
                      )}
                    </div>
                    <p style={{ color:S.gray, fontSize:10.5, fontWeight:700, textTransform:'uppercase', letterSpacing:0.5, margin:'0 0 2px' }}>
                      {track.album ? 'Album' : 'Single'}
                    </p>
                    <p style={{ color:'white', fontWeight:700, fontSize:13, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis', margin:'0 0 2px' }}>
                      {track.title}
                    </p>
                    <p style={{ color:S.gray, fontSize:11.5, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis', margin:0 }}>
                      {track.artistName || 'Unknown'}
                    </p>
                  </button>
                ))}
              </div>
            </div>
          )}

          {!loading && list.length > 0 && !loading && subTab==='browse' && !query && selectedGenre==='All' && (
            <p style={{ color:'white', fontWeight:800, fontSize:16, margin:'0 0 4px', padding:'0 16px 8px' }}>{t('music.allTracks')}</p>
          )}

          {!loading && list.map(track => (
            <MusicTrackCard
              key={track.id}
              track={track}
              isPlayingPreview={playingPreviewId===track.id}
              purchasing={purchasingId===track.id}
              onTogglePreview={togglePreview}
              onBuy={handleBuy}
              onPlayFull={handlePlayFull}
              onDownload={handleDownload}
              onUseSound={handleUseSound}
              onShowDetails={setDetailsTrack}
            />
          ))}
        </>
      )}
      </>)}

      <AnimatePresence>
        {showArtistProfileModal && (
          <ArtistProfileModal
            showToast={showToast}
            existingProfile={artistProfile || undefined}             lockedType="artist"
            onClose={()=>setShowArtistProfileModal(false)}
            onCreated={(profile)=>{
                            if (!profile?.artistName) {
                showToast?.("Couldn't confirm your artist profile saved — please try again.", 'error');
                return;
              }
              setArtistProfile(profile); setShowArtistProfileModal(false);
              if (profile.enabled) setShowUpload(true);
            }}
            onUpdated={(profile)=>{ setArtistProfile(profile); setShowArtistProfileModal(false); }}
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showUpload && (
          <MusicUploadModal onClose={()=>setShowUpload(false)} showToast={showToast} onUploaded={()=>loadBrowse(query)}
            artistProfile={artistProfile} onArtistProfileSaved={(profile)=>setArtistProfile(profile)}/>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {videoPlayerTrack && (
                    <SnapsaMusicPlayer track={videoPlayerTrack.track || { title: videoPlayerTrack.title, artist: videoPlayerTrack.artist }}
            videoUrl={videoPlayerTrack.url} showToast={showToast}
            onClose={()=>setVideoPlayerTrack(null)}
            onDeleted={(trackId)=>setTracks(prev => prev.filter(t => t.id !== trackId))}/>
      )}
        
      </AnimatePresence>

      <AnimatePresence>
        {audioPlayerTrack && (
          <SnapsaMusicPlayer track={audioPlayerTrack.track} audio={audioPlayerTrack.audio} showToast={showToast}
            onClose={()=>setAudioPlayerTrack(null)}
            onDeleted={(trackId)=>setTracks(prev => prev.filter(t => t.id !== trackId))}/>
        )}
      </AnimatePresence>

            {adGate && <MusicAdGate minSeconds={adGate.minSeconds} onDone={finishAdGate} onCancel={()=>setAdGate(null)}/>}

      <AnimatePresence>
        {detailsTrack && (
          <TrackDetailsModal track={detailsTrack} onClose={()=>setDetailsTrack(null)}
            onPlayWithAds={handlePlayWithAds}
            onPlayFull={handlePlayFull} onTogglePreview={togglePreview} onBuy={handleBuy}

            purchasing={purchasingId===detailsTrack.id}/>
        )}
      </AnimatePresence>
    </div>
  );
};

// ─── TV Episode Row — Watch (subscription-gated) + Download (pay-per-item) ──
const TVEpisodeRow = ({ episode, canWatch, downloading, onWatch, onDownload }) => {
  const { t } = useLanguage();
  return (
  <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', borderBottom:`1px solid ${S.border}` }}>
    <button onClick={()=>canWatch && onWatch(episode)}
      style={{ position:'relative', width:64, height:44, borderRadius:8, flexShrink:0, border:'none', cursor: canWatch ? 'pointer' : 'default', overflow:'hidden',
        background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
      {episode.thumbUrl && <img src={episode.thumbUrl} alt="" style={{ position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover' }}/>}
      {canWatch ? <Play size={16} fill="white" style={{ color:'white', position:'relative' }}/> : <Lock size={14} style={{ color:'white', position:'relative' }}/>}
    </button>
    <div style={{ flex:1, minWidth:0 }}>
      <p style={{ color:'white', fontWeight:700, fontSize:14, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>
        {episode.episodeNumber ? `E${episode.episodeNumber} · ` : ''}{episode.title}
      </p>
      <p style={{ color:S.gray, fontSize:11, marginTop:2 }}>{fmt(episode.viewCount||0)} {t('common.views')}</p>
    </div>
    <div style={{ flexShrink:0, display:'flex', flexDirection:'column', gap:6, alignItems:'flex-end' }}>
      {canWatch && (
        <button onClick={()=>onWatch(episode)}
          style={{ display:'flex', alignItems:'center', gap:4, background:S.card, border:`1px solid ${S.border}`, borderRadius:999, padding:'6px 12px', cursor:'pointer' }}>
          <Play size={11} style={{ color:'white' }} fill="white"/>
          <span style={{ color:'white', fontSize:11.5, fontWeight:700 }}>{t('common.watch')}</span>
        </button>
      )}
      <button onClick={()=>onDownload(episode)} disabled={downloading || episode.downloaded}
        style={{ display:'flex', alignItems:'center', gap:4, background: episode.downloaded ? 'transparent' : S.pink, border: episode.downloaded ? `1px solid ${S.border}` : 'none', borderRadius:999, padding:'6px 12px', cursor: (downloading||episode.downloaded) ? 'default' : 'pointer', opacity: downloading ? 0.6 : 1 }}>
        <Download size={11} style={{ color: episode.downloaded ? S.gray : 'white' }}/>
        <span style={{ color: episode.downloaded ? S.gray : 'white', fontSize:11.5, fontWeight:700 }}>
          {episode.downloaded ? t('common.downloaded') : downloading ? '…' : (episode.downloadIsFree ? t('common.download') : `${episode.downloadPrice||0} ${t('common.coins')}`)}
        </span>
      </button>
    </div>
  </div>
  );
};

const CreateShowModal = ({ onClose, showToast, onCreated }) => {
  const { t } = useLanguage();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('Series');
  const [genre, setGenre] = useState('');
  const [coverFile, setCoverFile] = useState(null);
  const [coverPreview, setCoverPreview] = useState(null);
  const [saving, setSaving] = useState(false);

  const pickCover = (file) => {
    if (!file) return;
    setCoverFile(file);
    const reader = new FileReader();
    reader.onload = () => setCoverPreview(reader.result);
    reader.readAsDataURL(file);
  };

  const submit = async () => {
    if (!title.trim()) { showToast?.('Give the show a title', 'error'); return; }
    setSaving(true);
    try {
      const body = { title: title.trim(), description: description.trim(), genre, category };
      if (coverPreview) body.coverBase64 = coverPreview;
      const res = await snapFetch('/snapsa/tv/shows', { method:'POST', body: JSON.stringify(body) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Could not create show');
      showToast?.('📺 Show created!', 'success');
      onCreated?.(data.show);
    } catch (err) {
      showToast?.(err.message || 'Something went wrong', 'error');
    }
    setSaving(false);
  };

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.85)', zIndex:70, display:'flex', alignItems:'flex-end' }}
      onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
        onClick={e=>e.stopPropagation()}
        style={{ width:'100%', background:S.dark, borderTop:`1px solid ${S.border}`, borderRadius:'20px 20px 0 0', padding:20, paddingBottom:'calc(20px + env(safe-area-inset-bottom,0px))', maxHeight:'88vh', overflowY:'auto' }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16 }}>
          <h2 style={{ color:'white', fontWeight:800, fontSize:17 }}>New Show</h2>
          <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={20} style={{ color:S.gray }}/></button>
        </div>
        <label style={{ display:'flex', alignItems:'center', gap:12, marginBottom:16, cursor:'pointer' }}>
          <div style={{ width:56, height:56, borderRadius:12, overflow:'hidden', flexShrink:0, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
            {coverPreview ? <img src={coverPreview} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Tv size={22} style={{ color:'white' }}/>}
          </div>
          <span style={{ color:S.pink, fontSize:13, fontWeight:600 }}>{coverFile ? 'Change cover' : 'Add cover art'}</span>
          <input type="file" accept="image/*" style={{ display:'none' }} onChange={e=>pickCover(e.target.files?.[0]||null)}/>
        </label>

        <label style={{ display:'block', color:S.gray, fontSize:12, fontWeight:600, marginBottom:8 }}>Category tab</label>
        <div style={{ display:'flex', gap:8, marginBottom:12, flexWrap:'wrap' }}>
          {TV_CATEGORIES.map(cat => (
            <button key={cat} type="button" onClick={()=>setCategory(cat)}
              style={{ padding:'8px 14px', borderRadius:999, border:'none', cursor:'pointer',
                background: category===cat ? S.pink : S.card, color: category===cat ? 'white' : S.gray, fontWeight:700, fontSize:12.5 }}>
              {t(`tv.categories.${cat}`)}
            </button>
          ))}
        </div>

        <input value={title} onChange={e=>setTitle(e.target.value.slice(0,80))} placeholder={category==='Movies' ? 'Movie title' : 'Show title'}
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}/>
        <select value={genre} onChange={e=>setGenre(e.target.value)}
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color: genre?'white':S.gray, outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}>
          <option value="">Genre (optional)</option>
          {MUSIC_GENRES.concat(['Drama','Comedy','News','Sport','Kids','Reality','Documentary','Talk Show','Other']).filter((v,i,a)=>a.indexOf(v)===i).map(g => <option key={g} value={g}>{g}</option>)}
        </select>
        <textarea value={description} onChange={e=>setDescription(e.target.value.slice(0,500))} placeholder="Short description (optional)" rows={3}
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:16, boxSizing:'border-box', resize:'none' }}/>
        <button onClick={submit} disabled={!title.trim() || saving}
          style={{ width:'100%', padding:14, borderRadius:12, border:'none', cursor: title.trim()&&!saving ? 'pointer':'default',
            background: title.trim()&&!saving ? S.pink : S.border, color:'white', fontWeight:800, fontSize:14 }}>
          {saving ? 'Creating…' : `Create ${category==='Movies' ? 'Movie' : 'Show'}`}
        </button>
      </motion.div>
    </motion.div>
  );
};

const EpisodeUploadModal = ({ onClose, showToast, onUploaded, shows }) => {
  const { t } = useLanguage();
  const [showId, setShowId] = useState(shows?.[0]?.id || '');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [videoFile, setVideoFile] = useState(null);
  const [thumbnail, setThumbnail] = useState(null);
  const [downloadIsFree, setDownloadIsFree] = useState(false);
  const [price, setPrice] = useState('1.00');
  const [agreedToRights, setAgreedToRights] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const uploadInFlightRef = useRef(false);

  const canSubmit = showId && title.trim() && videoFile && agreedToRights && !uploading;

  const submit = async () => {
    if (uploadInFlightRef.current) return;
    uploadInFlightRef.current = true;
    setUploading(true);
    setUploadProgress(0);
    try {
      const fd = new FormData();
      fd.append('showId', showId);
      fd.append('title', title.trim());
      fd.append('description', description.trim());
      fd.append('video', videoFile);
      if (thumbnail) fd.append('thumbnail', thumbnail);
      fd.append('downloadIsFree', downloadIsFree ? 'true' : 'false');
      fd.append('price', price);
      fd.append('copyrightAgreementAccepted', 'true');
      const res = await snapUploadWithProgress('/snapsa/tv/episodes/upload', fd, { onProgress: setUploadProgress });
      if (!res.ok) throw new Error(res.json?.error || 'Upload failed');
      showToast?.('📺 Episode submitted!', 'success');
      onUploaded?.();
      onClose();
    } catch (err) {
      showToast?.(err.message || 'Upload failed — try again', 'error');
    } finally {
      uploadInFlightRef.current = false;
      setUploading(false);
      setUploadProgress(0);
    }
  };

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.85)', zIndex:70, display:'flex', alignItems:'flex-end' }}
      onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
        onClick={e=>e.stopPropagation()}
        style={{ width:'100%', background:S.dark, borderTop:`1px solid ${S.border}`, borderRadius:'20px 20px 0 0', padding:20, paddingBottom:'calc(20px + env(safe-area-inset-bottom,0px))', maxHeight:'88vh', overflowY:'auto' }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16 }}>
          <h2 style={{ color:'white', fontWeight:800, fontSize:17 }}>{t('tv.uploadEpisode')}</h2>
          <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={20} style={{ color:S.gray }}/></button>
        </div>

        {!shows?.length ? (
          <p style={{ color:S.gray, fontSize:13, textAlign:'center', padding:'20px 0' }}>Create a show first before uploading episodes.</p>
        ) : (
          <>
            <select value={showId} onChange={e=>setShowId(e.target.value)}
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}>
              {shows.map(s => <option key={s.id} value={s.id}>{s.title} ({s.category})</option>)}
            </select>
            <input value={title} onChange={e=>setTitle(e.target.value.slice(0,80))} placeholder={t('common.title')}
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}/>
            <textarea value={description} onChange={e=>setDescription(e.target.value.slice(0,500))} placeholder={t('common.descriptionOptional')} rows={2}
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box', resize:'none' }}/>

            <label style={{ display:'flex', alignItems:'center', gap:10, background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:10, cursor:'pointer' }}>
              <Upload size={16} style={{ color:S.pink }}/>
              <span style={{ color:videoFile?'white':S.gray, fontSize:13 }}>{videoFile ? videoFile.name : 'Episode video'}</span>
              <input type="file" accept="video/*" style={{ display:'none' }} onChange={e=>setVideoFile(e.target.files?.[0]||null)}/>
            </label>
            <label style={{ display:'flex', alignItems:'center', gap:10, background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:10, cursor:'pointer' }}>
              <Upload size={16} style={{ color:S.pink }}/>
              <span style={{ color:thumbnail?'white':S.gray, fontSize:13 }}>{thumbnail ? thumbnail.name : t('common.thumbnailOptional')}</span>
              <input type="file" accept="image/*" style={{ display:'none' }} onChange={e=>setThumbnail(e.target.files?.[0]||null)}/>
            </label>

            <p style={{ color:S.gray, fontSize:11, marginBottom:10, lineHeight:1.5 }}>
              Anyone subscribed to your channel can watch this. The setting below only controls whether downloading it for offline costs extra.
            </p>

            <button type="button" onClick={()=>setDownloadIsFree(v=>!v)}
              style={{ display:'flex', alignItems:'center', gap:10, width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:10, cursor:'pointer', textAlign:'left' }}>
              <div style={{ width:20, height:20, borderRadius:6, border:`2px solid ${downloadIsFree?S.pink:S.gray}`, background:downloadIsFree?S.pink:'transparent', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
                {downloadIsFree && <Check size={13} style={{ color:'white' }}/>}
              </div>
              <div>
                <p style={{ color:'white', fontSize:13, fontWeight:700, margin:0 }}>{t('common.freeToDownload')}</p>
                <p style={{ color:S.gray, fontSize:11, margin:'2px 0 0' }}>Subscribers can save it for offline at no extra cost</p>
              </div>
            </button>

            {!downloadIsFree && (
              <div style={{ marginBottom:10 }}>
                <label style={{ display:'block', color:S.gray, fontSize:12, fontWeight:600, marginBottom:6 }}>{t('common.downloadPriceCoins')}</label>
                <input value={price} onChange={e=>setPrice(e.target.value.replace(/[^0-9.]/g,''))} inputMode="decimal" placeholder="1.00"
                  style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'11px 14px', color:'white', outline:'none', fontSize:14, boxSizing:'border-box' }}/>
              </div>
            )}

            <label style={{ display:'flex', alignItems:'flex-start', gap:10, background:S.card, border:`1px solid ${agreedToRights?S.pink:S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:16, cursor:'pointer' }}>
              <input type="checkbox" checked={agreedToRights} onChange={e=>setAgreedToRights(e.target.checked)} style={{ marginTop:2 }}/>
              <span style={{ color:S.gray, fontSize:11.5, lineHeight:1.5 }}>{t('common.confirmRights')}</span>
            </label>

            {uploading && (
              <div style={{ marginBottom:12 }}>
                <div style={{ height:6, background:S.card, borderRadius:999, overflow:'hidden' }}>
                  <div style={{ height:'100%', width:`${uploadProgress}%`, background:S.pink, transition:'width .2s' }}/>
                </div>
              </div>
            )}

            <button onClick={submit} disabled={!canSubmit}
              style={{ width:'100%', padding:14, borderRadius:12, border:'none', cursor: canSubmit ? 'pointer':'default',
                background: canSubmit ? S.pink : S.border, color:'white', fontWeight:800, fontSize:14 }}>
              {uploading ? `${t('common.uploading')} ${uploadProgress}%` : t('common.publishing')}
            </button>
          </>
        )}
      </motion.div>
    </motion.div>
  );
};

// ─── A TV channel's own profile — category tabs, subscribe gate ─────────
const TVChannelProfile = ({ channelId, currentUser, showToast, onClose }) => {
  const { t } = useLanguage();
  const [data, setData] = useState(null); // { channel, subscribed, subscriptionExpiresAt, showsByCategory }
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState('Series');
  const [subscribing, setSubscribing] = useState(false);
  const [selectedShow, setSelectedShow] = useState(null); // { show, canWatch, episodes }
  const [downloadingId, setDownloadingId] = useState(null);
  const [videoPlayer, setVideoPlayer] = useState(null);
  const isGuest = currentUser?.isGuest === true;

  const load = () => {
    setLoading(true);
    snapFetch(`/snapsa/tv/channel/${channelId}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (d) { setData(d); const firstNonEmpty = TV_CATEGORIES.find(c => d.showsByCategory[c]?.length); if (firstNonEmpty) setActiveCategory(firstNonEmpty); } })
      .catch(() => showToast?.('Could not load channel', 'error'))
      .finally(() => setLoading(false));
  };
  useEffect(() => { load(); }, [channelId]);

  const pollSubscribeStatus = (txRef, attemptsLeft = 10) => {
    snapFetch(`/snapsa/tv/subscribe/status/${txRef}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (d?.status === 'completed') {
          setSubscribing(false);
          showToast?.('📺 Subscribed!', 'success');
          load();
          return;
        }
        if (attemptsLeft > 0) setTimeout(() => pollSubscribeStatus(txRef, attemptsLeft - 1), 1500);
        else { setSubscribing(false); showToast?.('Payment still processing — check back shortly', 'info'); }
      })
      .catch(() => setSubscribing(false));
  };

  const handleSubscribe = async () => {
    if (isGuest) { showToast?.('Sign in to subscribe', 'info'); window.dispatchEvent(new CustomEvent('snapsa:requestAuth')); return; }
    setSubscribing(true);
    try {
      const res = await snapFetch('/snapsa/tv/subscribe/init', { method:'POST', body: JSON.stringify({ channelId }) });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || 'Could not subscribe');
      pollSubscribeStatus(d.transactionRef);
    } catch (err) {
      showToast?.(err.message || 'Could not subscribe', 'error');
      setSubscribing(false);
    }
  };

  const openShow = (show) => {
    snapFetch(`/snapsa/tv/shows/${show.id}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (d) setSelectedShow(d); })
      .catch(() => showToast?.('Could not load show', 'error'));
  };

  const handleWatch = async (episode) => {
    if (!episode.videoFile) { showToast?.('Video unavailable', 'error'); return; }
    snapFetch(`/snapsa/tv/episodes/${episode.id}/view`, { method:'POST' }).catch(()=>{});
    setVideoPlayer({ url: episode.videoFile, title: episode.title, artist: data?.channel?.channelName });
  };

  const pollDownloadStatus = (txRef, episode, attemptsLeft = 10) => {
    snapFetch(`/snapsa/tv/download/status/${txRef}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (d?.status === 'completed') {
          setDownloadingId(null);
          setSelectedShow(prev => prev ? { ...prev, episodes: prev.episodes.map(e => e.id===episode.id ? { ...e, downloaded:true } : e) } : prev);
          triggerBrowserDownload(d.downloadUrl, `${episode.title}.mp4`);
          showToast?.('⬇️ Downloading…', 'success');
          return;
        }
        if (attemptsLeft > 0) setTimeout(() => pollDownloadStatus(txRef, episode, attemptsLeft - 1), 1500);
        else { setDownloadingId(null); showToast?.('Payment still processing — check back shortly', 'info'); }
      })
      .catch(() => setDownloadingId(null));
  };

  const handleDownload = async (episode) => {
    if (isGuest) { showToast?.('Sign in to download', 'info'); window.dispatchEvent(new CustomEvent('snapsa:requestAuth')); return; }
    if (episode.downloadIsFree) {
      // Free download still needs the sourced URL — reuse the download/init
      // path so it's one code path either way. Free items complete instantly server-side? No — free items skip purchase, so use canWatch's videoFile directly since it's already present when subscribed.
      if (!episode.videoFile) { showToast?.('Subscribe to unlock this download', 'info'); return; }
      triggerBrowserDownload(episode.videoFile, `${episode.title}.mp4`);
      return;
    }
    setDownloadingId(episode.id);
    try {
      const res = await snapFetch(`/snapsa/tv/episodes/${episode.id}/download/init`, { method:'POST' });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || 'Could not start download');
      pollDownloadStatus(d.transactionRef, episode);
    } catch (err) {
      showToast?.(err.message || 'Could not start download', 'error');
      setDownloadingId(null);
    }
  };

  if (loading) {
    return (
      <div style={{ position:'fixed', inset:0, background:S.dark, zIndex:60, display:'flex', alignItems:'center', justifyContent:'center' }}>
        <div style={{ width:36, height:36, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>
      </div>
    );
  }
  if (!data) return null;

  return (
    <motion.div initial={{ x:'100%' }} animate={{ x:0 }} exit={{ x:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
      style={{ position:'fixed', inset:0, background:S.dark, zIndex:60, display:'flex', flexDirection:'column' }}>
      <div style={{ display:'flex', alignItems:'center', gap:12, padding:16, borderBottom:`1px solid ${S.border}` }}>
        <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><ArrowLeft size={20} style={{ color:'white' }}/></button>
        <div style={{ width:40, height:40, borderRadius:10, overflow:'hidden', flexShrink:0, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
          {data.channel.avatarUrl ? <img src={data.channel.avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Tv size={18} style={{ color:'white' }}/>}
        </div>
        <div style={{ minWidth:0, flex:1 }}>
          <p style={{ color:'white', fontWeight:800, fontSize:15, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{data.channel.channelName}</p>
          {data.subscribed ? (
            <p style={{ color:S.pink, fontSize:11 }}>{t('common.subscribed')}</p>
          ) : (
            <p style={{ color:S.gray, fontSize:11 }}>{data.channel.subscriptionPriceCoins} {t('tv.coinsPerMonth')} — {t('tv.subscribeToWatch').toLowerCase()}</p>
          )}
        </div>
        {!data.subscribed && (
          <button onClick={handleSubscribe} disabled={subscribing || !data.channel.subscriptionPriceCoins}
            style={{ flexShrink:0, background:S.pink, border:'none', borderRadius:999, padding:'9px 16px', cursor:'pointer', opacity: subscribing?0.7:1 }}>
            <span style={{ color:'white', fontWeight:700, fontSize:12.5 }}>{subscribing ? t('common.processing') : t('common.subscribe')}</span>
          </button>
        )}
      </div>

      <div style={{ display:'flex', gap:8, padding:'12px 16px', overflowX:'auto' }}>
        {TV_CATEGORIES.map(cat => (
          <button key={cat} onClick={()=>setActiveCategory(cat)}
            style={{ flexShrink:0, padding:'8px 14px', borderRadius:999, border:'none', cursor:'pointer',
              background: activeCategory===cat ? S.pink : S.card, color: activeCategory===cat ? 'white' : S.gray, fontWeight:700, fontSize:12.5 }}>
            {t(`tv.categories.${cat}`)} {data.showsByCategory[cat]?.length ? `(${data.showsByCategory[cat].length})` : ''}
          </button>
        ))}
      </div>

      <div style={{ flex:1, overflowY:'auto' }}>
        {!data.showsByCategory[activeCategory]?.length ? (
          <p style={{ color:S.gray, fontSize:13, textAlign:'center', padding:32 }}>Nothing in {t(`tv.categories.${activeCategory}`)} yet</p>
        ) : (
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14, padding:'0 16px 24px' }}>
            {data.showsByCategory[activeCategory].map(show => (
              <button key={show.id} onClick={()=>openShow(show)} style={{ background:'none', border:'none', padding:0, cursor:'pointer', textAlign:'left' }}>
                <div style={{ width:'100%', aspectRatio:'1', borderRadius:12, overflow:'hidden', marginBottom:8, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
                  {show.coverUrl ? <img src={show.coverUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Tv size={28} style={{ color:'white' }}/>}
                </div>
                <p style={{ color:'white', fontWeight:700, fontSize:13, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{show.title}</p>
                {show.category !== 'Movies' && <p style={{ color:S.gray, fontSize:11.5 }}>{show.episodeCount} episode{show.episodeCount===1?'':'s'}</p>}
              </button>
            ))}
          </div>
        )}
      </div>

      <AnimatePresence>
        {selectedShow && (
          <motion.div initial={{ x:'100%' }} animate={{ x:0 }} exit={{ x:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
            style={{ position:'fixed', inset:0, background:S.dark, zIndex:65, display:'flex', flexDirection:'column' }}>
            <div style={{ display:'flex', alignItems:'center', gap:12, padding:16, borderBottom:`1px solid ${S.border}` }}>
              <button onClick={()=>setSelectedShow(null)} style={{ background:'none', border:'none', cursor:'pointer' }}><ArrowLeft size={20} style={{ color:'white' }}/></button>
              <p style={{ color:'white', fontWeight:800, fontSize:15, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{selectedShow.show.title}</p>
            </div>
            {!selectedShow.canWatch && (
              <div style={{ margin:16, padding:14, borderRadius:12, background:`${S.pink}12`, border:`1px solid ${S.pink}33`, display:'flex', alignItems:'center', gap:10 }}>
                <Lock size={16} style={{ color:S.pink, flexShrink:0 }}/>
                <p style={{ color:'white', fontSize:12.5, lineHeight:1.5, margin:0 }}>Subscribe to {data.channel.channelName} to watch — you can still download individual episodes below.</p>
              </div>
            )}
            <div style={{ flex:1, overflowY:'auto' }}>
              {selectedShow.episodes.length === 0 ? (
                <p style={{ color:S.gray, fontSize:13, textAlign:'center', padding:32 }}>No episodes yet</p>
              ) : selectedShow.episodes.map(ep => (
                <TVEpisodeRow key={ep.id} episode={ep} canWatch={selectedShow.canWatch} downloading={downloadingId===ep.id}
                  onWatch={handleWatch} onDownload={handleDownload}/>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {videoPlayer && (
          <SnapsaMusicPlayer label="SNAPSA TV" track={{ title: videoPlayer.title, artist: videoPlayer.artist }} videoUrl={videoPlayer.url} showToast={typeof showToast === 'function' ? showToast : undefined} onClose={()=>setVideoPlayer(null)}/>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

// ─── Snapsa TV — browse channels, manage your own channel ────────────────
const TVScreen = ({ currentUser, showToast, isActive = true }) => {
  const { t } = useLanguage();
  const [subTab, setSubTab] = useState('browse'); // 'browse' | 'myShows'
  const [query, setQuery] = useState('');
  const [channels, setChannels] = useState([]);
  const [myShows, setMyShows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [openChannelId, setOpenChannelId] = useState(null);
  const [channelProfile, setChannelProfile] = useState(undefined);
  const [showChannelModal, setShowChannelModal] = useState(false);
  const [showCreateShow, setShowCreateShow] = useState(false);
  const [showEpisodeUpload, setShowEpisodeUpload] = useState(false);
  const debounceRef = useRef(null);

  const isGuest = currentUser?.isGuest === true;
  const isChannel = channelProfile?.enabled && channelProfile?.accountType === 'tv_channel';

  useEffect(() => {
    if (isGuest) { setChannelProfile(null); return; }
snapFetch('/snapsa/music/artist-profile/mine?type=tv_channel')
      .then(r => r.ok ? r.json() : null)
      .then(d => setChannelProfile(d?.artistProfile || null))
      .catch(() => setChannelProfile(null));
  }, [isGuest]);

  const loadBrowse = (q = '') => {
    setLoading(true);
    const qs = q ? `?search=${encodeURIComponent(q)}` : '';
    snapFetch(`/snapsa/tv/channels${qs}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => setChannels(d?.channels || []))
      .catch(() => setChannels([]))
      .finally(() => setLoading(false));
  };

  const loadMyShows = () => {
    setLoading(true);
    snapFetch('/snapsa/tv/channel/mine/shows')
      .then(r => r.ok ? r.json() : null)
      .then(d => setMyShows(d?.shows || []))
      .catch(() => setMyShows([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    if (subTab === 'browse') loadBrowse(query);
    else loadMyShows();
  }, [subTab]);

  const handleSearchChange = (val) => {
    setQuery(val);
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => loadBrowse(val), 350);
  };

  return (
    <>
      <div style={{ display:'flex', gap:8, padding:'4px 16px 12px' }}>
        {['browse','myShows'].map(tabId => (
          <button key={tabId} onClick={()=>setSubTab(tabId)}
            style={{ flex:1, padding:'9px 0', borderRadius:999, border:'none', cursor:'pointer',
              background: subTab===tabId ? S.pink : S.card, color: subTab===tabId ? 'white' : S.gray, fontWeight:700, fontSize:13 }}>
            {tabId==='browse' ? t('tv.browse') : t('tv.myChannel')}
          </button>
        ))}
      </div>

      {subTab==='browse' && (
        <div style={{ padding:'0 16px 12px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:10, background:S.card, borderRadius:12, padding:'11px 14px', border:`1px solid ${S.border}` }}>
            <Search size={17} style={{ color:S.gray }}/>
            <input value={query} onChange={e=>handleSearchChange(e.target.value)} placeholder={t('music.searchPlaceholder')}
              style={{ flex:1, background:'transparent', border:'none', outline:'none', color:'white', fontSize:14 }}/>
            {query && <button onClick={()=>handleSearchChange('')} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={15} style={{ color:S.gray }}/></button>}
          </div>
        </div>
      )}

      {subTab==='myShows' && (
        <div style={{ padding:'0 16px 12px', display:'flex', gap:8 }}>
                    {channelProfile?.status === 'pending' || channelProfile?.status === 'rejected' ? (
            <CreatorStatusCard profile={channelProfile} onEdit={()=>setShowChannelModal(true)}/>
          ) : !isChannel ? (
            <button onClick={()=>setShowChannelModal(true)}
              style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', gap:8, padding:'12px 0', borderRadius:10, border:'none', cursor:'pointer', background:S.pink }}>
              <Tv size={15} style={{ color:'white' }}/>
              <span style={{ color:'white', fontWeight:700, fontSize:13 }}>{t('tv.setUpChannel')}</span>
            </button>
          ) : (<>
            <button onClick={()=>setShowChannelModal(true)}
              style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:6, padding:'12px 14px', borderRadius:10, border:`1px solid ${S.border}`, cursor:'pointer', background:S.card }}>
              <Settings size={14} style={{ color:S.gray }}/>
            </button>
            <button onClick={()=>setShowCreateShow(true)}
              style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', gap:8, padding:'12px 0', borderRadius:10, border:`1px solid ${S.border}`, cursor:'pointer', background:S.card }}>
              <Plus size={15} style={{ color:S.pink }}/>
              <span style={{ color:'white', fontWeight:700, fontSize:13 }}>{t('tv.newShow')}</span>
            </button>
            <button onClick={()=>setShowEpisodeUpload(true)}
              style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', gap:8, padding:'12px 0', borderRadius:10, border:'none', cursor:'pointer', background:S.pink }}>
              <Upload size={15} style={{ color:'white' }}/>
              <span style={{ color:'white', fontWeight:700, fontSize:13 }}>{t('tv.uploadEpisode')}</span>
            </button>
          </>)}
        </div>
      )}

      {loading && (
        <div style={{ display:'flex', alignItems:'center', justifyContent:'center', padding:'40px 0' }}>
          <div style={{ width:36, height:36, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>
          <style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style>
        </div>
      )}

      {!loading && subTab==='browse' && channels.length === 0 && (
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, padding:32 }}>
          <Tv size={40} style={{ color:S.gray, opacity:0.5 }}/>
          <p style={{ color:S.gray, fontSize:13, textAlign:'center' }}>{query ? `${t('music.noneMatch')} "${query}"` : t('tv.noChannelsYet')}</p>
        </div>
      )}

      {!loading && subTab==='browse' && channels.length > 0 && (
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14, padding:'0 16px 24px' }}>
          {channels.map(ch => (
            <button key={ch.channelId} onClick={()=>setOpenChannelId(ch.channelId)}
              style={{ background:'none', border:'none', padding:0, cursor:'pointer', textAlign:'left' }}>
              <div style={{ width:'100%', aspectRatio:'1', borderRadius:12, overflow:'hidden', marginBottom:8, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
                {ch.avatarUrl ? <img src={ch.avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : (ch.coverUrl ? <img src={ch.coverUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Tv size={28} style={{ color:'white' }}/>)}
              </div>
              <p style={{ color:'white', fontWeight:700, fontSize:13, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{ch.channelName}</p>
              <p style={{ color:S.gray, fontSize:11.5 }}>{ch.showCount} show{ch.showCount===1?'':'s'} · {ch.subscriptionPriceCoins} {t('tv.coinsPerMonth')}</p>
            </button>
          ))}
        </div>
      )}

      {!loading && subTab==='myShows' && isChannel && myShows.length === 0 && (
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, padding:32 }}>
          <Tv size={40} style={{ color:S.gray, opacity:0.5 }}/>
          <p style={{ color:S.gray, fontSize:13, textAlign:'center' }}>No shows yet — create your first one</p>
        </div>
      )}

      {!loading && subTab==='myShows' && isChannel && myShows.length > 0 && (
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14, padding:'0 16px 24px' }}>
          {myShows.map(show => (
            <div key={show.id} style={{ textAlign:'left' }}>
              <div style={{ width:'100%', aspectRatio:'1', borderRadius:12, overflow:'hidden', marginBottom:8, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
                {show.coverUrl ? <img src={show.coverUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Tv size={28} style={{ color:'white' }}/>}
              </div>
              <p style={{ color:'white', fontWeight:700, fontSize:13, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{show.title}</p>
              <p style={{ color:S.gray, fontSize:11.5 }}>{show.category} · {show.episodeCount} ep{show.episodeCount===1?'':'s'}</p>
            </div>
          ))}
        </div>
      )}

      <AnimatePresence>
        {openChannelId && (
          <TVChannelProfile channelId={openChannelId} currentUser={currentUser} showToast={showToast} onClose={()=>setOpenChannelId(null)}/>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showChannelModal && (
          <ArtistProfileModal
            showToast={showToast}
            existingProfile={channelProfile || undefined}           
            lockedType="tv_channel"
            onClose={()=>setShowChannelModal(false)}
            onCreated={(profile)=>{ setChannelProfile(profile); setShowChannelModal(false); }}
            onUpdated={(profile)=>{ setChannelProfile(profile); setShowChannelModal(false); }}
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showCreateShow && (
          <CreateShowModal showToast={showToast} onClose={()=>setShowCreateShow(false)}
            onCreated={()=>{ setShowCreateShow(false); loadMyShows(); }}/>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showEpisodeUpload && (
          <EpisodeUploadModal showToast={showToast} shows={myShows} onClose={()=>setShowEpisodeUpload(false)}
            onUploaded={()=>loadMyShows()}/>
        )}
      </AnimatePresence>
    </>
  );
};

// ─── Radio / Podcast — flat post feed, free stream, optional follow ─────
// News articles (text + photos) render as a headline card instead of a
// play/download row — there's no media to play, just a story to read.
const NewsArticleCard = ({ post, onOpenChannel, onOpenArticle }) => {
  const { t } = useLanguage();
  return (
  <button onClick={()=>onOpenArticle(post)} style={{ display:'block', width:'100%', textAlign:'left', background:'none', border:'none', padding:'12px 16px', borderBottom:`1px solid ${S.border}`, cursor:'pointer' }}>
    <div style={{ display:'flex', gap:12 }}>
      <div style={{ width:64, height:64, borderRadius:8, flexShrink:0, overflow:'hidden', background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
        {post.photos?.[0]?.url ? <img src={post.photos[0].url} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : <Newspaper size={22} style={{ color:'white' }}/>}
      </div>
      <div style={{ flex:1, minWidth:0 }}>
        <p style={{ color:'white', fontWeight:700, fontSize:14, overflow:'hidden', display:'-webkit-box', WebkitLineClamp:2, WebkitBoxOrient:'vertical' }}>{post.title}</p>
        <span onClick={(e)=>{ e.stopPropagation(); onOpenChannel(post.channelId); }} style={{ color:S.pink, fontSize:12, fontWeight:600 }}>{post.channelName}</span>
        <p style={{ color:S.gray, fontSize:11, marginTop:2 }}>{fmt(post.viewCount||0)} {t('common.views')}</p>
      </div>
    </div>
  </button>
  );
};

const NewsArticleReader = ({ post, onClose }) => {
  const { t } = useLanguage();
  return (
  <motion.div initial={{ x:'100%' }} animate={{ x:0 }} exit={{ x:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
    style={{ position:'fixed', inset:0, background:S.dark, zIndex:65, display:'flex', flexDirection:'column' }}>
    <div style={{ display:'flex', alignItems:'center', gap:12, padding:16, borderBottom:`1px solid ${S.border}` }}>
      <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><ArrowLeft size={20} style={{ color:'white' }}/></button>
      <p style={{ color:S.pink, fontSize:12.5, fontWeight:700 }}>{post.channelName}</p>
    </div>
    <div style={{ flex:1, overflowY:'auto', padding:'20px 20px 40px' }}>
      <h1 style={{ color:'white', fontWeight:800, fontSize:20, lineHeight:1.35, marginBottom:14 }}>{post.title}</h1>
      {(post.photos||[]).map((photo, i) => (
        <img key={i} src={photo.url} alt="" style={{ width:'100%', borderRadius:12, marginBottom:14, display:'block' }}/>
      ))}
      {post.description && <p style={{ color:S.gray, fontSize:13.5, fontStyle:'italic', marginBottom:14, lineHeight:1.6 }}>{post.description}</p>}
      {post.body && <p style={{ color:'white', fontSize:14.5, lineHeight:1.8, whiteSpace:'pre-wrap' }}>{post.body}</p>}
      <p style={{ color:S.gray, fontSize:11, marginTop:24 }}>{fmt(post.viewCount||0)} {t('common.views')}</p>
    </div>
  </motion.div>
  );
};

const ChannelPostRow = ({ post, downloading, following, onPlay, onDownload, onOpenChannel, onOpenArticle }) => {
  const { t } = useLanguage();
  if (post.postType === 'article') return <NewsArticleCard post={post} onOpenChannel={onOpenChannel} onOpenArticle={onOpenArticle}/>;
  return (
  <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', borderBottom:`1px solid ${S.border}` }}>
    <button onClick={()=>onPlay(post)}
      style={{ position:'relative', width:64, height:44, borderRadius:8, flexShrink:0, border:'none', cursor:'pointer', overflow:'hidden',
        background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
      {post.thumbUrl && <img src={post.thumbUrl} alt="" style={{ position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover' }}/>}
      <Play size={16} fill="white" style={{ color:'white', position:'relative' }}/>
    </button>
    <div style={{ flex:1, minWidth:0 }}>
      <p style={{ color:'white', fontWeight:700, fontSize:14, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{post.title}</p>
      <button onClick={()=>onOpenChannel(post.channelId)} style={{ background:'none', border:'none', padding:0, cursor:'pointer' }}>
        <span style={{ color:S.pink, fontSize:12, fontWeight:600 }}>{post.channelName}</span>
      </button>
      <p style={{ color:S.gray, fontSize:11, marginTop:2 }}>{fmt(post.viewCount||0)} {t('common.views')}</p>
    </div>
    <button onClick={()=>onDownload(post)} disabled={downloading || post.downloaded}
      style={{ flexShrink:0, display:'flex', alignItems:'center', gap:4, background: post.downloaded ? 'transparent' : S.card, border:`1px solid ${S.border}`, borderRadius:999, padding:'8px 12px', cursor: (downloading||post.downloaded) ? 'default' : 'pointer', opacity: downloading?0.6:1 }}>
      <Download size={12} style={{ color: post.downloaded ? S.gray : 'white' }}/>
      <span style={{ color: post.downloaded ? S.gray : 'white', fontSize:12, fontWeight:700 }}>
        {post.downloaded ? t('common.downloaded') : downloading ? '…' : (post.downloadIsFree ? t('common.free') : `${post.downloadPrice||0} ${t('common.coins')}`)}
      </span>
    </button>
  </div>
  );
};

const ChannelProfileSheet = ({ channelId, showToast, currentUser, onClose }) => {
  const { t } = useLanguage();
  const [data, setData] = useState(null);
  const [posts, setPosts] = useState([]);
  const [toggling, setToggling] = useState(false);
  const [openArticle, setOpenArticle] = useState(null);
  const isGuest = currentUser?.isGuest === true;

  useEffect(() => {
    snapFetch(`/snapsa/channel/${channelId}/profile`).then(r=>r.ok?r.json():null).then(d=>setData(d)).catch(()=>{});
    snapFetch(`/snapsa/channel/posts?channelId=${channelId}`).then(r=>r.ok?r.json():null).then(d=>setPosts(d?.posts||[])).catch(()=>{});
  }, [channelId]);

  const toggleFollow = async () => {
    if (isGuest) { showToast?.('Sign in to subscribe', 'info'); window.dispatchEvent(new CustomEvent('snapsa:requestAuth')); return; }
    setToggling(true);
    try {
      const res = await snapFetch(`/snapsa/channel/${channelId}/follow`, { method:'POST' });
      const d = await res.json();
      setData(prev => prev ? { ...prev, following: d.following, channel: { ...prev.channel, followerCount: prev.channel.followerCount + (d.following?1:-1) } } : prev);
    } catch { showToast?.('Could not update', 'error'); }
    setToggling(false);
  };

  if (!data) return null;
  return (
    <motion.div initial={{ x:'100%' }} animate={{ x:0 }} exit={{ x:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
      style={{ position:'fixed', inset:0, background:S.dark, zIndex:60, display:'flex', flexDirection:'column' }}>
      <div style={{ display:'flex', alignItems:'center', gap:12, padding:16, borderBottom:`1px solid ${S.border}` }}>
        <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><ArrowLeft size={20} style={{ color:'white' }}/></button>
        <div style={{ width:40, height:40, borderRadius:'50%', overflow:'hidden', flexShrink:0, background:`linear-gradient(135deg,${S.pink},#7c3aed)`, display:'flex', alignItems:'center', justifyContent:'center' }}>
          {data.channel.avatarUrl ? <img src={data.channel.avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/> : (data.channel.accountType==='podcast' ? <Mic size={16} style={{color:'white'}}/> : data.channel.accountType==='news_channel' ? <Newspaper size={16} style={{color:'white'}}/> : <Radio size={16} style={{color:'white'}}/>)}
        </div>
        <div style={{ minWidth:0, flex:1 }}>
          <p style={{ color:'white', fontWeight:800, fontSize:15, overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{data.channel.channelName}</p>
          <p style={{ color:S.gray, fontSize:11 }}>{fmt(data.channel.followerCount)} {t('common.subscribers')}</p>
        </div>
        <button onClick={toggleFollow} disabled={toggling}
          style={{ flexShrink:0, background: data.following ? S.card : S.pink, border: data.following ? `1px solid ${S.border}` : 'none', borderRadius:999, padding:'9px 16px', cursor:'pointer' }}>
          <span style={{ color:'white', fontWeight:700, fontSize:12.5 }}>{data.following ? t('common.subscribed') : t('common.subscribe')}</span>
        </button>
      </div>
      <div style={{ flex:1, overflowY:'auto' }}>
        {posts.length === 0 ? (
          <p style={{ color:S.gray, fontSize:13, textAlign:'center', padding:32 }}>{t('common.noPostsYet')}</p>
        ) : posts.map(p => (
          <ChannelPostRow key={p.id} post={p} following={data.following}
            onPlay={(post)=>window.dispatchEvent(new CustomEvent('snapsa:playChannelPost', { detail: post }))}
            onDownload={()=>{}} onOpenChannel={()=>{}} onOpenArticle={setOpenArticle}/>
        ))}
      </div>
      <AnimatePresence>
        {openArticle && <NewsArticleReader post={openArticle} onClose={()=>setOpenArticle(null)}/>}
      </AnimatePresence>
    </motion.div>
  );
};

const ChannelPostUploadModal = ({ accountType, onClose, showToast, onUploaded }) => {
  const { t } = useLanguage();
  const [postType, setPostType] = useState('video'); // 'video' | 'article' — article only offered to news_channel
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [body, setBody] = useState('');
  const [mediaFile, setMediaFile] = useState(null);
  const [thumbnail, setThumbnail] = useState(null);
  const [photos, setPhotos] = useState([]); // File[]
  const [downloadIsFree, setDownloadIsFree] = useState(true);
  const [price, setPrice] = useState('1.00');
  const [agreedToRights, setAgreedToRights] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const uploadInFlightRef = useRef(false);
  const label = accountType === 'podcast' ? 'episode' : 'video';
  const isArticle = accountType === 'news_channel' && postType === 'article';

  const canSubmit = title.trim() && agreedToRights && !uploading &&
    (isArticle ? (photos.length > 0 || body.trim()) : !!mediaFile);

  const submit = async () => {
    if (uploadInFlightRef.current) return;
    uploadInFlightRef.current = true;
    setUploading(true);
    setUploadProgress(0);
    try {
      const fd = new FormData();
      fd.append('title', title.trim());
      fd.append('description', description.trim());
      fd.append('copyrightAgreementAccepted', 'true');
      if (isArticle) {
        fd.append('postType', 'article');
        fd.append('body', body.trim());
        photos.forEach(p => fd.append('photos', p));
      } else {
        fd.append('media', mediaFile);
        if (thumbnail) fd.append('thumbnail', thumbnail);
        fd.append('downloadIsFree', downloadIsFree ? 'true' : 'false');
        fd.append('price', price);
      }
      const res = await snapUploadWithProgress(`/snapsa/channel/posts/upload?type=${accountType}`, fd, { onProgress: setUploadProgress });
      if (!res.ok) throw new Error(res.json?.error || 'Upload failed');
      showToast?.(isArticle ? '✅ Article posted!' : `✅ ${label==='episode'?'Episode':'Video'} posted!`, 'success');
      onUploaded?.();
      onClose();
    } catch (err) {
      showToast?.(err.message || 'Upload failed — try again', 'error');
    } finally {
      uploadInFlightRef.current = false;
      setUploading(false);
      setUploadProgress(0);
    }
  };

  return (
    <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
      style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.85)', zIndex:70, display:'flex', alignItems:'flex-end' }}
      onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
        onClick={e=>e.stopPropagation()}
        style={{ width:'100%', background:S.dark, borderTop:`1px solid ${S.border}`, borderRadius:'20px 20px 0 0', padding:20, paddingBottom:'calc(20px + env(safe-area-inset-bottom,0px))', maxHeight:'88vh', overflowY:'auto' }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16 }}>
          <h2 style={{ color:'white', fontWeight:800, fontSize:17 }}>{isArticle ? 'Post Article' : `Post ${label==='episode'?'Episode':'Video'}`}</h2>
          <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={20} style={{ color:S.gray }}/></button>
        </div>

        {accountType === 'news_channel' && (
          <div style={{ display:'flex', gap:8, marginBottom:14 }}>
            {[{ id:'video', label:'Video' }, { id:'article', label:'Article (text + photos)' }].map(opt => (
              <button key={opt.id} type="button" onClick={()=>setPostType(opt.id)}
                style={{ flex:1, padding:'10px 8px', borderRadius:10, border:'none', cursor:'pointer',
                  background: postType===opt.id ? S.pink : S.card, color: postType===opt.id ? 'white' : S.gray, fontWeight:700, fontSize:12.5 }}>
                {opt.label}
              </button>
            ))}
          </div>
        )}

        <input value={title} onChange={e=>setTitle(e.target.value.slice(0,80))} placeholder={isArticle ? t('news.headline') : t('common.title')}
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box' }}/>
        <textarea value={description} onChange={e=>setDescription(e.target.value.slice(0,500))} placeholder={isArticle ? 'Short summary / caption (optional)' : t('common.descriptionOptional')} rows={2}
          style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box', resize:'none' }}/>

        {isArticle ? (
          <>
            <textarea value={body} onChange={e=>setBody(e.target.value.slice(0,5000))} placeholder={t('news.writeStory')} rows={6}
              style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', color:'white', outline:'none', fontSize:14, marginBottom:10, boxSizing:'border-box', resize:'vertical', fontFamily:'inherit' }}/>
            <label style={{ display:'flex', alignItems:'center', gap:10, background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:10, cursor:'pointer' }}>
              <Upload size={16} style={{ color:S.pink }}/>
              <span style={{ color:photos.length?'white':S.gray, fontSize:13 }}>{photos.length ? `${photos.length} photo${photos.length===1?'':'s'} selected` : 'Add photos (optional)'}</span>
              <input type="file" accept="image/*" multiple style={{ display:'none' }} onChange={e=>setPhotos(Array.from(e.target.files||[]).slice(0,10))}/>
            </label>
          </>
        ) : (
          <>
            <label style={{ display:'flex', alignItems:'center', gap:10, background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:10, cursor:'pointer' }}>
              <Upload size={16} style={{ color:S.pink }}/>
              <span style={{ color:mediaFile?'white':S.gray, fontSize:13 }}>{mediaFile ? mediaFile.name : `${accountType==='podcast'?'Audio or video':'Video'} file`}</span>
              <input type="file" accept={accountType==='podcast' ? 'audio/*,video/*' : 'video/*'} style={{ display:'none' }} onChange={e=>setMediaFile(e.target.files?.[0]||null)}/>
            </label>
            <label style={{ display:'flex', alignItems:'center', gap:10, background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:10, cursor:'pointer' }}>
              <Upload size={16} style={{ color:S.pink }}/>
              <span style={{ color:thumbnail?'white':S.gray, fontSize:13 }}>{thumbnail ? thumbnail.name : t('common.thumbnailOptional')}</span>
              <input type="file" accept="image/*" style={{ display:'none' }} onChange={e=>setThumbnail(e.target.files?.[0]||null)}/>
            </label>

            <p style={{ color:S.gray, fontSize:11, marginBottom:10, lineHeight:1.5 }}>Free to stream for everyone. The setting below only affects downloading for offline.</p>

            <button type="button" onClick={()=>setDownloadIsFree(v=>!v)}
              style={{ display:'flex', alignItems:'center', gap:10, width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:10, cursor:'pointer', textAlign:'left' }}>
              <div style={{ width:20, height:20, borderRadius:6, border:`2px solid ${downloadIsFree?S.pink:S.gray}`, background:downloadIsFree?S.pink:'transparent', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
                {downloadIsFree && <Check size={13} style={{ color:'white' }}/>}
              </div>
              <div>
                <p style={{ color:'white', fontSize:13, fontWeight:700, margin:0 }}>{t('common.freeToDownload')}</p>
                <p style={{ color:S.gray, fontSize:11, margin:'2px 0 0' }}>Anyone can save it for offline at no cost</p>
              </div>
            </button>

            {!downloadIsFree && (
              <div style={{ marginBottom:10 }}>
                <label style={{ display:'block', color:S.gray, fontSize:12, fontWeight:600, marginBottom:6 }}>{t('common.downloadPriceCoins')}</label>
                <input value={price} onChange={e=>setPrice(e.target.value.replace(/[^0-9.]/g,''))} inputMode="decimal" placeholder="1.00"
                  style={{ width:'100%', background:S.card, border:`1px solid ${S.border}`, borderRadius:10, padding:'11px 14px', color:'white', outline:'none', fontSize:14, boxSizing:'border-box' }}/>
              </div>
            )}
          </>
        )}

        <label style={{ display:'flex', alignItems:'flex-start', gap:10, background:S.card, border:`1px solid ${agreedToRights?S.pink:S.border}`, borderRadius:10, padding:'12px 14px', marginBottom:16, cursor:'pointer' }}>
          <input type="checkbox" checked={agreedToRights} onChange={e=>setAgreedToRights(e.target.checked)} style={{ marginTop:2 }}/>
          <span style={{ color:S.gray, fontSize:11.5, lineHeight:1.5 }}>{t('common.confirmRights')}</span>
        </label>

        {uploading && (
          <div style={{ marginBottom:12 }}>
            <div style={{ height:6, background:S.card, borderRadius:999, overflow:'hidden' }}>
              <div style={{ height:'100%', width:`${uploadProgress}%`, background:S.pink, transition:'width .2s' }}/>
            </div>
          </div>
        )}

        <button onClick={submit} disabled={!canSubmit}
          style={{ width:'100%', padding:14, borderRadius:12, border:'none', cursor: canSubmit ? 'pointer':'default',
            background: canSubmit ? S.pink : S.border, color:'white', fontWeight:800, fontSize:14 }}>
          {uploading ? `${t('common.uploading')} ${uploadProgress}%` : t('common.publishing')}
        </button>
      </motion.div>
    </motion.div>
  );
};

// Shared browse+manage screen for Radio and Podcasts — same structure, only
// the accountType and a few labels differ.
const ChannelPostsScreen = ({ accountType, currentUser, showToast }) => {
  const { t } = useLanguage();
  const [subTab, setSubTab] = useState('browse'); // 'browse' | 'myPosts'
  const [query, setQuery] = useState('');
  const [posts, setPosts] = useState([]);
  const [myPosts, setMyPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [channelProfile, setChannelProfile] = useState(undefined);
  const [showChannelModal, setShowChannelModal] = useState(false);
  const [showUpload, setShowUpload] = useState(false);
  const [openChannelId, setOpenChannelId] = useState(null);
  const [downloadingId, setDownloadingId] = useState(null);
  const [mediaPlayer, setMediaPlayer] = useState(null); // { url, title, artist, mediaType }
  const [openArticle, setOpenArticle] = useState(null);
  const debounceRef = useRef(null);
  const isGuest = currentUser?.isGuest === true;
  const isOwner = channelProfile?.enabled && channelProfile?.accountType === accountType;
  const label = accountType === 'podcast' ? 'Podcast' : accountType === 'news_channel' ? 'News Channel' : 'Radio Station';
  const EmptyIcon = accountType === 'podcast' ? Mic : accountType === 'news_channel' ? Newspaper : Radio;

  useEffect(() => {
    if (isGuest) { setChannelProfile(null); return; }
snapFetch(`/snapsa/music/artist-profile/mine?type=${accountType}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => setChannelProfile(d?.artistProfile || null))
      .catch(() => setChannelProfile(null));
  }, [isGuest, accountType]);

  const loadBrowse = (q = '') => {
    setLoading(true);
    const params = new URLSearchParams({ accountType });
    if (q) params.set('search', q);
    snapFetch(`/snapsa/channel/posts?${params.toString()}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => setPosts(d?.posts || []))
      .catch(() => setPosts([]))
      .finally(() => setLoading(false));
  };

  const loadMyPosts = () => {
    setLoading(true);
    snapFetch('/snapsa/channel/mine/posts')
      .then(r => r.ok ? r.json() : null)
      .then(d => setMyPosts(d?.posts || []))
      .catch(() => setMyPosts([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    if (subTab === 'browse') loadBrowse(query);
    else loadMyPosts();
  }, [subTab]);

  const handleSearchChange = (val) => {
    setQuery(val);
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => loadBrowse(val), 350);
  };

  const handlePlay = (post) => {
    if (!post.mediaFile) { showToast?.('Media unavailable', 'error'); return; }
    snapFetch(`/snapsa/channel/posts/${post.id}/view`, { method:'POST' }).catch(()=>{});
    setMediaPlayer({ url: post.mediaFile, title: post.title, artist: post.channelName, mediaType: post.mediaType });
  };

  const pollDownloadStatus = (txRef, post, attemptsLeft = 10) => {
    snapFetch(`/snapsa/channel/posts/download/status/${txRef}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (d?.status === 'completed') {
          setDownloadingId(null);
          setPosts(prev => prev.map(p => p.id===post.id ? { ...p, downloaded:true } : p));
          triggerBrowserDownload(d.downloadUrl, `${post.title}.${post.mediaType==='audio'?'mp3':'mp4'}`);
          showToast?.('⬇️ Downloading…', 'success');
          return;
        }
        if (attemptsLeft > 0) setTimeout(() => pollDownloadStatus(txRef, post, attemptsLeft - 1), 1500);
        else { setDownloadingId(null); showToast?.('Payment still processing — check back shortly', 'info'); }
      })
      .catch(() => setDownloadingId(null));
  };

  const handleDownload = async (post) => {
    if (isGuest) { showToast?.('Sign in to download', 'info'); window.dispatchEvent(new CustomEvent('snapsa:requestAuth')); return; }
    if (post.downloadIsFree) { triggerBrowserDownload(post.mediaFile, `${post.title}.${post.mediaType==='audio'?'mp3':'mp4'}`); return; }
    setDownloadingId(post.id);
    try {
      const res = await snapFetch(`/snapsa/channel/posts/${post.id}/download/init`, { method:'POST' });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || 'Could not start download');
      pollDownloadStatus(d.transactionRef, post);
    } catch (err) {
      showToast?.(err.message || 'Could not start download', 'error');
      setDownloadingId(null);
    }
  };

  return (
    <>
      <div style={{ display:'flex', gap:8, padding:'4px 16px 12px' }}>
        {['browse','myPosts'].map(tabId => (
          <button key={tabId} onClick={()=>setSubTab(tabId)}
            style={{ flex:1, padding:'9px 0', borderRadius:999, border:'none', cursor:'pointer',
              background: subTab===tabId ? S.pink : S.card, color: subTab===tabId ? 'white' : S.gray, fontWeight:700, fontSize:13 }}>
            {tabId==='browse' ? t('tv.browse') : t('tv.myChannel')}
          </button>
        ))}
      </div>

      {subTab==='browse' && (
        <div style={{ padding:'0 16px 12px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:10, background:S.card, borderRadius:12, padding:'11px 14px', border:`1px solid ${S.border}` }}>
            <Search size={17} style={{ color:S.gray }}/>
            <input value={query} onChange={e=>handleSearchChange(e.target.value)} placeholder={`${t('common.search')} ${label.toLowerCase()}s…`}
              style={{ flex:1, background:'transparent', border:'none', outline:'none', color:'white', fontSize:14 }}/>
            {query && <button onClick={()=>handleSearchChange('')} style={{ background:'none', border:'none', cursor:'pointer' }}><X size={15} style={{ color:S.gray }}/></button>}
          </div>
        </div>
      )}

      {subTab==='myPosts' && (
        <div style={{ padding:'0 16px 12px', display:'flex', gap:8 }}>
          {channelProfile?.status === 'pending' || channelProfile?.status === 'rejected' ? (
            <CreatorStatusCard profile={channelProfile} onEdit={()=>setShowChannelModal(true)}/>
          ) : !isOwner ? (
            <button onClick={()=>setShowChannelModal(true)}
              style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', gap:8, padding:'12px 0', borderRadius:10, border:'none', cursor:'pointer', background:S.pink }}>
              {accountType==='podcast' ? <Mic size={15} style={{ color:'white' }}/> : accountType==='news_channel' ? <Newspaper size={15} style={{ color:'white' }}/> : <Radio size={15} style={{ color:'white' }}/>}
              <span style={{ color:'white', fontWeight:700, fontSize:13 }}>{accountType==='podcast' ? t('podcast.setUp') : accountType==='news_channel' ? t('news.setUp') : t('radio.setUp')}</span>
            </button>
          ) : (
            <button onClick={()=>setShowUpload(true)}
              style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', gap:8, padding:'12px 0', borderRadius:10, border:'none', cursor:'pointer', background:S.pink }}>
              <Upload size={15} style={{ color:'white' }}/>
              <span style={{ color:'white', fontWeight:700, fontSize:13 }}>{accountType==='podcast' ? t('podcast.postEpisode') : accountType==='news_channel' ? t('news.newPost') : t('radio.postVideo')}</span>
            </button>
          )}
        </div>
      )}

      {loading && (
        <div style={{ display:'flex', alignItems:'center', justifyContent:'center', padding:'40px 0' }}>
          <div style={{ width:36, height:36, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>
          <style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style>
        </div>
      )}

      {!loading && subTab==='browse' && posts.length === 0 && (
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, padding:32 }}>
          <EmptyIcon size={40} style={{ color:S.gray, opacity:0.5 }}/>
          <p style={{ color:S.gray, fontSize:13, textAlign:'center' }}>{query ? `${t('music.noneMatch')} "${query}"` : (accountType==='podcast' ? t('podcast.noneYet') : accountType==='news_channel' ? t('news.noneYet') : t('radio.noneYet'))}</p>
        </div>
      )}

      {!loading && subTab==='browse' && posts.map(post => (
        <ChannelPostRow key={post.id} post={post} downloading={downloadingId===post.id}
          onPlay={handlePlay} onDownload={handleDownload} onOpenChannel={setOpenChannelId} onOpenArticle={setOpenArticle}/>
      ))}

      {!loading && subTab==='myPosts' && isOwner && myPosts.length === 0 && (
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:12, padding:32 }}>
          <EmptyIcon size={40} style={{ color:S.gray, opacity:0.5 }}/>
          <p style={{ color:S.gray, fontSize:13, textAlign:'center' }}>{t('common.nothingPostedYet')}</p>
        </div>
      )}

      {!loading && subTab==='myPosts' && isOwner && myPosts.map(post => (
        <ChannelPostRow key={post.id} post={post} downloading={false}
          onPlay={handlePlay} onDownload={()=>{}} onOpenChannel={()=>{}} onOpenArticle={setOpenArticle}/>
      ))}

      <AnimatePresence>
        {openChannelId && <ChannelProfileSheet channelId={openChannelId} showToast={showToast} currentUser={currentUser} onClose={()=>setOpenChannelId(null)}/>}
      </AnimatePresence>

      <AnimatePresence>
        {showChannelModal && (
          <ArtistProfileModal
            showToast={showToast}
            existingProfile={channelProfile || undefined}         
            lockedType={accountType}
            onClose={()=>setShowChannelModal(false)}
            onCreated={(profile)=>{ setChannelProfile(profile); setShowChannelModal(false); }}
            onUpdated={(profile)=>{ setChannelProfile(profile); setShowChannelModal(false); }}
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showUpload && (
          <ChannelPostUploadModal accountType={accountType} showToast={showToast} onClose={()=>setShowUpload(false)}
            onUploaded={()=>loadMyPosts()}/>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {mediaPlayer && (
          <SnapsaMusicPlayer label={accountType === 'podcast' ? 'SNAPSA PODCASTS' : accountType === 'news_channel' ? 'SNAPSA NEWS' : 'SNAPSA RADIO'} track={{ title: mediaPlayer.title, artist: mediaPlayer.artist }} videoUrl={mediaPlayer.url} audioOnly={mediaPlayer.mediaType === 'audio'} showToast={showToast} onClose={()=>setMediaPlayer(null)}/>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {openArticle && <NewsArticleReader post={openArticle} onClose={()=>setOpenArticle(null)}/>}
      </AnimatePresence>
    </>
  );
};

// ─── Lives Screen ─────────────────────────────────────────────────────
const LivesScreen = ({ isActive = true }) => {
  const [liveRooms, setLiveRooms] = useState([]);
  const [watching,  setWatching]  = useState(null);
  const [loading,   setLoading]   = useState(true);
  useEffect(() => {
    snapFetch('/snapsa/live/rooms').then(r=>r.ok?r.json():null).then(d=>{
      if(d?.rooms?.length) setLiveRooms(d.rooms.map(r=>({ id:r.id||r._id, name:r.hostName, viewers:String(r.viewers||0), title:r.title, c:['#134e4a','#4c1d95'] })));
      setLoading(false);
    }).catch(()=>setLoading(false));
  },[]);
 
  useEffect(() => { if (!isActive) setWatching(null); }, [isActive]);
  return (
    <div style={{ flex:1, overflowY:'auto', background:'transparent', position:'relative', zIndex:1 }}>
      <div style={{ padding:'16px 16px 8px' }}><h2 style={{ color:'white', fontWeight:900, fontSize:20 }}>🔴 Live Now</h2></div>
      {loading ? <div style={{ display:'flex', justifyContent:'center', padding:40 }}><div style={{ width:32, height:32, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/><style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style></div>
      : liveRooms.length===0 ? <p style={{ color:S.gray, textAlign:'center', padding:40 }}>No live streams at the moment</p>
      : (
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12, padding:'8px 16px 80px' }}>
          {liveRooms.map(l => (
            <button key={l.id} onClick={()=>setWatching(l)} style={{ borderRadius:16, overflow:'hidden', position:'relative', height:200, background:`linear-gradient(135deg,${l.c[0]},${l.c[1]})`, border:'none', cursor:'pointer' }}>
              <div style={{ position:'absolute', inset:0, background:'linear-gradient(to top,rgba(0,0,0,.7) 40%,transparent)' }}/>
              <div style={{ position:'absolute', top:10, left:10, background:S.pink, color:'white', fontSize:9, fontWeight:900, padding:'3px 8px', borderRadius:4 }}>● LIVE</div>
              <div style={{ position:'absolute', top:'42%', left:'50%', transform:'translate(-50%,-50%)', width:48, height:48, borderRadius:'50%', background:'rgba(255,255,255,.15)', border:`2px solid ${S.pink}`, display:'flex', alignItems:'center', justifyContent:'center', fontWeight:900, color:'white', fontSize:19 }}>{l.name?.[0]?.toUpperCase()}</div>
              <div style={{ position:'absolute', bottom:10, left:10, right:10, textAlign:'left' }}>
                <p style={{ color:'white', fontWeight:700, fontSize:13 }}>@{l.name}</p>
                <p style={{ color:'rgba(255,255,255,.65)', fontSize:11, marginTop:2 }}>{l.title}</p>
              </div>
            </button>
          ))}
        </div>
      )}
      <AnimatePresence>
        {watching && (
          <motion.div key="lw" initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }} style={{ position:'absolute', inset:0, zIndex:50 }}>
            <LiveWatchScreen live={watching} onClose={()=>setWatching(null)}/>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

// ─── User Profile Screen ──────────────────────────────────────────────
const UserProfileScreen = ({ profileUser, onBack, onDM, showToast, currentUser }) => {
  const [following, setFollowing] = useState(profileUser.isFollowing||false);   const [followState, setFollowState] = useState({ requested:false, locked:false });
  const [userData,  setUserData]  = useState(profileUser);
  const [loading,   setLoading]   = useState(!profileUser.followerCount&&!profileUser.followersCount);
  const [avatarFull, setAvatarFull] = useState(false);
  const [videosCursor, setVideosCursor] = useState(null);
  const [loadingMoreVideos, setLoadingMoreVideos] = useState(false);
  const { t: tr } = useLanguage();
  const [safety, setSafety] = useState({ blockedByMe:false, hiddenByMe:false, blockedByThem:false });
  const [showSafety, setShowSafety] = useState(false);
  const [showOtherShirt, setShowOtherShirt] = useState(false);
  const [reportOpen, setReportOpen] = useState(false);
  const scrollRef = useRef(null);
  useEffect(() => {
    const uid = profileUser?.id || profileUser?._id || profileUser?.authorId;
    if (!uid) { setLoading(false); return; }
    snapFetch(`/snapsa/users/${uid}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (d) {
          setUserData({
            ...d.user,
            id: d.user._id || d.user.id,
            videos: d.videos || [],
            authorName: d.user.username || d.user.displayName || profileUser.authorName,
            avatarUrl: mediaHref(d.user.avatarUrl),
          });
          setFollowing(d.isFollowing || false);           setFollowState({ requested: !!d.followRequested, locked: !!d.privateLocked });
          setVideosCursor(d.nextCursor || null);
          setSafety({ blockedByMe: !!d.blockedByMe, hiddenByMe: !!d.hiddenByMe, blockedByThem: !!d.blockedByThem });
        }
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [profileUser?.id, profileUser?._id, profileUser?.authorId]);

  const loadMoreVideos = () => {
    const uid = userData?.id || userData?._id;
    if (!uid || !videosCursor || loadingMoreVideos) return;
    setLoadingMoreVideos(true);
    snapFetch(`/snapsa/users/${uid}/videos?before=${encodeURIComponent(videosCursor)}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => {
        if (d?.videos) {
          setUserData(prev => ({ ...prev, videos: [...(prev.videos||[]), ...d.videos] }));
          setVideosCursor(d.nextCursor || null);
        }
      })
      .catch(() => {})
      .finally(() => setLoadingMoreVideos(false));
  };

  const handleScroll = () => {
    const el = scrollRef.current;
    if (!el) return;
    if (el.scrollHeight - el.scrollTop - el.clientHeight < 400) loadMoreVideos();
  };

  const handleFollow = async () => {
    if (currentUser?.isGuest) { showToast?.('Sign in to follow creators', 'info'); window.dispatchEvent(new CustomEvent('snapsa:requestAuth')); return; }
        const wasFollowing = following;
    const wasRequested = followState.requested;
    try {
      const res = await snapFetch(`/snapsa/users/${userData.id||userData._id}/follow`, { method: (wasFollowing || wasRequested) ? 'DELETE' : 'POST' });
      if (res.ok) {
        const d = await res.json();
        if (d.requested) {
          setFollowState(s => ({ ...s, requested: true }));
          showToast?.('Follow request sent', 'success');
          return;
        }
        if (wasRequested) {
          setFollowState(s => ({ ...s, requested: false }));
          showToast?.('Follow request cancelled', 'success');
          return;
        }
        setFollowing(!wasFollowing);
        if (wasFollowing && d.private) {
          setFollowState(s => ({ ...s, locked: true }));
          setUserData(prev => ({ ...prev, videos: [] }));
        }
        
        setUserData(prev => ({
          ...prev,
          followerCount: typeof d.followerCount === 'number'
            ? d.followerCount
            : (prev.followerCount || 0) + (wasFollowing ? -1 : 1),
        }));
        showToast?.(wasFollowing ? 'Unfollowed' : '✅ Following!', 'success');
        window.dispatchEvent(new CustomEvent('snapsa:followChanged'));
      } else if (res.status === 409) {
       
        setFollowing(true);
        showToast?.('Already following', 'info');
      } else {
        showToast?.('Could not update follow — try again', 'error');
      }
    } catch {
      showToast?.('Could not update follow — you appear offline', 'error');
    }
  };
  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100%', background:S.dark, position:'relative', zIndex:1 }}>
      <AnimatePresence>
        {avatarFull && userData.avatarUrl && (
          <motion.div
            initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
            style={{ position:'fixed', inset:0, zIndex:600, background:'rgba(0,0,0,.92)', display:'flex', alignItems:'center', justifyContent:'center' }}
            onClick={() => setAvatarFull(false)}
          >
            <motion.img
              initial={{ scale:.7 }} animate={{ scale:1 }} exit={{ scale:.7 }}
              transition={{ type:'spring', damping:20, stiffness:250 }}
              src={userData.avatarUrl} alt=""
              style={{ width:280, height:280, borderRadius:'50%', border:`4px solid ${S.yellow}`, objectFit:'cover' }}
              onClick={e => e.stopPropagation()}
            />
          </motion.div>
        )}
      </AnimatePresence>
      <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', borderBottom:`1px solid ${S.border}`, background:S.dark, position:'relative', zIndex:2 }}>
        <button onClick={onBack} style={{ background:'none', border:'none', cursor:'pointer' }}><ArrowLeft size={20} style={{ color:'white' }}/></button>
        <h2 style={{ fontWeight:700, color:'white', fontSize:16, flex:1 }}>@{userData.username||userData.authorName}</h2>
        {(userData.id||userData._id) && String(userData.id||userData._id) !== String(currentUser?._id||currentUser?.id) && (
          <button onClick={()=>setShowSafety(true)} style={{ background:'none', border:'none', cursor:'pointer', padding:4 }}>
            <MoreHorizontal size={20} style={{ color:'white' }}/>
          </button>
        )}
      </div>
      {showSafety && (
        <SafetySheet title={`@${userData.username||userData.authorName}`} onClose={()=>setShowSafety(false)}
          actions={makeUserSafetyActions({
            t: tr, userId: userData.id||userData._id, username: userData.username||userData.authorName,
            state: safety, setState: setSafety, showToast, close: ()=>setShowSafety(false),
            extra: [{ icon: Flag, label: tr('moderation.reportUser'), onClick: ()=>{ setShowSafety(false); setReportOpen(true); } }],
          })}/>
      )}
      {reportOpen && <ReportModal targetType="user" targetId={userData.id||userData._id} onClose={()=>setReportOpen(false)} showToast={showToast}/>}
      {loading ? <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center' }}><div style={{ width:32, height:32, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/><style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style></div>
      : (
        <div ref={scrollRef} onScroll={handleScroll} style={{ flex:1, overflowY:'auto' }}>
          <div style={{ padding:'20px 16px 0' }}>
            <div style={{ display:'flex', alignItems:'center', gap:16, marginBottom:16 }}>
              <div style={{ position:'relative', flexShrink:0 }}>
              <button
                onClick={() => userData.avatarUrl && setAvatarFull(true)}
                style={{ width:72, height:72, borderRadius:'50%', background:S.pink, border:`3px solid ${S.yellow}`, display:'flex', alignItems:'center', justifyContent:'center', fontWeight:900, fontSize:26, color:'white', flexShrink:0, overflow:'hidden', padding:0, cursor: userData.avatarUrl ? 'pointer' : 'default' }}
              >
                {userData.avatarUrl
                  ? <img src={userData.avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover' }}/>
                  : (userData.username||userData.authorName||'S')[0].toUpperCase()}
              </button>
              {userData.crew && <ShirtFlipButton onClick={() => setShowOtherShirt(true)} />}
              </div>
              <div>
                {userData.displayName && <p style={{ fontWeight:800, fontSize:16, color:'white', margin:'0 0 2px', wordBreak:'break-word' }}>{userData.displayName}</p>}
                <div style={{ display:'flex', alignItems:'center', gap:6 }}>
                  <h2 style={{ fontWeight:900, fontSize:18, color:S.pink }}>@{userData.username||userData.authorName}</h2>
                  <AuthorBadges wernTier={userData.tier} snapsaTier={userData.snapsaTier} crew={userData.crew} />
                </div>
                {(userData.official || userData.officialLabel) && <div style={{ margin:'4px 0' }}><OfficialPill label={userData.official || userData.officialLabel} /></div>}
                {userData.bio && <p style={{ color:S.gray, fontSize:13, marginTop:4, whiteSpace:'pre-wrap' }}>{renderRich(userData.bio)}</p>}
                <WorkLine work={userData.work} crew={userData.crew} />
                {showOtherShirt && <CrewShirtModal firstName={(userData.displayName || userData.username || '').split(' ')[0]} position={userData.crew} snapFetch={snapFetch} onClose={() => setShowOtherShirt(false)} />}
                {userData.countryCode && <div style={{ marginTop:6 }}><CountryTag code={userData.countryCode} name={userData.countryName}/></div>}
                <div style={{ display:'flex', gap:10, marginTop:12 }}>
                  <button onClick={handleFollow} style={{ padding:'8px 20px', borderRadius:999, fontWeight:700, fontSize:13, cursor:'pointer', background:(following||followState.requested)?'transparent':S.yellow, color:(following||followState.requested)?S.gray:'#000', border:(following||followState.requested)?`1.5px solid ${S.border}`:'none' }}>{following ? 'Following' : (followState.requested ? 'Requested' : '+ Follow')}</button>
                  <button onClick={() => {
                    // Ensure the user object has a reliable id field
                    const dmUser = {
                      ...userData,
                      id: userData.id || userData._id,
                      _id: userData._id || userData.id,
                    };
                    onDM(dmUser);
                  }} style={{ padding:'8px 20px', borderRadius:999, fontWeight:700, fontSize:13, background:'transparent', border:`1.5px solid ${S.border}`, color:S.gray, cursor:'pointer' }}>
                    Message
                  </button>
                </div>
              </div>
            </div>
            <div style={{ display:'flex', borderTop:`1px solid ${S.border}`, borderBottom:`1px solid ${S.border}`, padding:'12px 0', marginBottom:16 }}>
              {[{label:'Following',value:userData.followingHidden ? 'Hidden' : fmt(userData.followingCount||0)},{label:'Followers',value:fmt(userData.followerCount||0)},{label:'Likes',value:fmt(typeof userData.totalLikes === 'number' ? userData.totalLikes : (userData.videos||[]).reduce((a,v)=>a+(v.likes||0),0))}].map(({label,value})=>(
                <div key={label} style={{ flex:1, textAlign:'center' }}>
                  <p style={{ fontWeight:900, fontSize:17, color:'white' }}>{value}</p>
                  <p style={{ fontSize:11, color:S.gray }}>{label}</p>
                </div>
              ))}
            </div>
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(4, minmax(0, 1fr))', gap:2, background:S.border, padding:'0 2px' }}>
            {followState.locked ? <p style={{ color:S.gray, textAlign:'center', padding:40, gridColumn:'1/-1' }}>🔒 This account is private. Follow to see their videos.</p>             : (userData.videos||[]).length===0 ? <p style={{ color:S.gray, textAlign:'center', padding:40, gridColumn:'1/-1' }}>No videos yet</p>
            : (userData.videos||[]).map(v=>(
              <button
                key={v.id||v._id}
                onClick={() => window.dispatchEvent(new CustomEvent('snapsa:playVideo', { detail: { video: {
                  id: v.id||v._id,
                  authorId: userData.id||userData._id,
                  authorName: userData.username||userData.authorName,
                  authorTier: userData.tier||'',
                  authorSnapsaTier: userData.snapsaTier||'',
                  crew: userData.crew||'',
                  official: userData.official||userData.officialLabel||'',
                  caption: v.caption||'',
                  likes: v.likes||0,
                  comments: v.comments||0,
                  shares: v.shares||0,
                  videoUrl: mediaHref(v.videoUrl || v.videoFile),
                  thumbUrl: mediaHref(v.thumbUrl),
                  c: v.c||['#1a1a4e','#4c1d95','#be185d'],
                } } }))}
                style={{ position:'relative', width:'100%', aspectRatio:'9/16', maxHeight:220, overflow:'hidden', background:'#111', border:'none', cursor:'pointer', padding:0 }}
              >
                {mediaHref(v.thumbUrl) ? (
                  <img src={mediaHref(v.thumbUrl)} style={{ width:'100%', height:'100%', objectFit:'cover' }} alt="" onError={e=>e.target.style.display='none'}/>
                ) : (
                  <div style={{ width:'100%', height:'100%', display:'flex', alignItems:'center', justifyContent:'center', background:`linear-gradient(135deg,${S.dark},${S.pink}33)` }}>
                    <Play size={20} style={{ color:'rgba(255,255,255,0.3)' }}/>
                  </div>
                )}
                <div style={{ position:'absolute', inset:0, background:'rgba(0,0,0,0.15)', display:'flex', alignItems:'center', justifyContent:'center' }}>
                  <Play size={22} fill="white" style={{ color:'white', opacity:0.85 }}/>
                </div>
                <div style={{ position:'absolute', bottom:6, left:8, display:'flex', alignItems:'center', gap:3 }}>
                  <Heart size={10} style={{ color:'white' }} fill="white"/><span style={{ color:'white', fontSize:10, fontWeight:600 }}>{fmt(v.likes)}</span>
                </div>
              </button>
            ))}
          </div>
          {loadingMoreVideos && (
            <div style={{ display:'flex', justifyContent:'center', padding:16 }}>
              <div style={{ width:24, height:24, borderRadius:'50%', border:`3px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const ShareSnapsaModal = ({ onClose, snapsaUsername, name, avatarUrl }) => {
  const shareUrl = `${window.location.origin}${window.location.pathname}${snapsaUsername ? `?snapsa_ref=${snapsaUsername}` : ''}`;
  // Dark modules on white — the old white-on-dark QR is "inverted" and many scanner apps can't read it.
  const qrSrc = `https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=0&bgcolor=FFFFFF&color=0B0B14&data=${encodeURIComponent(shareUrl)}`;
  const shownName = (name && name !== `@${snapsaUsername}`) ? name : (snapsaUsername ? `@${snapsaUsername}` : '');
  const initial = (shownName.replace(/^@/, '')[0] || 'S').toUpperCase();
  const copyLink = () => { navigator.clipboard?.writeText(shareUrl).catch(()=>{}); };

  const saveCard = async () => {
    try {
      const loadImg = (src) => new Promise((res, rej) => {
        const img = new Image(); img.crossOrigin = 'anonymous';
        img.onload = () => res(img); img.onerror = rej; img.src = src;
      });
      const drawCover = (ctx, img, x, y, w, h) => {
        const scale = Math.max(w / img.width, h / img.height);
        const dw = img.width * scale, dh = img.height * scale;
        ctx.drawImage(img, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
      };
      const canvas = document.createElement('canvas');
      canvas.width = 480; canvas.height = 680;
      const ctx = canvas.getContext('2d');

      const grad = ctx.createLinearGradient(0, 0, 480, 680);
      grad.addColorStop(0, '#1a0533'); grad.addColorStop(1, '#0B0B14');
      ctx.fillStyle = grad; ctx.fillRect(0, 0, 480, 680);
      const radial = ctx.createRadialGradient(240, 150, 0, 240, 150, 300);
      radial.addColorStop(0, 'rgba(255,32,85,0.25)'); radial.addColorStop(1, 'transparent');
      ctx.fillStyle = radial; ctx.fillRect(0, 0, 480, 680);

      // Header: logo + "Snapsa", top-left like the on-screen card
      try {
        const logo = await loadImg('/SnapsaLogo.png');
        ctx.save(); ctx.beginPath(); ctx.arc(56, 56, 26, 0, Math.PI * 2); ctx.clip();
        ctx.drawImage(logo, 30, 30, 52, 52); ctx.restore();
      } catch {}
      ctx.fillStyle = '#FF2055'; ctx.font = 'bold 34px system-ui'; ctx.textAlign = 'left';
      ctx.fillText('Snapsa', 92, 68);

      // Profile photo in a white ring
      ctx.beginPath(); ctx.arc(240, 172, 58, 0, Math.PI * 2); ctx.fillStyle = 'white'; ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.arc(240, 172, 52, 0, Math.PI * 2); ctx.clip();
      let drewAvatar = false;
      if (avatarUrl) {
        try { drawCover(ctx, await loadImg(avatarUrl), 188, 120, 104, 104); drewAvatar = true; } catch {}
      }
      if (!drewAvatar) {
        ctx.fillStyle = '#FF2055'; ctx.fillRect(188, 120, 104, 104);
        ctx.fillStyle = 'white'; ctx.font = 'bold 46px system-ui'; ctx.textAlign = 'center';
        ctx.fillText(initial, 240, 189);
      }
      ctx.restore();

      // Name (shrinks to fit)
      ctx.textAlign = 'center'; ctx.fillStyle = 'white';
      let fs = 26; ctx.font = `bold ${fs}px system-ui`;
      while (ctx.measureText(shownName).width > 420 && fs > 14) { fs -= 1; ctx.font = `bold ${fs}px system-ui`; }
      ctx.fillText(shownName, 240, 272);

      // QR code on white
      const qrImg = await loadImg(qrSrc);
      ctx.fillStyle = 'white';
      ctx.beginPath(); ctx.roundRect(100, 296, 280, 280, 16); ctx.fill();
      ctx.drawImage(qrImg, 116, 312, 248, 248);

      // Link + @username
      ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.font = '13px monospace';
      ctx.fillText(shareUrl.slice(0, 52), 240, 614);
      if (snapsaUsername && shownName !== `@${snapsaUsername}`) {
        ctx.fillStyle = '#FF2055'; ctx.font = 'bold 20px system-ui';
        ctx.fillText(`@${snapsaUsername}`, 240, 650);
      }

      canvas.toBlob(blob => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `snapsa_invite_${snapsaUsername || 'share'}.png`;
        a.click();
        URL.revokeObjectURL(url);
      }, 'image/png');
    } catch (e) {
      console.error('[saveCard]', e);
    }
  };

  // Portalled to <body> with a high z-index so nothing from the app (like the
  // bottom-bar "+" button) can show through the sheet.
  return createPortal(
    <div style={{ position:'fixed', inset:0, zIndex:9000, display:'flex', alignItems:'flex-end', justifyContent:'center', background:'rgba(0,0,0,.7)' }} onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }}
        style={{ width:'100%', maxWidth:420, maxHeight:'100vh', overflowY:'auto', background:S.card, borderTopLeftRadius:24, borderTopRightRadius:24, padding:'24px 24px calc(28px + env(safe-area-inset-bottom,0px))', textAlign:'center' }}
        onClick={e=>e.stopPropagation()}>
        <div style={{ width:40, height:4, borderRadius:999, background:S.border, margin:'0 auto 20px' }}/>
        <SnapsaLogo size={34}/>
        <div style={{ width:84, height:84, borderRadius:'50%', border:'4px solid white', margin:'18px auto 10px', overflow:'hidden', background:S.pink, display:'flex', alignItems:'center', justifyContent:'center', boxSizing:'border-box' }}>
          {avatarUrl
            ? <img src={avatarUrl} alt="" style={{ width:'100%', height:'100%', objectFit:'cover', display:'block' }}/>
            : <span style={{ color:'white', fontWeight:900, fontSize:32 }}>{initial}</span>}
        </div>
        <p style={{ color:'white', fontWeight:800, fontSize:18, margin:'0 0 16px', wordBreak:'break-word' }}>{shownName}</p>
        <div style={{ background:'white', borderRadius:16, padding:16, display:'inline-block', marginBottom:20 }}>
          <img src={qrSrc} alt="Snapsa QR Code" width={200} height={200} style={{ display:'block' }}/>
        </div>
              <div style={{ height:4 }}/> 
        <button onClick={saveCard} style={{ width:'100%', padding:'13px 0', borderRadius:12, background:`linear-gradient(90deg,#7C3AED,${S.pink})`, color:'white', fontWeight:700, fontSize:14, border:'none', cursor:'pointer', marginBottom:10, display:'flex', alignItems:'center', justifyContent:'center', gap:8 }}>
          <Download size={16}/> Save Card to Device
        </button>
        <button onClick={copyLink} style={{ width:'100%', padding:'13px 0', borderRadius:12, background:S.pink, color:'white', fontWeight:700, fontSize:14, border:'none', cursor:'pointer', marginBottom:10 }}>Copy Link</button>
        <button onClick={onClose} style={{ width:'100%', padding:'13px 0', borderRadius:12, background:S.border, color:S.gray, fontWeight:600, fontSize:14, border:'none', cursor:'pointer' }}>Close</button>
      </motion.div>
    </div>,
    document.body
  );
};

