const AboutSnapsaScreen = ({ onClose, onOpenTerms }) => {
  const { t } = useLanguage();
  return (
  <div style={{ display:'flex', flexDirection:'column', height:'100%', background:'transparent', position:'relative', zIndex:1 }}>
    <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', borderBottom:`1px solid ${S.border}` }}>
      <button onClick={onClose} style={{ background:'none', border:'none', cursor:'pointer' }}><ArrowLeft size={20} style={{ color:'white' }}/></button>
      <h2 style={{ color:'white', fontWeight:700 }}>{t('about.title')}</h2>
    </div>
    <div style={{ flex:1, overflowY:'auto', padding:'32px 24px', textAlign:'center' }}>
      <img src="/SnapsaHub.png" alt="" style={{ width:'72%', maxWidth:260, height:'auto', display:'block', margin:'0 auto 22px' }}
        onError={e => { e.target.onerror = null; e.target.src = '/SnapsaLogo.png'; }} />
      <div style={{ color:'#d8d4e6', fontSize:13.5, lineHeight:1.7, maxWidth:360, margin:'0 auto 24px', textAlign:'left' }}>
        <p style={{ marginBottom:12 }}>Snapsa is a digital technology app where people create, share and discover short videos, music and live broadcasts, message each other, and manage money, all in one place.</p>
        <p style={{ marginBottom:6, color:'white', fontWeight:700 }}>What Snapsa offers</p>
        <ul style={{ paddingLeft:18, margin:'0 0 12px', listStyle:'disc' }}>
          <li style={{ marginBottom:5 }}>Short-form video with editing tools, music and effects</li>
          <li style={{ marginBottom:5 }}>Live streaming with real-time comments and gifts</li>
          <li style={{ marginBottom:5 }}>Stories and private messaging, including sending while offline</li>
          <li style={{ marginBottom:5 }}>Offline videos, so you can keep watching without a connection</li>
          <li style={{ marginBottom:5 }}>Snapsa Wallet: a card and account for approved users, with PIN or device-biometric protection</li>
          <li style={{ marginBottom:5 }}>Gifts, shops and tools that let creators grow an audience and earn</li>
          <li style={{ marginBottom:5 }}>Snapsa Verified for professionals and well-known public figures</li>
        </ul>
        <p style={{ marginBottom:6, color:'white', fontWeight:700 }}>Privacy and identity</p>
        <p style={{ marginBottom:12 }}>Snapsa uses zero-knowledge proofs (ZKPs) to create your digital identity, so your account does not have to be tied to your personal phone number or email. Some details, such as usernames, are not encrypted so the app stays easy to use and people can be found.</p>
        <p style={{ marginBottom:6, color:'white', fontWeight:700 }}>Who makes Snapsa</p>
        <p>Snapsa was designed and developed by Frans Van Der Werndtz, known as DCE-07 in the cybersecurity world. It is a product of Snapsa Technologies, a company registered in Botswana.</p>
      </div>

      <div style={{ textAlign:'left', background:S.card, border:`1px solid ${S.border}`, borderRadius:14, padding:18, marginBottom:16 }}>
        <p style={{ color:S.gray, fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:1, marginBottom:6 }}>{t('about.developer')}</p>
        <p style={{ color:'white', fontSize:15, fontWeight:700 }}>Frans Dominique Van Der Werndtz</p>
      </div>

      <button onClick={onOpenTerms} style={{ width:'100%', display:'flex', alignItems:'center', gap:12, padding:'14px 4px', background:'none', border:'none', borderTop:`1px solid ${S.border}`, cursor:'pointer', textAlign:'left' }}>
        <FileText size={18} style={{ color:S.gray }}/>
        <span style={{ color:'white', fontSize:14, fontWeight:600, flex:1 }}>{t('privacy.termsAndConditions')}</span>
        <ChevronRight size={16} style={{ color:S.gray }}/>
      </button>

      <p style={{ color:S.gray, fontSize:11.5, marginTop:28 }}>© {new Date().getFullYear()} Snapsa. All rights reserved.</p>
    </div>
  </div>
  );
};

