                  <input type="password" inputMode="numeric" style={{ ...wpInput, marginTop:10 }} value={pinForm.confirm} placeholder="Confirm PIN"
                    onChange={e => setPinForm(p => ({ ...p, confirm:e.target.value.replace(/\D/g, '').slice(0, 6) }))} />
