// ─── Bottom Nav  ──────────────────
const BottomNav = ({
  activeTab,
  onTabChange,
  onCreatePress,
    unreadNotifCount = 0,
  unreadMsgCount = 0,
  offlineMode = false,
  emberActive = false
}) => {
  const { t } = useLanguage();

  const tabs = [
    { id: 'feed', icon: Home, label: t('nav.home') },
    { id: 'discover', icon: Compass, label: t('nav.discover') },
    { id: 'music', icon: Music2, label: t('nav.music') },
    { id: 'create', icon: Plus, label: '' },
    { id: 'notifications', icon: Bell, label: t('nav.alerts'), badge: unreadNotifCount },
    { id: 'inbox', icon: MessageCircle, label: t('nav.messages'), badge: unreadMsgCount },
    { id: 'profile', icon: User, label: t('nav.me') },
  ];

  return (
    <div className={emberActive ? 'snapsa-bottom-nav offline-ember player-ember' : offlineMode ? 'snapsa-bottom-nav offline-ember' : 'snapsa-bottom-nav'}
      onClickCapture={() => { if (offlineMode) window.dispatchEvent(new CustomEvent('snapsa:closeOffline')); }}>

      <div className="snapsa-nav-inner">

        {tabs.map(({ id, icon: Icon, label, badge }) => {

          // Central Create button
          if (id === 'create') {
            return (
              <motion.button
                key={id}
                type="button"
                whileTap={{ scale: 0.88 }}
                onClick={onCreatePress}
                className="snapsa-create-button"
                aria-label="Create"
              >
                <Plus size={34} strokeWidth={2.8} />
              </motion.button>
            );
          }

          const isA = activeTab === id;

          return (
            <motion.button
              key={id}
              type="button"
              whileTap={{ scale: 0.91 }}
              onClick={() => onTabChange(id)}
              className={`snapsa-nav-item ${isA ? 'active' : ''}`}
              aria-label={label}
              aria-current={isA ? 'page' : undefined}
            >

              <div className="snapsa-nav-icon">

                <Icon
                  size={25}
                  strokeWidth={isA ? 2.5 : 1.8}
                />

                {badge > 0 && (
                  <span className="snapsa-nav-badge">
                    {badge > 99 ? '99+' : badge}
                  </span>
                )}

              </div>

              <span className="snapsa-nav-label">
                {label}
              </span>

            </motion.button>
          );
        })}

      </div>
    </div>
  );
};
const LiveStatsModal = ({ stats, onClose }) => {
  if (!stats) return null;
  const mins = Math.floor((stats.duration || 0) / 60000);
  const secs = Math.floor(((stats.duration || 0) % 60000) / 1000);

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 300,
      background: 'rgba(0,0,0,0.85)', backdropFilter: 'blur(8px)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20,
    }}>
      <motion.div
        initial={{ scale: 0.85, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        style={{ width: '100%', maxWidth: 360, background: S.card, borderRadius: 24, padding: 28, border: `1px solid ${S.border}` }}
      >
        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: 24 }}>
          <div style={{ fontSize: 48 }}>🎬</div>
          <h2 style={{ color: 'white', fontWeight: 900, fontSize: 22, margin: '8px 0 4px' }}>
            Stream Complete!
          </h2>
          <p style={{ color: S.gray, fontSize: 13 }}>Here's how your stream went</p>
        </div>

        {/* Stats grid */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: 24 }}>
          {[
            { label: 'Duration',     value: `${mins}m ${secs}s`,                  icon: '⏱' },
            { label: 'Peak Viewers', value: stats.peakViewers || 0,               icon: '👥' },
            { label: 'Total Likes',  value: fmt(stats.totalLikes || 0),            icon: '❤️' },
            { label: 'Revenue',      value: `$${(stats.totalRevenue||0).toFixed(2)}`, icon: '💰' },
          ].map(({ label, value, icon }) => (
            <div key={label} style={{ background: S.dark, borderRadius: 14, padding: '12px 14px', border: `1px solid ${S.border}` }}>
              <div style={{ fontSize: 20, marginBottom: 4 }}>{icon}</div>
              <div style={{ color: 'white', fontWeight: 800, fontSize: 18 }}>{value}</div>
              <div style={{ color: S.gray, fontSize: 11 }}>{label}</div>
            </div>
          ))}
        </div>

        <button
          onClick={onClose}
          style={{ width: '100%', padding: '13px 0', borderRadius: 12, background: S.pink, color: 'white', fontWeight: 700, fontSize: 15, border: 'none', cursor: 'pointer' }}
        >
          Done
        </button>
      </motion.div>
    </div>
  );
};
// ─── Username Modal ───────────────────────────────────────────────────
const UsernameModalInline = ({ current, onSave, onClose }) => {
  const [v, setV] = useState(current||'');
  const [av, setAv] = useState(null);
  const [ck, setCk] = useState(false);
  const check = async raw => {
    setV(raw);
    if (raw.length<3) { setAv(null); return; }
    setCk(true);
    try { const r=await snapFetch(`/snapsa/username/check?username=${encodeURIComponent(raw)}`); const d=r.ok?await r.json():null; setAv(d?.available??true); } catch { setAv(true); }
    setCk(false);
  };
  const save = async () => {
    if (!av||v.length<3) return;
    try { await snapFetch('/snapsa/username/reserve',{method:'POST',body:JSON.stringify({username:v})}); } catch {}
    onSave(v); onClose();
  };
  return (
    <div style={{ position:'fixed', inset:0, zIndex:500, display:'flex', alignItems:'flex-end', justifyContent:'center', background:'rgba(0,0,0,.7)' }} onClick={onClose}>
      <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }}
        style={{ width:'100%', maxWidth:480, background:S.card, borderTopLeftRadius:24, borderTopRightRadius:24, padding:'24px 24px 36px' }} onClick={e=>e.stopPropagation()}>
        <div style={{ width:40, height:4, borderRadius:999, background:S.border, margin:'0 auto 20px' }}/>
        <h3 style={{ color:'white', fontWeight:700, fontSize:18, marginBottom:4 }}>Snapsa Username</h3>
        <p style={{ color:S.gray, fontSize:13, marginBottom:20 }}>This is your Snapsa profile photo.</p>
        <div style={{ display:'flex', alignItems:'center', gap:8, background:S.dark, borderRadius:12, padding:'12px 16px', border:`1px solid ${S.border}`, marginBottom:12 }}>
          <span style={{ color:S.gray }}>@</span>
          <input value={v} onChange={e=>check(e.target.value.toLowerCase().replace(/[^a-z0-9_.]/g,''))} placeholder="your_snapsa_name" maxLength={30} autoFocus
            style={{ flex:1, background:'transparent', border:'none', outline:'none', color:'white', fontSize:14 }}/>
          {ck&&<div style={{ width:16, height:16, borderRadius:'50%', border:`2px solid ${S.pink}`, borderTopColor:'transparent', animation:'sp .8s linear infinite' }}/>}
          {!ck&&av===true&&<Check size={16} style={{ color:'#4ade80' }}/>}
          {!ck&&av===false&&<X size={16} style={{ color:'#f87171' }}/>}
        </div>
        {av===true&&<p style={{ color:'#4ade80', fontSize:12, marginBottom:16 }}>✓ @{v} is available!</p>}
        {av===false&&<p style={{ color:'#f87171', fontSize:12, marginBottom:16 }}>✗ Already taken</p>}
        <style>{`@keyframes sp{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style>
        <div style={{ display:'flex', gap:12 }}>
          <button onClick={onClose} style={{ flex:1, padding:'12px 0', borderRadius:12, background:S.border, color:S.gray, fontWeight:600, fontSize:14, border:'none', cursor:'pointer' }}>Cancel</button>
          <button onClick={save} disabled={!av||v.length<3} style={{ flex:1, padding:'12px 0', borderRadius:12, background:av&&v.length>=3?S.pink:S.border, color:'white', fontSize:14, fontWeight:700, border:'none', cursor:'pointer', opacity:av&&v.length>=3?1:.5 }}>Save</button>
        </div>
      </motion.div>
    </div>
  );
};

// ─── Name (shown on the profile beside the @username) ────────────────
const wernjatFullName = (userData, currentUser) => {
  const bad = (x) => !x || /^(loading|user|guest|snapsa user)\.{0,3}$/i.test(String(x).trim());
  if (userData?.firstName && !bad(userData.firstName)) return `${userData.firstName} ${userData.lastName || ''}`.trim();
  if (userData?.fullName && !bad(userData.fullName)) return userData.fullName;
  if (currentUser?.firstName && !bad(currentUser.firstName)) return `${currentUser.firstName} ${currentUser.lastName || ''}`.trim();
  if (currentUser?.displayName && !bad(currentUser.displayName)) return currentUser.displayName;
  return '';
};

