const SaveProgressModal = ({ video, snapUrl, authToken, onClose, showToast }) => {
  const [progress, setProgress]   = useState(0);
  const [status,   setStatus]     = useState('Preparing...');
  const [done,     setDone]       = useState(false);
  const [error,    setError]      = useState(null);
  const abortRef                  = useRef(false);

  useEffect(() => {
    let cancelled = false;
    abortRef.current = false;

    const run = async () => {
      try {
        setStatus('Connecting to server...');
        setProgress(5);

        const { saveVideoToDevice } = await import('./videoSave.js');

        await saveVideoToDevice({
          videoId:    video.id,
          authorName: video.authorName,
          snapUrl,
          authToken,
          onProgress: (pct) => {
            if (cancelled) return;
            setProgress(pct);
            if (pct < 20)  setStatus('Connecting...');
            else if (pct < 55) setStatus(`Downloading... ${pct}%`);
            else if (pct < 80) setStatus('Processing...');
            else if (pct < 95) setStatus('Saving to device...');
            else               setStatus('Almost done...');
          },
        });

        if (cancelled) return;

        setProgress(100);
        setStatus('Saved!');
        setDone(true);
        showToast?.('✅ Video saved!', 'success');

        setTimeout(() => { if (!cancelled) onClose(); }, 2000);

      } catch (err) {
        if (cancelled) return;
        console.error('[Save]', err);
        setError(err.message || 'Save failed');
        setStatus('Failed');
        showToast?.('❌ Could not save video', 'error');
      }
    };

    run();

    return () => { cancelled = true; abortRef.current = true; };
  }, []);

  const progressColor = error ? '#ef4444' : done ? '#4ade80' : S.pink;

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 600,
      background: 'rgba(0,0,0,0.88)', backdropFilter: 'blur(8px)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20,
    }}>
      <motion.div
        initial={{ scale: 0.88, opacity: 0 }}
        animate={{ scale: 1,    opacity: 1 }}
        exit={{   scale: 0.88,  opacity: 0 }}
        style={{ width: '100%', maxWidth: 320, background: S.card, borderRadius: 24, padding: 28, textAlign: 'center', border: `1px solid ${S.border}` }}
      >
        {/* Logo */}
        <img src="/SnapsaLogo.png" alt="Snapsa"
          style={{ width: 52, height: 52, borderRadius: '50%', margin: '0 auto 16px', display: 'block' }}
          onError={e => e.target.style.display = 'none'}
        />

        <h3 style={{ color: 'white', fontWeight: 800, fontSize: 18, marginBottom: 4 }}>
          {done ? 'Video Saved!' : error ? 'Save Failed' : 'Saving Video'}
        </h3>
        <p style={{ color: S.gray, fontSize: 12, marginBottom: 22 }}>
          {video.authorName}
        </p>

        {/* Progress bar */}
        <div style={{ background: 'rgba(255,255,255,0.08)', borderRadius: 99, height: 8, overflow: 'hidden', marginBottom: 10 }}>
          <motion.div
            animate={{ width: `${progress}%` }}
            transition={{ duration: 0.3 }}
            style={{ height: '100%', background: progressColor, borderRadius: 99 }}
          />
        </div>

        <p style={{ color: progressColor, fontWeight: 700, fontSize: 14, marginBottom: 6 }}>
          {Math.round(progress)}%
        </p>
        <p style={{ color: S.gray, fontSize: 12, marginBottom: 24 }}>{status}</p>

        {/* Watermark notice */}
        {!done && !error && (
          <p style={{ color: 'rgba(255,255,255,0.3)', fontSize: 10, marginBottom: 20 }}>
          </p>
        )}

        {/* Actions */}
        {!done && !error && (
          <button
            onClick={onClose}
            style={{ width: '100%', padding: '11px 0', borderRadius: 12, background: 'rgba(255,255,255,0.08)', color: S.gray, border: `1px solid ${S.border}`, cursor: 'pointer', fontWeight: 600, fontSize: 14 }}
          >
            Cancel
          </button>
        )}

        {(done || error) && (
          <button
            onClick={onClose}
            style={{ width: '100%', padding: '11px 0', borderRadius: 12, background: done ? '#4ade8022' : `${S.pink}22`, color: done ? '#4ade80' : S.pink, border: `1px solid ${done ? '#4ade8044' : S.pink+'44'}`, cursor: 'pointer', fontWeight: 700, fontSize: 14 }}
          >
            {error ? 'Close' : 'Done'}
          </button>
        )}
      </motion.div>
    </div>
  );
};

// ─── MAIN APP ─────────────────────────────────────────────────────────
const sendOutboxItem = (it) => {
  const fd = new FormData();
  Object.entries(it.fields || {}).forEach(([k, v]) => { if (v !== undefined && v !== null) fd.append(k, v); });
  if (it.file) fd.append('media', it.file);
  return snapFetch(it.kind === 'story' ? '/snapsa/stories' : `/snapsa/messages/${it.target}`, { method: 'POST', body: fd });
};

const SnapsaAppInner = ({ onClose, currentUser: currentUserProp, userData, followers=[], following=[], timeline=[], showToast, authToken, api, useAuth }) => {
  // The signed-in token is the source of truth for "who am I". If the user object carries a different _id
  // (e.g. an old WernTjat id) own videos/chats were treated as someone else's and chat deletes hit the wrong chat.
  const currentUser = React.useMemo(() => {
    try {
      const tok = getSnapToken() || authToken;
      const b = tok && tok.split('.')[1];
      if (!b || !currentUserProp) return currentUserProp;
      const pl = JSON.parse(atob(b.replace(/-/g, '+').replace(/_/g, '/')));
      const uid = pl.userId || pl.id || pl.sub;
      if (uid && String(currentUserProp._id || currentUserProp.id || '') !== String(uid)) return { ...currentUserProp, _origId: currentUserProp._id || currentUserProp.id, _id: String(uid), id: String(uid) };
    } catch {}
    return currentUserProp;
  }, [currentUserProp, authToken]);
  // Offline outbox: queued chat messages and stories go out as soon as we are online.
  useEffect(() => {
    const go = () => flushOutbox(sendOutboxItem);
    const sent = (e) => { if (e.detail?.item?.kind === 'story') { showToast?.('✨ Your queued story was posted', 'success'); window.dispatchEvent(new CustomEvent('snapsa:storyPosted')); } };
    const dropped = (e) => showToast?.(e.detail?.item?.kind === 'story' ? 'A queued story could not be posted' : 'A queued message could not be sent', 'error');
    go();
    window.addEventListener('online', go);
    window.addEventListener('snapsa:outboxSent', sent);
    window.addEventListener('snapsa:outboxDropped', dropped);
    const t = setInterval(go, 20000);
    return () => { clearInterval(t); window.removeEventListener('online', go); window.removeEventListener('snapsa:outboxSent', sent); window.removeEventListener('snapsa:outboxDropped', dropped); };
  }, []);


  const [activeTab, setActiveTab] = useState('feed');
  const [feedMode, setFeedMode] = useState('public');
  const [showCreate, setShowCreate] = useState(false);
  const [showStories, setShowStories] = useState(false);
  const [showPosts, setShowPosts] = useState(false);
  const [showGoLive, setShowGoLive] = useState(false);
  const [liveFeaturedBrand, setLiveFeaturedBrand] = useState(null);
  const [showLive,   setShowLive]   = useState(false);
  const [showRecord, setShowRecord] = useState(false);
  const [showUpload, setShowUpload] = useState(false);
  const [viewProfile, setViewProfile] = useState(null);
  useDeepLink(async (u) => {
    try {
      const r = await snapFetch(`/snapsa/profile-by-username/${encodeURIComponent(u)}`);
      const d = r.ok ? await r.json() : null;
      if (d?.id) { setShowCreate(false); setViewProfile({ authorId: d.id, id: d.id, username: d.username, authorName: d.username }); }
      else showToast?.('Could not find that profile', 'error');
    } catch { showToast?.('Could not open that profile', 'error'); }
  }, !!currentUser?._id);
  const [productStoreTarget, setProductStoreTarget] = useState(null); // {sellerId, productId?, featuringVideoId?}
  // Notifications is now a proper tab — no overlay state needed
  const [dmTarget, setDmTarget] = useState(null);
  useEffect(() => { const h = (e) => { const u = e.detail || {}; setDmTarget({ ...u, fresh: true }); }; window.addEventListener('snapsa:openFreshChat', h); return () => window.removeEventListener('snapsa:openFreshChat', h); }, []);
  const [inboxRefreshKey, setInboxRefreshKey] = useState(0);
  const [unreadNotifCount, setUnreadNotifCount] = useState(0);
  const [unreadMsgCount, setUnreadMsgCount] = useState(0);
  const [showUsernameModal, setShowUsernameModal] = useState(false);
  const [quickPlayVideo, setQuickPlayVideo] = useState(null);
  const [showAvatarModal,   setShowAvatarModal]   = useState(false);
  const [showBioModal,      setShowBioModal]       = useState(false);

   // ─── NEW: Live stream state ───────────────────────────────────────────────
  const [liveService,    setLiveService]    = useState(null);
  const [isBroadcasting, setIsBroadcasting] = useState(false);
  const [streamChannel,  setStreamChannel]  = useState(null);
  const [liveStats,      setLiveStats]      = useState(null);
  const [showLiveStats,  setShowLiveStats]  = useState(false);

  const uid = currentUser?._id||'';
  const [snapsaUsername, setSnapsaUsername] = useState(()=>localStorage.getItem(`snapsa_un_${uid}`)||'');
  const [snapsaAvatar,   setSnapsaAvatar]   = useState(()=>localStorage.getItem(`snapsa_avatar_${uid}`)||null);
  const [snapsaBio,      setSnapsaBio]      = useState(()=>localStorage.getItem(`snapsa_bio_${uid}`)||'');
  const [snapsaName,     setSnapsaName]     = useState(()=>localStorage.getItem(`snapsa_name_${uid}`)||'');
  const [showNameModal,  setShowNameModal]   = useState(false);
  const [snapsaTier,     setSnapsaTier]     = useState('');
  const [snapsaOfficial, setSnapsaOfficial] = useState('');

  const [feedH, setFeedH] = useState(0);
  const rootRef = useRef(null);
  const [offlineMode, setOfflineMode] = useState(false);
  useEffect(() => {
    const on = (e) => setOfflineMode(!!e.detail);
    window.addEventListener('snapsa:offlineMode', on);
    return () => window.removeEventListener('snapsa:offlineMode', on);
  }, []);

  const NAVH = 64, HEADERH = 92;


  const [snapsaForceLoggedOut, setSnapsaForceLoggedOut] = useState(() => {
  
    try {
      return localStorage.getItem(SNAPSA_LOGGED_OUT_FLAG) === '1' && !localStorage.getItem(SNAPSA_OWN_TOKEN_KEY);
    } catch { return false; }
  });

  useEffect(() => {
    if (snapsaForceLoggedOut) { _activeToken = null; return; }
    _activeToken = authToken || null;
    return () => { _activeToken = null; };
  }, [authToken, snapsaForceLoggedOut]);
  useEffect(() => {
    const h = () => setSnapsaForceLoggedOut(true);
    window.addEventListener('snapsa:forceLogout', h);
    return () => window.removeEventListener('snapsa:forceLogout', h);
  }, []);

  const [SnapsaEntryForLogout, setSnapsaEntryForLogout] = useState(null);
  useEffect(() => {
    if (!snapsaForceLoggedOut) return;
    import('./SnapsaEntry').then(m => setSnapsaEntryForLogout(() => m.SnapsaEntry || m.default));
  }, [snapsaForceLoggedOut]);
  useEffect(() => {
     // The tab bar is taller now (neon design), so measure it instead of assuming 64px.
    const m = ()=>{
      if(!rootRef.current) return;
      const nav = rootRef.current.querySelector('.snapsa-bottom-nav');
      setFeedH(rootRef.current.clientHeight-(nav ? nav.offsetHeight : NAVH));
    };
    m(); const t1=setTimeout(m,300), t2=setTimeout(m,1200);
    const ro=new ResizeObserver(m); if(rootRef.current) ro.observe(rootRef.current);
    window.addEventListener('resize', m);
    return()=>{ clearTimeout(t1); clearTimeout(t2); ro.disconnect(); window.removeEventListener('resize', m); };

  }, []);
  useEffect(() => {
    if (!uid) return;
snapFetch('/snapsa/me').then(r=>r.ok?r.json():null).then(d=>{
  if(d?.profile?.username&&!snapsaUsername) setSnapsaUsername(d.profile.username);
  if(d?.profile?.bio&&!snapsaBio) setSnapsaBio(d.profile.bio);
  if(d?.profile?.displayName&&!snapsaName) { setSnapsaName(d.profile.displayName); localStorage.setItem(`snapsa_name_${uid}`, d.profile.displayName); }
  if(d?.profile?.snapsaTier) setSnapsaTier(d.profile.snapsaTier);
  setSnapsaOfficial(d?.profile?.officialLabel || '');
  if (typeof d?.profile?.avatarUrl !== 'undefined') {
    setSnapsaAvatar(d.profile.avatarUrl || null);
    try {
      if (d.profile.avatarUrl) localStorage.setItem(`snapsa_avatar_${uid}`, d.profile.avatarUrl);
      else localStorage.removeItem(`snapsa_avatar_${uid}`);
    } catch {}
  }
});
  }, [uid]);
  
   // ─── Push: ask permission + register this device's FCM token
  useEffect(() => {
    if (!uid || snapsaForceLoggedOut) return;
    registerForPush((token) => snapFetch('/snapsa/push/register', {
      method: 'POST',
      body: JSON.stringify({ token, platform: 'android' }),
    }));
  }, [uid, snapsaForceLoggedOut]);

  // ─── Snapsa realtime: DMs + notifications
  useEffect(() => {
    if (!uid) return;
    let ws, closedByUs = false, retryMs = 1500;
    const connect = () => {
      const token = getSnapToken();
      if (!token) return;
      const WS_URL = SNAP_URL.replace(/^http/, 'ws');
      ws = new WebSocket(`${WS_URL}/snapsa/live/ws?snapsa=1&token=${token}`);
      ws.onopen = () => { retryMs = 1500; };
      ws.onmessage = (evt) => {
        let msg; try { msg = JSON.parse(evt.data); } catch { return; }
        if (msg.type === 'new_message') {
                    setUnreadMsgCount(c => c + 1);
          playSnapsaPing();
          window.dispatchEvent(new CustomEvent('snapsa:realtimeMessage', { detail: msg }));
        } else if (msg.type === 'message_sent') {
          window.dispatchEvent(new CustomEvent('snapsa:realtimeMessage', { detail: msg }));
        } else if (msg.type === 'snapsa_dm_reaction') {
          window.dispatchEvent(new CustomEvent('snapsa:realtimeReaction', { detail: msg }));
        } else if (msg.type === 'snapsa_dm_delivered') {
          window.dispatchEvent(new CustomEvent('snapsa:dmDelivered', { detail: msg }));
        } else if (msg.type === 'call_signal') {
          window.dispatchEvent(new CustomEvent('snapsa:callSignal', { detail: msg }));
        } else if (msg.type === 'snapsa_dm_burned') {
          window.dispatchEvent(new CustomEvent('snapsa:dmBurned', { detail: msg }));
        } else if (msg.type === 'snapsa_dm_deleted') {
          window.dispatchEvent(new CustomEvent('snapsa:dmDeleted', { detail: msg }));
        } else if (msg.type === 'new_notification') {
                    setUnreadNotifCount(c => c + 1);
          playSnapsaPing();
          showToast?.(msg.notification?.title || 'New notification', 'info');
          window.dispatchEvent(new CustomEvent('snapsa:realtimeNotification', { detail: msg }));

        }
      };
      ws.onclose = () => {
        if (closedByUs) return;
        setTimeout(connect, retryMs);
        retryMs = Math.min(retryMs * 1.7, 20000);
      };
      ws.onerror = () => { try { ws.close(); } catch {} };
    };
    connect();
    return () => { closedByUs = true; try { ws?.close(); } catch {} };
  }, [uid]);

  // Presence heartbeat — keeps lastActiveAt fresh for the "last seen X ago"
  // fallback. The socket connect/disconnect already covers most of this,
  // but a periodic ping catches long-lived tabs and brief reconnect gaps.
  useEffect(() => {
    if (!uid) return;
    const ping = () => snapFetch('/snapsa/presence/ping', { method:'POST' }).catch(()=>{});
    ping();
    const t = setInterval(ping, 30000);
    return () => clearInterval(t);
  }, [uid]);

  // Quick-play video from search
  useEffect(() => {
    const h = (e) => setQuickPlayVideo(e.detail?.video || null);
    window.addEventListener('snapsa:playVideo', h);
    return () => window.removeEventListener('snapsa:playVideo', h);
  }, []);

  // Tab switch from child components (e.g. empty messages → discover)
  useEffect(() => {
    const h = (e) => { if (e.detail) setActiveTab(e.detail); };
    window.addEventListener('snapsa:switchTab', h);
    return () => window.removeEventListener('snapsa:switchTab', h);
  }, []);


    // ─── Snapsa API adapter for LiveStreamService ─────────────────────────────
const snapApiInstance = useRef({
  get: async (path) => {
    const res = await snapFetch(path);
    if (!res.ok) throw new Error(`GET ${path} failed: ${res.status}`);
    return res.json();
  },
  post: async (path, body = {}) => {
    const res = await snapFetch(path, {
      method: 'POST',
      body: JSON.stringify(body),
    });
    // Some endpoints return 204 No Content — handle gracefully
    if (res.status === 204) return {};
    if (!res.ok) throw new Error(`POST ${path} failed: ${res.status}`);
    return res.json();
  },
}).current;

  const saveUsername = async (v) => {
    setSnapsaUsername(v); localStorage.setItem(`snapsa_un_${uid}`,v);
    try { await snapFetch('/snapsa/me',{method:'POST',body:JSON.stringify({username:v,bio:snapsaBio})}); showToast?.('✅ Username saved!','success'); } catch { showToast?.('✅ Saved locally','info'); }
  };
  const saveBio = async (v) => {
    setSnapsaBio(v); localStorage.setItem(`snapsa_bio_${uid}`,v);
    try { await snapFetch('/snapsa/me',{method:'POST',body:JSON.stringify({username:snapsaUsername,bio:v})}); } catch {}
    showToast?.('✅ Bio saved!','success');
  };

  const saveName = async (v) => {
    const clean = (v || '').replace(/\s+/g, ' ').trim().slice(0, 50);
    try {
      const res = await snapFetch('/snapsa/me/name', { method:'PUT', body: JSON.stringify({ displayName: clean }) });
      if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || 'Could not save name'); }
      setSnapsaName(clean); localStorage.setItem(`snapsa_name_${uid}`, clean);
      showToast?.('✅ Name saved!', 'success');
    } catch (err) { showToast?.(err.message || 'Could not save name', 'error'); }
  };

  const handleViewProfile = useCallback(async (video) => {
    const authorId = video.authorId||video.id||video._id;
    if (!authorId) { setViewProfile(video); return; }
    // If this is the current user's own profile, switch to Me tab instead of opening a profile sheet
    const myId = currentUser?._id || currentUser?.id;
    if (authorId && myId && authorId.toString() === myId.toString()) {
      setActiveTab('profile');
      return;
    }
    try {
      const res=await snapFetch(`/snapsa/users/${authorId}`);
      if(res.ok){
        const d=await res.json();
        setViewProfile({
          ...d.user,
          id: d.user.id,
          _id: d.user.id,
          authorId: d.user.id,
          videos: d.videos,
          isFollowing: d.isFollowing,
          authorName: d.user.username||video.authorName,
          _isOtherUser: true,  // explicit flag so UserProfileScreen never shows "Follow" for self
        });
      } else setViewProfile({...video, _isOtherUser:true});
    } catch { setViewProfile({...video, _isOtherUser:true}); }
  }, [currentUser]);

  const handleTabChange = id => {
    if (id === 'create') return;
    
    if (id === 'feed' && activeTab === 'feed') {
      window.dispatchEvent(new CustomEvent('snapsa:refreshFeed'));
      return;
    }
    if (id === 'inbox') setDmTarget(null); // always land on the chats list, not a stale open thread
    setActiveTab(id);
  };

  // ── Phone back button + swipe between the bottom tabs ───────────────────────────────────────
  // Back: closes whatever is open on top (profile, video, chat, Stories / Posts ...), then goes to Home; from Home it leaves the app.
  const backRef = useRef(() => false);
  backRef.current = () => {
    if (quickPlayVideo) { setQuickPlayVideo(null); return true; }
    if (productStoreTarget) { setProductStoreTarget(null); return true; }
    if (showRecord) { setShowRecord(false); return true; }
    if (showUpload) { setShowUpload(false); return true; }
    if (showCreate) { setShowCreate(false); return true; }
    if (viewProfile) { setViewProfile(null); return true; }
    if (showStories) { setShowStories(false); return true; }
    if (showPosts) { setShowPosts(false); return true; }
    if (activeTab === 'inbox' && dmTarget) { setDmTarget(null); return true; }
    if (activeTab !== 'feed') { setActiveTab('feed'); return true; }
    return false;
  };
  useEffect(() => {
    let on = false, h = null;
    (async () => {
      try {
        const { Capacitor, registerPlugin } = await import('@capacitor/core');
        if (!Capacitor.isNativePlatform()) return;
        on = true;
        const native = registerPlugin('SnapsaRingtone');
        history.pushState({ snapsa: 1 }, '');
        h = () => {
          if (backRef.current()) { history.pushState({ snapsa: 1 }, ''); return; }
          native.exitApp?.().catch?.(() => {});   // on Home with nothing open: leave the app
        };
        window.addEventListener('popstate', h);
      } catch {}
    })();
    return () => { if (h) window.removeEventListener('popstate', h); };
  }, []);

  // Swipe left / right anywhere on the main screens moves to the next / previous bottom tab
  const swipeRef = useRef({});
  swipeRef.current = { activeTab, go: handleTabChange, blocked: !!(showStories || showPosts || viewProfile || showRecord || showUpload || showCreate || quickPlayVideo || productStoreTarget || (activeTab === 'inbox' && dmTarget)) };
  useEffect(() => {
    const ORDER = ['feed', 'discover', 'music', 'notifications', 'inbox', 'profile'];
    let sx = 0, sy = 0, ok = false;
    const scrollableX = (el) => {
      for (let n = el; n && n !== document.body; n = n.parentElement) {
        if (n.dataset?.noswipe) return true;
        const tag = n.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'CANVAS') return true;
        const cs = getComputedStyle(n);
        if ((cs.overflowX === 'auto' || cs.overflowX === 'scroll') && n.scrollWidth > n.clientWidth + 4) return true;
      }
      return false;
    };
    const ts = (e) => { const t = e.touches[0]; sx = t.clientX; sy = t.clientY; ok = e.touches.length === 1 && !swipeRef.current.blocked && !scrollableX(e.target); };
    const te = (e) => {
      if (!ok) return; ok = false;
      const t = e.changedTouches[0]; const dx = t.clientX - sx, dy = t.clientY - sy;
      if (Math.abs(dx) < 80 || Math.abs(dx) < Math.abs(dy) * 2) return;
      const i = ORDER.indexOf(swipeRef.current.activeTab); if (i < 0) return;
      const next = ORDER[i + (dx < 0 ? 1 : -1)]; if (next) swipeRef.current.go(next);
    };
    window.addEventListener('touchstart', ts, { passive: true });
    window.addEventListener('touchend', te, { passive: true });
    return () => { window.removeEventListener('touchstart', ts); window.removeEventListener('touchend', te); };
  }, []);

  // The full-screen player has its own nav; its taps arrive here.
  useEffect(() => {
    const nav = (e) => { if (e.detail) handleTabChange(e.detail); };
    const create = () => setShowCreate(true);
    const stories = () => setShowStories(true);
    const posts = () => setShowPosts(true);
    window.addEventListener('snapsa:navTab', nav);
    window.addEventListener('snapsa:openCreate', create);
    window.addEventListener('snapsa:openStories', stories);
    window.addEventListener('snapsa:openPosts', posts);
    let lastLock = 0; const lock = () => { if (Date.now() - lastLock > 4000) { lastLock = Date.now(); showToast?.('🔒 DEFCON lockdown: you can only watch videos, read posts and use Music', 'info'); } };
    window.addEventListener('snapsa:lockdown', lock);
    return () => { window.removeEventListener('snapsa:navTab', nav); window.removeEventListener('snapsa:openCreate', create); window.removeEventListener('snapsa:openStories', stories); window.removeEventListener('snapsa:openPosts', posts); window.removeEventListener('snapsa:lockdown', lock); };
  }, [activeTab]);

  // ─── Poll unread badge counts for the Alerts + Messages tabs ───────────
  const refreshUnreadCounts = useCallback(() => {
    if (!currentUser?._id || currentUser?.isGuest === true) return;
    snapFetch('/snapsa/notifications/unread-count')
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (typeof d?.count === 'number') setUnreadNotifCount(d.count); })
      .catch(() => {});
    snapFetch('/snapsa/messages/unread-count')
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (typeof d?.count === 'number') setUnreadMsgCount(d.count); })
      .catch(() => {});
  }, [currentUser?._id, currentUser?.isGuest]);

  useEffect(() => {
    if (!currentUser?._id || currentUser?.isGuest === true) {
      setUnreadNotifCount(0);
      setUnreadMsgCount(0);
      return;
    }
    refreshUnreadCounts();
    const t = setInterval(() => { if (!document.hidden) refreshUnreadCounts(); }, 15000);
    return () => clearInterval(t);
  }, [currentUser?._id, currentUser?.isGuest, refreshUnreadCounts]);

// Coming back to the app (or the network returning) re-fetches badges, my
// profile numbers, the chat list and notifications.
  useEffect(() => {
    if (!currentUser?._id || currentUser?.isGuest === true) return;
    let last = 0;
    const resume = () => {
      if (document.visibilityState === 'hidden') return;
      const now = Date.now();
      if (now - last < 3000) return;
      last = now;
      refreshUnreadCounts();
      window.dispatchEvent(new CustomEvent('snapsa:followChanged'));
      window.dispatchEvent(new CustomEvent('snapsa:appResume'));
    };
    document.addEventListener('visibilitychange', resume);
    window.addEventListener('focus', resume);
    window.addEventListener('online', resume);
    return () => {
      document.removeEventListener('visibilitychange', resume);
      window.removeEventListener('focus', resume);
      window.removeEventListener('online', resume);
    };
  }, [currentUser?._id, currentUser?.isGuest, refreshUnreadCounts]);

  // Opening the Alerts tab clears its badge (list itself still shows read/unread per-item)
  

  // Opening the Alerts tab clears its badge (list itself still shows read/unread per-item)
  useEffect(() => {
    if (activeTab === 'notifications' && unreadNotifCount > 0) {
      setUnreadNotifCount(0);
      snapFetch('/snapsa/notifications/mark-all-read', { method: 'POST' }).catch(() => {});
    }
  }, [activeTab, unreadNotifCount]);

// ─── Initialize the live stream ───────────────────────────────────────────
const initializeLiveStream = useCallback(async (brandId) => {
  if (!currentUser?._id) {
    showToast?.('Please log in to go live', 'error');
    return;
  }

  try {
    // Unique channel name per stream session
    const channelName = `snapsa_${currentUser._id}_${Date.now()}`;
    setStreamChannel(channelName);
    setLiveFeaturedBrand(brandId || null);
    setIsBroadcasting(true);
    setShowGoLive(false); // close pre-stream screen
    setShowLive(true);    // open LiveStreamSystem

    if (brandId) {
      // Fire-and-forget — lets the backend attribute brand-deal revenue to this stream
      snapFetch('/snapsa/live/feature-brand', { method:'POST', body: JSON.stringify({ channelName, brandId }) }).catch(()=>{});
    }

    showToast?.(brandId ? `🔴 Starting broadcast · featuring ${BRAND_PARTNERS[brandId]?.name}...` : '🔴 Starting broadcast...', 'info');
  } catch (err) {
    console.error('[Live] Init failed:', err);
    showToast?.('Failed to start stream', 'error');
    setIsBroadcasting(false);
    setStreamChannel(null);
  }
}, [currentUser, showToast]);

// ─── Handle stream end — receives stats from LiveStreamSystem ─────────────
const handleLiveClose = useCallback((stats) => {
  setShowLive(false);
  setIsBroadcasting(false);
  setStreamChannel(null);

  if (stats && typeof stats === 'object') {
    setLiveStats(stats);
    setShowLiveStats(true);

    const mins     = Math.floor((stats.duration || 0) / 60000);
    const revenue  = (stats.totalRevenue || 0).toFixed(2);
    const viewers  = stats.peakViewers || 0;
    showToast?.(
      `🎬 Stream ended · ${mins}m · 👥 ${viewers} peak · 💰 $${revenue}`,
      'success'
    );
  }
}, [showToast]);

// ─── Cleanup stream service on unmount ────────────────────────────────────
useEffect(() => {
  return () => {
    if (liveService) {
      liveService.destroy().catch(err =>
        console.warn('[Live] Cleanup error:', err)
      );
    }
  };
}, [liveService]);

  if (snapsaForceLoggedOut) {
    if (!SnapsaEntryForLogout) return (
      <div style={{ position:'fixed', inset:0, background:'#0B0B14', display:'flex', alignItems:'center', justifyContent:'center' }} />
    );
    const SnapsaEntryComp = SnapsaEntryForLogout;
    return (
      <SnapsaEntryComp
        onAuthenticated={(user, token) => {
          try { localStorage.setItem(SNAPSA_OWN_TOKEN_KEY, token); } catch {}
          window.location.reload();
        }}
        onBack={() => setSnapsaForceLoggedOut(false)}
      />
    );
  }

  return (
    <motion.div initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }}
      ref={rootRef}
      style={{ position:'fixed', inset:0, zIndex:200, display:'flex', flexDirection:'column', overflow:'hidden', background:'#0B0B14' }}>

      {activeTab!=='feed' && !offlineMode && <PageTopBar onClose={onClose}/>}

      <div style={{ flex:1, overflow:'hidden', position:'relative', display:'flex', flexDirection:'column' }}>
        <CosmicBg />
        {/* All tab screens stay mounted the whole session  */}
        <div style={{ display: activeTab==='feed' ? 'flex' : 'none', flexDirection:'column', flex:1, minHeight:0 }}>
          <HomeTopBar ownAvatar={snapsaAvatar} />
          <ScreenErrorBoundary>
          <FeedScreen
            currentUser={currentUser}
            feedH={feedH ? Math.max(0, feedH - HOME_BAR_H) : 0}
            onViewProfile={handleViewProfile}
            showToast={showToast}
            feedMode={feedMode}
            onFeedModeChange={setFeedMode}
            snapsaAvatar={snapsaAvatar}
            overlayOpen={!!(showStories || showPosts || viewProfile || showRecord || showUpload || quickPlayVideo || productStoreTarget || activeTab!=='feed')}
            onOpenProductStore={setProductStoreTarget}
            // No muted props passed - each video manages its own mute state
          />
          </ScreenErrorBoundary>
        </div>
        <div className="snapsa-tab" style={{ display: activeTab==='discover' ? 'flex' : 'none', flexDirection:'column', flex:1, minHeight:0 }}>
          <ScreenErrorBoundary>
          <DiscoverScreen showToast={showToast} onViewProfile={handleViewProfile}/>
          </ScreenErrorBoundary>
        </div>
        <div className="snapsa-tab" style={{ display: activeTab==='music' ? 'flex' : 'none', flexDirection:'column', flex:1, minHeight:0 }}>
          <ScreenErrorBoundary>
          <MusicScreen currentUser={currentUser} showToast={showToast} isActive={activeTab==='music'}/>
          </ScreenErrorBoundary>
        </div>
        <div className="snapsa-tab" style={{ display: activeTab==='lives' ? 'flex' : 'none', flexDirection:'column', flex:1, minHeight:0 }}>
          <ScreenErrorBoundary>
          <LivesScreen isActive={activeTab==='lives'}/>
          </ScreenErrorBoundary>
        </div>
        <div className="snapsa-tab" style={{ display: activeTab==='notifications' ? 'flex' : 'none', flexDirection:'column', flex:1, minHeight:0 }}>
          <ScreenErrorBoundary>
          <NotificationsScreen onBack={()=>setActiveTab('feed')} showToast={showToast} onOpenProfile={(p)=>{ setActiveTab('feed'); handleViewProfile(p); }}/>
          </ScreenErrorBoundary>
        </div>
        <div className="snapsa-tab" style={{ display: activeTab==='inbox' ? 'flex' : 'none', flexDirection:'column', flex:1, minHeight:0 }}>
          <ScreenErrorBoundary>
          {currentUser?.isGuest ? (
            <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:16, position:'relative', zIndex:1, background:S.dark }}>
              <MessageCircle size={52} style={{ color:'rgba(255,255,255,0.1)' }}/>
              <p style={{ color:S.gray, fontSize:16, fontWeight:700 }}>Messages</p>
              <p style={{ color:'rgba(255,255,255,0.25)', fontSize:13 }}>Sign in to view your messages</p>
              <button onClick={() => window.dispatchEvent(new CustomEvent('snapsa:requestAuth'))}
                style={{ padding:'10px 28px', borderRadius:999, background:S.pink, color:'white', fontWeight:700, fontSize:14, border:'none', cursor:'pointer' }}>
                Sign In
              </button>
            </div>
          ) : dmTarget ? (
            <SnapsaDMScreen currentUser={currentUser} chatUser={dmTarget} onBack={()=>setDmTarget(null)} showToast={showToast}
              onMessageSent={()=>setInboxRefreshKey(k=>k+1)} onMessagesRead={refreshUnreadCounts} isActive={activeTab==='inbox'} onOpenProfile={handleViewProfile}/>
          ) : (
            <DMThreadsScreen currentUser={currentUser} onOpenChat={setDmTarget} refreshKey={inboxRefreshKey} isActive={activeTab==='inbox'}/>
          )}
          </ScreenErrorBoundary>
        </div>
        <div className="snapsa-tab" style={{ display: activeTab==='profile' ? 'flex' : 'none', flexDirection:'column', flex:1, minHeight:0 }}>
          <ScreenErrorBoundary>
          <OwnProfileScreen currentUser={currentUser} userData={userData} followers={followers} following={following}
            snapsaUsername={snapsaUsername} snapsaAvatar={snapsaAvatar} snapsaBio={snapsaBio} snapsaName={snapsaName} onEditName={()=>setShowNameModal(true)} snapsaTier={snapsaTier} snapsaOfficial={snapsaOfficial}
            onEditUsername={()=>setShowUsernameModal(true)} onEditAvatar={()=>setShowAvatarModal(true)} onEditBio={()=>setShowBioModal(true)} showToast={showToast} api={api}          // ADD
    useAuth={useAuth}/>
          </ScreenErrorBoundary>
        </div>

        <AnimatePresence>
          {viewProfile && (
            <motion.div key="up" initial={{ x:'100%' }} animate={{ x:0 }} exit={{ x:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }} style={{ position:'absolute', inset:0, zIndex:40 }}>
              <ScreenErrorBoundary>
              <UserProfileScreen profileUser={viewProfile} onBack={()=>setViewProfile(null)} showToast={showToast} currentUser={currentUser}
                onDM={(u)=>{
                  // Only block if explicitly a guest — undefined/null isGuest means authenticated
                  if (currentUser?.isGuest === true) {
                    showToast?.('Sign in to send messages','info');
                    window.dispatchEvent(new CustomEvent('snapsa:requestAuth'));
                    return;
                  }
                  const targetId = u.id || u._id || u.authorId;
                  if (!targetId) { showToast?.('Could not open chat — missing user id','error'); return; }
                  setDmTarget({ id: targetId, authorName: u.username||u.authorName, avatarUrl: u.avatarUrl||null });
                  setActiveTab('inbox');
                  setViewProfile(null);
                  showToast?.(`💬 Opening chat with @${u.username||u.authorName}`, 'info');
                }}/>
              </ScreenErrorBoundary>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Personal marketplace — opened either from a featured-product chip
            tap in a video, or from "My Store" on your own profile. */}
        <AnimatePresence>
          {productStoreTarget && (
            <motion.div key="store" initial={{ x:'100%' }} animate={{ x:0 }} exit={{ x:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }} style={{ position:'absolute', inset:0, zIndex:45 }}>
              <ScreenErrorBoundary>
              <StoreScreen
                sellerId={productStoreTarget.sellerId}
                highlightProductId={productStoreTarget.productId}
                featuringVideoId={productStoreTarget.featuringVideoId}
                isOwner={String(productStoreTarget.sellerId) === String(currentUser?._id || currentUser?.id)}
                currentUser={currentUser}
                showToast={showToast}
                onBack={() => setProductStoreTarget(null)}
              />
              </ScreenErrorBoundary>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Notifications is now a proper tab */}

        <AnimatePresence>
          {showRecord && (
            <motion.div key="rec" initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }} style={{ position:'absolute', inset:0, zIndex:60 }}>
              <ScreenErrorBoundary>
              <RecordVideoScreen onClose={()=>setShowRecord(false)} showToast={showToast} currentUser={currentUser} snapsaUsername={snapsaUsername}/>
              </ScreenErrorBoundary>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence>
          {showUpload && (
            <motion.div key="upl" initial={{ y:'100%' }} animate={{ y:0 }} exit={{ y:'100%' }} transition={{ type:'spring', damping:30, stiffness:300 }} style={{ position:'absolute', inset:0, zIndex:60 }}>
              <ScreenErrorBoundary>
              <UploadVideoScreen onClose={()=>setShowUpload(false)} showToast={showToast} currentUser={currentUser} snapsaUsername={snapsaUsername}/>
              </ScreenErrorBoundary>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
{activeTab !== 'feed' && <TransferBars floating />}
{showStories && <StoriesScreen onClose={()=>setShowStories(false)} snapFetch={snapFetch} mediaHref={mediaHref} showToast={showToast} currentUser={currentUser} ownAvatar={snapsaAvatar} StoryViewer={StoryViewer} renderBadge={(g)=><AuthorBadges snapsaTier={g.authorSnapsaTier} size={13} crew={g.crew}/>} />}
{showPosts && <PostsScreen onClose={()=>setShowPosts(false)} snapFetch={snapFetch} mediaHref={mediaHref} showToast={showToast} currentUser={currentUser} ownName={snapsaName||snapsaUsername} ownAvatar={snapsaAvatar} ownBadges={<AuthorBadges wernTier={currentUser?.tier} snapsaTier={snapsaTier} size={16}/>} renderBadges={(p)=><AuthorBadges wernTier={p.authorTier} snapsaTier={p.authorSnapsaTier} size={14}/>} />}
<SnapsaCallHost snapFetch={snapFetch} playPing={playSnapsaPing} showToast={showToast}/>
      <BottomNav activeTab={activeTab} onTabChange={handleTabChange} onCreatePress={()=>setShowCreate(true)}
        unreadNotifCount={unreadNotifCount} unreadMsgCount={unreadMsgCount} offlineMode={offlineMode}/>

      <AnimatePresence>
        {showCreate && (
          <>
            <motion.div key="ov" initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
              style={{ position:'absolute', inset:0, background:'rgba(0,0,0,.6)', backdropFilter:'blur(4px)', zIndex:40 }} onClick={()=>setShowCreate(false)}/>
            <ScreenErrorBoundary>
            <CreateSheet
          onClose={()=>setShowCreate(false)}
          onGoLive={()=>{
            setShowCreate(false);
            setShowGoLive(true); 
          }}
          onRecord={()=>setShowRecord(true)}
          onUpload={()=>setShowUpload(true)}
        />
            </ScreenErrorBoundary>
          </>
        )}
       {showAvatarModal && (
          <motion.div key="avatar" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} style={{ position: 'fixed', inset: 0, zIndex: 500 }}>
            <ScreenErrorBoundary>
            <SnapsaAvatarEditor 
              currentUser={currentUser} 
              snapsaAvatar={snapsaAvatar} 
              showToast={showToast}
              onSave={(avatar) => {
                setSnapsaAvatar(avatar);
                try {
                  if (avatar) localStorage.setItem(`snapsa_avatar_${uid}`, avatar);
                  else localStorage.removeItem(`snapsa_avatar_${uid}`);
                } catch (e) {
                  
                  console.warn('[avatar] localStorage persist failed:', e.message);
                }
                showToast?.(avatar ? '✅ Photo updated!' : 'Photo removed', 'success');
              }} 
              onClose={() => setShowAvatarModal(false)}
            />
            </ScreenErrorBoundary>
          </motion.div>
        )}
        {showGoLive && (
            <ScreenErrorBoundary>
            <GoLiveScreen
              currentUser={currentUser}
              showToast={showToast}
              onClose={() => setShowGoLive(false)}
              onStart={(brandId) => {
                setShowGoLive(false);
                initializeLiveStream(brandId);
              }}
            />
            </ScreenErrorBoundary>
          )}
       {showLive && isBroadcasting && (
          <motion.div
            key="live-system"
            initial={{ opacity: 0, y: '100%' }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: '100%' }}
            transition={{ type: 'spring', damping: 30, stiffness: 300 }}
            style={{ position: 'absolute', inset: 0, zIndex: 100 }}
          >
            <ScreenErrorBoundary>
              <React.Suspense fallback={<div style={{ width:'100%', height:'100%', background:'#000', display:'flex', alignItems:'center', justifyContent:'center' }}><NeonLoader label="Starting live…"/></div>}>
              <LiveStreamSystem
                isBroadcaster={true}
                currentUser={currentUser}
                apiInstance={snapApiInstance}
                onClose={handleLiveClose}
                channelName={streamChannel}
                featuredBrand={liveFeaturedBrand ? [liveFeaturedBrand] : null}
              />
              </React.Suspense>
            </ScreenErrorBoundary>
          </motion.div>
        )}
        <AnimatePresence>
          {showLiveStats && liveStats && (
            <LiveStatsModal
              stats={liveStats}
              onClose={() => { setShowLiveStats(false); setLiveStats(null); }}
            />
          )}
        </AnimatePresence>
        {quickPlayVideo && (
          <motion.div key="qp" initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}
            style={{ position:'fixed', inset:0, zIndex:400, background:'#000' }}>
            <ScreenErrorBoundary>
            <FeedScreen
              singleVideo={quickPlayVideo}
              currentUser={currentUser}
              onViewProfile={handleViewProfile}
              showToast={showToast}
              overlayOpen={false}
              onOpenProductStore={setProductStoreTarget}
            />
            </ScreenErrorBoundary>
            <button onClick={()=>setQuickPlayVideo(null)}
              style={{ position:'absolute', top:48, left:16, zIndex:500, background:'rgba(0,0,0,0.6)', border:'none', borderRadius:'50%', padding:10, cursor:'pointer' }}>
              <X size={20} style={{ color:'white' }}/>
            </button>
          </motion.div>
        )}
        {showUsernameModal && <ScreenErrorBoundary><UsernameModalInline current={snapsaUsername} onSave={saveUsername} onClose={()=>setShowUsernameModal(false)}/></ScreenErrorBoundary>}
        {showBioModal && <ScreenErrorBoundary><BioModalInline current={snapsaBio} onSave={saveBio} onClose={()=>setShowBioModal(false)}/></ScreenErrorBoundary>}
        {showNameModal && <ScreenErrorBoundary><NameModalInline current={snapsaName} suggestion={wernjatFullName(userData, currentUser)} onSave={saveName} onClose={()=>setShowNameModal(false)}/></ScreenErrorBoundary>}
      </AnimatePresence>
    </motion.div>
  );
};

const SNAPSA_VISITOR_KEY = 'snapsa_visitor_id';
const SNAPSA_VISIT_CHOICE_KEY = 'snapsa_visit_choice';

const VisitTracker = () => {
  const [showNotice, setShowNotice] = useState(false);

  useEffect(() => {
    let choice = null;
    try { choice = localStorage.getItem(SNAPSA_VISIT_CHOICE_KEY); } catch { return undefined; }
    if (navigator.doNotTrack === '1' || choice === 'no') return undefined;
    if (!choice) setShowNotice(true);

    let vid = null;
    try {
      vid = localStorage.getItem(SNAPSA_VISITOR_KEY);
      if (!vid) {
        vid = (globalThis.crypto?.randomUUID ? globalThis.crypto.randomUUID() : `v${Date.now().toString(36)}${Math.random().toString(36).slice(2, 14)}`)
          .replace(/[^A-Za-z0-9_-]/g, '');
        localStorage.setItem(SNAPSA_VISITOR_KEY, vid);
      }
    } catch { return undefined; }
    if (!vid || vid.length < 16) return undefined;

    let referrer = '';
    try {
      const h = document.referrer ? new URL(document.referrer).hostname : '';
      referrer = h && h !== window.location.hostname ? h : '';
    } catch {}
    let invite = '';
    try { invite = new URLSearchParams(window.location.search).get('snapsa_ref') || ''; } catch {}

    const ping = () => {
      try { if (localStorage.getItem(SNAPSA_VISIT_CHOICE_KEY) === 'no') return; } catch {}
      if (document.visibilityState === 'hidden') return;
      snapFetch('/snapsa/visit', { method: 'POST', body: JSON.stringify({ vid, referrer, invite }) }).catch(() => {});
    };
    ping();
    const timer = setInterval(ping, 120000);
    return () => clearInterval(timer);
  }, []);

  const choose = (value) => {
    try { localStorage.setItem(SNAPSA_VISIT_CHOICE_KEY, value); } catch {}
    setShowNotice(false);
  };
  if (!showNotice) return null;
  return (
    <div style={{ position:'fixed', left:12, right:12, bottom:84, zIndex:8000, maxWidth:420, margin:'0 auto', background:S.card, border:`1px solid ${S.border}`, borderRadius:14, padding:'12px 14px', display:'flex', alignItems:'center', gap:10 }}>
      <p style={{ flex:1, color:S.gray, fontSize:12, margin:0 }}>Snapsa counts anonymous visits to improve the app. No names or IP addresses are stored.</p>
      <button onClick={() => choose('no')} style={{ background:'none', border:'none', color:S.gray, fontSize:12, fontWeight:700, cursor:'pointer' }}>No thanks</button>
      <button onClick={() => choose('ok')} style={{ background:S.pink, border:'none', borderRadius:999, color:'white', fontSize:12, fontWeight:700, padding:'7px 14px', cursor:'pointer' }}>OK</button>
    </div>
  );
};

export const SnapsaApp = (props) => (
  <LanguageProvider>
    <SnapsaAppInner {...props}/>
    <AccountRestrictedOverlay/>   
    <VisitTracker/>
    <DownloadPrompt/>
  </LanguageProvider>
);

export default SnapsaApp;
